  const query = useFileSystem(path);
  return {
    ...query,
    data: query.data
      ? {
          path: query.data.current || path || "/",
          parent: query.data.parent,
          entries: (query.data.directories || []).map((d) => ({
            name: d.name,
            path: d.path,
            isDirectory: true,
            size: d.size,
          })),
        }
      : undefined,
  };
