                  style={{
                    fontSize: "0.7rem",
                    padding: "0.15rem 0.5rem",
                    borderRadius: "9999px",
                    backgroundColor: "rgba(35, 40, 75, 0.8)",
                    color: "#C7C5D3",
                    border: "none",
                    cursor: "pointer",
                    whiteSpace: "nowrap",
                  }}
                >
                  {t("copilot.speedTips")}
                </button>
                <button
                  onClick={() =>
                    setInputMessage(
                      "Explain what Endgame mode and Rarest-First piece picking do in Seedarr.",
