                  }
                  style={{
                    fontSize: "0.7rem",
                    padding: "0.15rem 0.5rem",
                    borderRadius: "9999px",
                    backgroundColor: "rgba(35, 40, 75, 0.8)",
                    color: "#C7C5D3",
                    border: "none",
                    cursor: "pointer",
                    whiteSpace: "nowrap",
                  }}
                >
                  {t("copilot.piecePickers")}
                </button>
                <button
                  onClick={() =>
                    setInputMessage(
                      "How does VPN kill switch and interface binding work?",
                    )
                  }
                  style={{
                    fontSize: "0.7rem",
                    padding: "0.15rem 0.5rem",
                    borderRadius: "9999px",
                    backgroundColor: "rgba(35, 40, 75, 0.8)",
                    color: "#C7C5D3",
                    border: "none",
                    cursor: "pointer",
                    whiteSpace: "nowrap",
                  }}
                >
                  {t("copilot.vpnSecurity")}
                </button>
              </div>

              {/* Messages Container */}
              <div
                style={{
                  flex: 1,
                  padding: "0.75rem",
                  overflowY: "auto",
                  display: "flex",
                  flexDirection: "column",
                  gap: "0.6rem",
                }}
              >
                {messages.map((msg) => (
                  <div
                    key={msg.id}
                    style={{
                      display: "flex",
                      alignItems: "flex-start",
                      gap: "0.5rem",
                      flexDirection:
                        msg.sender === "user" ? "row-reverse" : "row",
