                        borderRadius: "50%",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        backgroundColor:
                          msg.sender === "user" ? "#FFD166" : "#23284B",
                        color: msg.sender === "user" ? "#10111A" : "#FFD166",
                        flexShrink: 0,
                      }}
                    >
                      {msg.sender === "user" ? (
                        <UserIcon size={13} />
                      ) : (
                        <BotIcon size={13} />
                      )}
                    </div>

                    <div
                      style={{
                        maxWidth: "85%",
                        padding: "0.5rem 0.75rem",
                        borderRadius: "8px",
                        fontSize: "0.75rem",
                        lineHeight: 1.4,
                        backgroundColor:
                          msg.sender === "user"
                            ? "#FFD166"
                            : "var(--bg-secondary, #171B35)",
                        color:
                          msg.sender === "user"
                            ? "#10111A"
                            : "var(--text-primary, #F8F4ED)",
                        border:
                          msg.sender === "user"
                            ? "none"
                            : "1px solid var(--border-light)",
                        fontWeight: msg.sender === "user" ? 600 : 400,
                      }}
                    >
                      <p style={{ margin: 0, whiteSpace: "pre-wrap" }}>
                        {msg.text}
                      </p>
                      <div
                        style={{
                          display: "flex",
