                  <SendIcon size={14} />
                </button>
              </form>
            </div>
          )}

          {/* Tab Content: Parse Release */}
          {activeTab === "parse" && (
            <div
              style={{
                flex: 1,
                padding: "0.75rem",
                overflowY: "auto",
                display: "flex",
                flexDirection: "column",
                gap: "0.75rem",
