        title: t(
          "modals.gettingStarted.stepWelcomeTitle",
          undefined,
          "Welcome to Seedarr",
        ),
      },
      {
        id: "client",
        stepNum: 1,
        icon: "📥",
        shortName: t(
          "modals.gettingStarted.stepClient",
          undefined,
          "Download Client",
        ),
        title: t(
          "modals.gettingStarted.stepClientTitle",
          undefined,
          "Add Download Client",
        ),
      },
      {
        id: "prowlarr",
        stepNum: 2,
        icon: "🔍",
        shortName: t(
          "modals.gettingStarted.stepProwlarr",
          undefined,
          "Prowlarr",
        ),
        title: t(
          "modals.gettingStarted.stepProwlarrTitle",
          undefined,
          "Add Indexer",
        ),
      },
      {
        id: "sonarr",
        stepNum: 3,
        icon: "📺",
        shortName: t("modals.gettingStarted.stepSonarr", undefined, "Sonarr"),
        title: t(
          "modals.gettingStarted.stepSonarrTitle",
          undefined,
          "Add Connection",
        ),
      },
      {
        id: "radarr",
        stepNum: 4,
        icon: "🎬",
        shortName: t("modals.gettingStarted.stepRadarr", undefined, "Radarr"),
        title: t(
          "modals.gettingStarted.stepRadarrTitle",
          undefined,
          "Add Connection",
        ),
      },
      {
        id: "lidarr",
        stepNum: 5,
        icon: "🎵",
        shortName: t("modals.gettingStarted.stepLidarr", undefined, "Lidarr"),
        title: t(
          "modals.gettingStarted.stepLidarrTitle",
          undefined,
          "Add Connection",
        ),
      },
      {
        id: "storage",
        stepNum: 6,
        icon: "💾",
        shortName: t("modals.gettingStarted.stepStorage", undefined, "Storage"),
        title: t(
          "modals.gettingStarted.stepStorageTitle",
          undefined,
          "Storage & Downloads",
        ),
      },
      {
        id: "finish",
        stepNum: 7,
        icon: "🎉",
        shortName: t(
          "modals.gettingStarted.stepFinished",
          undefined,
          "Finished",
        ),
        title: t(
          "modals.gettingStarted.stepFinishedTitle",
          undefined,
          "Setup Complete",
        ),
      },
    ],
    [t],
  );

  // Download Client Form State
  const [clientForm, setClientForm] = useState<
    Partial<DownloadClientDefinition>
  >({
    name: "My qBittorrent",
    clientType: "QBitTorrent",
    host: "localhost",
    port: 8080,
    useSsl: false,
    username: "",
    password: "",
    category: "",
    enable: true,
  });
  const [clientTestResult, setClientTestResult] =
    useState<DownloadClientTestResult | null>(null);
  const [clientSaved, setClientSaved] = useState(false);

  // Prowlarr Indexer Form State
  const [indexerForm, setIndexerForm] = useState<Partial<IndexerDefinition>>({
    name: "Prowlarr",
    indexerType: "Prowlarr",
    url: "http://prowlarr:9696",
    apiKey: "",
    apiPath: "/api",
    categories: "2000,5000",
    enable: true,
    enableRss: true,
    enableSearch: true,
  });
  const [indexerTestResult, setIndexerTestResult] =
    useState<IndexerTestResult | null>(null);
  const [indexerSaved, setIndexerSaved] = useState(false);

  // Sonarr Form State
  const [sonarrForm, setSonarrForm] = useState<Partial<ArrConnection>>({
    name: "Sonarr",
    arrType: "Sonarr",
    url: "http://localhost:8989",
    apiKey: "",
    enable: true,
    syncEnabled: true,
    enableAutomaticAdd: true,
    webhookEnabled: true,
    webhookHost: "seedarr",
  });
  const [sonarrTestResult, setSonarrTestResult] =
    useState<ArrTestResult | null>(null);
  const [sonarrSaved, setSonarrSaved] = useState(false);

  // Radarr Form State
  const [radarrForm, setRadarrForm] = useState<Partial<ArrConnection>>({
    name: "Radarr",
    arrType: "Radarr",
    url: "http://localhost:7878",
    apiKey: "",
    enable: true,
    syncEnabled: true,
    enableAutomaticAdd: true,
    webhookEnabled: true,
    webhookHost: "seedarr",
  });
  const [radarrTestResult, setRadarrTestResult] =
    useState<ArrTestResult | null>(null);
  const [radarrSaved, setRadarrSaved] = useState(false);

  // Lidarr Form State
  const [lidarrForm, setLidarrForm] = useState<Partial<ArrConnection>>({
    name: "Lidarr",
    arrType: "Lidarr",
    url: "http://localhost:8686",
    apiKey: "",
    enable: true,
    syncEnabled: true,
    enableAutomaticAdd: true,
    webhookEnabled: true,
    webhookHost: "seedarr",
  });
  const [lidarrTestResult, setLidarrTestResult] =
    useState<ArrTestResult | null>(null);
  const [lidarrSaved, setLidarrSaved] = useState(false);

  // Category & Storage Hooks / State
  const { data: categories } = useCategories();
  const { data: diskSpace } = useDiskSpace();
  const { data: generalConfig } = useGeneralConfig();
  const createCategoryMutation = useCreateCategory();
  const updateCategoryMutation = useUpdateCategory();
  const saveGeneralConfigMutation = useSaveGeneralConfig();

  const [storageForm, setStorageForm] = useState({
    defaultDownloadPath: "/downloads",
    completedPath: "/downloads/completed",
    watchFolderPath: "",
  });
  const [isValidatingPath, setIsValidatingPath] = useState(false);
  const [pathValidationResult, setPathValidationResult] = useState<{
    success: boolean;
    message?: string;
  } | null>(null);
  const [storageSaved, setStorageSaved] = useState(false);
  const [isSavingStorage, setIsSavingStorage] = useState(false);
  // Pre-fill storage paths if already configured in backend
  useEffect(() => {
    const defaultCat = categories?.find(
      (c) => c.isDefault || c.name.toLowerCase() === "default",
    );
    if (defaultCat?.savePath) {
      setStorageForm((prev) => ({
        ...prev,
        defaultDownloadPath: defaultCat.savePath || prev.defaultDownloadPath,
      }));
    }
  }, [categories]);

  useEffect(() => {
    if (generalConfig?.watchFolderPath) {
      setStorageForm((prev) => ({
        ...prev,
        watchFolderPath: generalConfig.watchFolderPath,
      }));
    }
  }, [generalConfig?.watchFolderPath]);

  // Per-step error banners
  const [clientError, setClientError] = useState<string | null>(null);
  const [indexerError, setIndexerError] = useState<string | null>(null);
  const [sonarrError, setSonarrError] = useState<string | null>(null);
  const [radarrError, setRadarrError] = useState<string | null>(null);
  const [lidarrError, setLidarrError] = useState<string | null>(null);
  const [storageError, setStorageError] = useState<string | null>(null);

  // API Mutations
  const testClientMutation = useTestDirectDownloadClient();
  const createClientMutation = useCreateDownloadClient();

  const testIndexerMutation = useTestDirectIndexer();
  const createIndexerMutation = useCreateIndexer();

  const testArrMutation = useTestDirectArrConnection();
  const createArrMutation = useCreateArrConnection();

  const currentStepRef = useRef(currentStep);
  currentStepRef.current = currentStep;
  const dontShowAgainRef = useRef(dontShowAgain);
  dontShowAgainRef.current = dontShowAgain;

  const handleClose = useCallback(
    (_explicitDismissal = false) => {
      localStorage.setItem(STORAGE_KEY_HIDE_GUIDE, "true");
      setDontShowAgain(true);
      onClose();
    },
    [onClose],
  );

  useEffect(() => {
    if (!isOpen) return;
    apiClient
      .getSetupStatus()
      .then((status) => {
        if (status.isSetupCompleted) {
          localStorage.setItem(STORAGE_KEY_HIDE_GUIDE, "true");
          setDontShowAgain(true);
          onClose();
        }
      })
      .catch(() => {
        // ignore
      });
  }, [isOpen, onClose]);

  const handleFinish = async (targetPath?: string) => {
    localStorage.setItem(STORAGE_KEY_HIDE_GUIDE, "true");
    setDontShowAgain(true);
    try {
      await apiClient.completeSetup({});
    } catch {
      // ignore
    }
    handleClose(true);
    if (targetPath) {
      navigate(targetPath);
    }
  };

  const modalRef = useFocusTrap<HTMLDivElement>({
    isOpen,
    onEscape: () => handleClose(true),
  });

  useModalRegistration({
    id: "getting-started-modal",
    isOpen,
    onClose: () => handleClose(true),
    modalRef,
  });

  if (!isOpen) return null;

  const handleDontShowChange = (checked: boolean) => {
    setDontShowAgain(checked);
    if (checked) {
      localStorage.setItem(STORAGE_KEY_HIDE_GUIDE, "true");
    } else {
      localStorage.setItem(STORAGE_KEY_HIDE_GUIDE, "false");
    }
  };

  const clearAllErrors = () => {
    setClientError(null);
    setIndexerError(null);
    setSonarrError(null);
    setRadarrError(null);
    setLidarrError(null);
    setStorageError(null);
  };

  const handleNext = () => {
    clearAllErrors();
    if (currentStep < steps.length - 1) {
      setCurrentStep((p) => p + 1);
    } else {
      localStorage.setItem(STORAGE_KEY_HIDE_GUIDE, "true");
      setDontShowAgain(true);
      handleFinish();
    }
  };

  const handlePrev = () => {
    clearAllErrors();
    if (currentStep > 0) {
      setCurrentStep((p) => p - 1);
    }
  };

  const isReadOnly = mode === "readonly";

  // Client Defaults helper
  const clientDefaults: Record<string, { port: number }> = {
    QBitTorrent: { port: 8080 },
    Transmission: { port: 9091 },
    Deluge: { port: 8112 },
  };

  // Test Connection Handlers
  const handleTestClient = () => {
    setClientError(null);
    setClientTestResult(null);
    const validation = validateClientConfig(clientForm);
    if (!validation.valid) {
      setClientError(validation.error || "Invalid client configuration");
      return;
    }
    testClientMutation.mutate(clientForm, {
      onSuccess: (data) => setClientTestResult(data),
      onError: (err) =>
        setClientTestResult({ success: false, message: err.message }),
    });
  };

  const handleSaveClient = () => {
    setClientError(null);
    const validation = validateClientConfig(clientForm);
    if (!validation.valid) {
      setClientError(validation.error || "Invalid client configuration");
      return;
    }
    createClientMutation.mutate(
      {
        ...clientForm,
        name:
          clientForm.name?.trim() ||
          clientForm.clientType ||
          t("modals.gettingStarted.stepClient", undefined, "Download Client"),
        implementation: `${clientForm.clientType || "QBitTorrent"}DownloadClient`,
        configContract: "DownloadClientDefinition",
      },
      {
        onSuccess: () => {
          setClientSaved(true);
          handleNext();
        },
        onError: (err) => {
          setClientError(
            err.message ||
              t(
                "modals.gettingStarted.saveClientFailed",
                undefined,
                "Failed to save download client. Please verify connection parameters.",
              ),
          );
        },
      },
    );
  };

  const handleTestIndexer = () => {
    setIndexerError(null);
    setIndexerTestResult(null);
    const validation = validateIndexerConfig(
      indexerForm,
      mode === "interactive",
    );
    if (!validation.valid) {
      setIndexerError(validation.error || "Invalid indexer configuration");
      return;
    }
    testIndexerMutation.mutate(indexerForm, {
      onSuccess: (data) => setIndexerTestResult(data),
      onError: (err) =>
        setIndexerTestResult({ success: false, message: err.message }),
    });
  };

  const handleSaveIndexer = () => {
    setIndexerError(null);
    const validation = validateIndexerConfig(
      indexerForm,
      mode === "interactive",
    );
    if (!validation.valid) {
      setIndexerError(validation.error || "Invalid indexer configuration");
      return;
    }
    createIndexerMutation.mutate(
      {
        ...indexerForm,
        name: indexerForm.name?.trim() || "Prowlarr",
        implementation: `${indexerForm.indexerType || "Prowlarr"}Indexer`,
        configContract: "IndexerDefinition",
      },
      {
        onSuccess: () => {
          setIndexerSaved(true);
          handleNext();
        },
        onError: (err) => {
          setIndexerError(
            err.message ||
              t(
                "modals.gettingStarted.saveIndexerFailed",
                undefined,
                "Failed to save indexer. Please verify host and API key.",
              ),
          );
        },
      },
    );
  };

  const handleTestArr = (
    form: Partial<ArrConnection>,
    setResult: (res: ArrTestResult | null) => void,
    setError: (err: string | null) => void,
  ) => {
    setError(null);
    setResult(null);
    const validation = validateArrConfig(form, mode === "interactive");
    if (!validation.valid) {
      setError(validation.error || "Invalid connection configuration");
      return;
    }
    testArrMutation.mutate(form, {
      onSuccess: (data) => setResult(data),
      onError: (err) => setResult({ success: false, message: err.message }),
    });
  };

  const handleSaveArr = (
    form: Partial<ArrConnection>,
    setSaved: (saved: boolean) => void,
    setError: (err: string | null) => void,
    arrType: string,
  ) => {
    setError(null);
    const validation = validateArrConfig(form, mode === "interactive");
    if (!validation.valid) {
      setError(validation.error || `Invalid ${arrType} configuration`);
      return;
    }
    createArrMutation.mutate(
      {
        ...form,
        arrType,
        name: form.name?.trim() || arrType,
        implementation: `${arrType}Connection`,
        configContract: "ArrConnectionDefinition",
      },
      {
        onSuccess: () => {
          setSaved(true);
          handleNext();
        },
        onError: (err) => {
          setError(
            err.message ||
              t(
                "modals.gettingStarted.saveArrFailed",
                undefined,
                `Failed to save ${arrType} connection. Please verify credentials.`,
              ),
          );
        },
      },
    );
  };

  // Storage Handlers
  const handleValidateStoragePath = async () => {
    setPathValidationResult(null);
    setStorageError(null);
    const validation = validateStorageConfig(storageForm);
    if (!validation.valid) {
      setStorageError(validation.error || "Invalid storage path");
      return;
    }

    setIsValidatingPath(true);
    try {
      const res = await apiClient.post<{
        isValid: boolean;
        errorMessage?: string;
      }>("/filesystem/validate", {
        path: storageForm.defaultDownloadPath.trim(),
        testWrite: true,
      });
      if (res.isValid) {
        setPathValidationResult({
          success: true,
          message: `Directory verified: write permissions confirmed for "${storageForm.defaultDownloadPath.trim()}"`,
        });
      } else {
        setPathValidationResult({
          success: false,
          message:
            res.errorMessage ||
            "Directory is not writable or cannot be accessed.",
        });
      }
    } catch (err: any) {
      setPathValidationResult({
        success: false,
        message: err?.message || "Validation failed or directory not found.",
      });
    } finally {
      setIsValidatingPath(false);
    }
  };

  const handleSaveStorage = async () => {
    setStorageError(null);
    const validation = validateStorageConfig(storageForm);
    if (!validation.valid) {
      setStorageError(validation.error || "Invalid storage configuration");
      return;
    }

    setIsSavingStorage(true);
    try {
      const defaultCat = categories?.find(
        (c) => c.isDefault || c.name.toLowerCase() === "default",
      );
      if (defaultCat) {
        await updateCategoryMutation.mutateAsync({
          id: defaultCat.id,
          data: {
            ...defaultCat,
            savePath: storageForm.defaultDownloadPath.trim(),
          },
        });
      } else {
        await createCategoryMutation.mutateAsync({
          name: "Default",
          savePath: storageForm.defaultDownloadPath.trim(),
          isDefault: true,
        });
      }

      if (storageForm.watchFolderPath?.trim() && generalConfig) {
        await saveGeneralConfigMutation.mutateAsync({
          ...generalConfig,
          watchFolderEnabled: true,
          watchFolderPath: storageForm.watchFolderPath.trim(),
        });
      }

      setStorageSaved(true);
      handleNext();
    } catch (err: any) {
      setStorageError(
        err?.message ||
          t(
            "modals.gettingStarted.saveStorageFailed",
            undefined,
            "Failed to save storage configuration.",
          ),
      );
    } finally {
      setIsSavingStorage(false);
    }
  };

  // Helper for rendering connection test feedback alert
  const renderTestAlert = (
    isPending: boolean,
    result: { success: boolean; message?: string } | null,
    targetName: string,
  ) => {
    if (isPending) {
      return (
        <div
          style={{
            marginTop: "1rem",
            padding: "0.75rem 1rem",
            borderRadius: "6px",
            fontSize: "0.875rem",
            backgroundColor: "rgba(200, 168, 78, 0.12)",
            color: "var(--accent, #c8a84e)",
            border: "1px solid rgba(200, 168, 78, 0.35)",
            display: "flex",
            alignItems: "center",
            gap: "0.5rem",
          }}
        >
          <span>
            {t(
              "modals.gettingStarted.testingTo",
              { target: targetName },
              `Testing connection to ${targetName}...`,
            )}
          </span>
        </div>
      );
    }

    if (result) {
      return (
        <div
          style={{
            marginTop: "1rem",
            padding: "0.75rem 1rem",
            borderRadius: "6px",
            fontSize: "0.875rem",
            lineHeight: "1.4",
            display: "flex",
            alignItems: "flex-start",
            gap: "0.65rem",
            backgroundColor: result.success
              ? "rgba(40, 167, 69, 0.15)"
              : "rgba(220, 53, 69, 0.15)",
            color: result.success
              ? "var(--success, #28a745)"
              : "var(--danger, #dc3545)",
            border: `1px solid ${
              result.success
                ? "rgba(40, 167, 69, 0.35)"
                : "rgba(220, 53, 69, 0.35)"
            }`,
          }}
        >
          <span
            style={{ fontWeight: "bold", fontSize: "1.1rem", lineHeight: "1" }}
          >
            {result.success ? "✓" : "✕"}
          </span>
          <div style={{ flex: 1 }}>
            <div style={{ fontWeight: 600 }}>
              {result.success
                ? t(
                    "modals.gettingStarted.connectionSuccess",
                    undefined,
                    "Connection Successful",
                  )
                : t(
                    "modals.gettingStarted.connectionFailed",
                    undefined,
                    "Connection Failed",
                  )}
            </div>
            {result.message && (
              <div
                style={{
                  marginTop: "0.25rem",
                  opacity: 0.95,
                  wordBreak: "break-word",
                }}
              >
                {result.message}
              </div>
            )}
          </div>
        </div>
      );
    }

    return null;
  };

  const renderErrorBanner = (error: string | null) => {
    if (!error) return null;
    return (
      <div
        role="alert"
        aria-live="assertive"
        style={{
          marginTop: "1rem",
          padding: "0.75rem 1rem",
          borderRadius: "6px",
          fontSize: "0.875rem",
          lineHeight: "1.4",
          display: "flex",
          alignItems: "flex-start",
          gap: "0.65rem",
          backgroundColor: "rgba(220, 53, 69, 0.15)",
          color: "var(--danger, #dc3545)",
          border: "1px solid rgba(220, 53, 69, 0.35)",
        }}
      >
        <span
          style={{ fontWeight: "bold", fontSize: "1.1rem", lineHeight: "1" }}
        >
          ✕
        </span>
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 600 }}>
            {t(
              "modals.gettingStarted.validationErrorTitle",
              undefined,
              "Configuration Error",
            )}
          </div>
          <div
            style={{
              marginTop: "0.25rem",
              opacity: 0.95,
              wordBreak: "break-word",
            }}
          >
            {error}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div
      ref={modalRef}
      className="modal-overlay"
      role="dialog"
      aria-modal="true"
      aria-labelledby="getting-started-modal-title"
      tabIndex={-1}
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: "rgba(10, 11, 18, 0.85)",
        backdropFilter: "blur(6px)",
        WebkitBackdropFilter: "blur(6px)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 9999,
        padding: "1rem",
      }}
      onClick={(e) => {
        if (e.target === e.currentTarget) handleClose(true);
      }}
    >
      <div
        className="modal"
        onClick={(e) => e.stopPropagation()}
        style={{
          maxWidth: 540,
          width: "92vw",
          maxHeight: "90vh",
          overflowY: "auto",
