describe("MediaArtwork: Fallback and Error Handling", () => {
  it("renders client-side CSS fallback container when state is error", () => {
    const html = renderToStaticMarkup(
      React.createElement(MediaArtwork, {
        src: "https://broken.invalid/poster.jpg",
        title: "Interstellar",
        category: "radarr",
        initialState: "error",
      }),
    );

    assert.ok(
      html.includes("media-artwork-fallback"),
      "Must render fallback container",
    );
    assert.ok(
      !html.includes("<img"),
      "Must NOT render broken img tag in error state",
    );
    assert.ok(html.includes("🎬"), "Must render category glyph for radarr");
    assert.ok(
      html.includes("Interstellar"),
      "Must render title in non-compact fallback",
    );
  });

  it("uses custom fallbackIcon when provided", () => {
    const html = renderToStaticMarkup(
      React.createElement(MediaArtwork, {
        title: "Special Item",
        category: "radarr",
        fallbackIcon: "⭐",
        initialState: "error",
      }),
    );

    assert.ok(html.includes("media-artwork-fallback"));
    assert.ok(html.includes("⭐"), "Must use custom fallbackIcon");
    assert.ok(
      !html.includes("🎬"),
      "Must not use default glyph when custom fallbackIcon is set",
    );
  });

  it("renders compact 20x28 fallback thumbnail without title overflow", () => {
    const html = renderToStaticMarkup(
      React.createElement(MediaArtwork, {
        title:
          "Very Long Torrent Name That Should Not Render In Table Thumbnail",
        category: "radarr",
        width: "20px",
        height: "28px",
        aspectRatio: "auto",
        borderRadius: "2px",
        initialState: "error",
      }),
    );

    assert.ok(html.includes("media-artwork-fallback"));
    assert.ok(html.includes("🎬"), "Must render glyph");
    assert.ok(
      html.includes("font-size:0.85rem"),
      "Must use compact font size for width <= 30",
    );
    assert.ok(
      !html.includes("media-artwork-title"),
      "Must NOT render title element in compact table thumbnail",
    );
    assert.ok(
      !html.includes(">Very Long Torrent Name"),
      "Must NOT render title text element in compact table thumbnail",
    );
  });

  it("renders retry button when allowRetry is enabled in error state", () => {
    const html = renderToStaticMarkup(
      React.createElement(MediaArtwork, {
        title: "Inception",
        category: "radarr",
        allowRetry: true,
        initialState: "error",
      }),
    );

    assert.ok(
      html.includes("media-artwork-retry-btn"),
      "Must render retry button",
    );
    assert.ok(html.includes('aria-label="Retry loading artwork"'));
    assert.ok(html.includes("↻"), "Must show retry icon");
  });

  it("does NOT render retry button when allowRetry is disabled", () => {
    const html = renderToStaticMarkup(
      React.createElement(MediaArtwork, {
        title: "Inception",
        category: "radarr",
        allowRetry: false,
        initialState: "error",
      }),
    );

    assert.ok(!html.includes("media-artwork-retry-btn"));
  });
});

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import {
  isPlayableFile,
  buildStreamUrl,
  buildDownloadUrl,
  buildExternalPlayerUrl,
  getAbsoluteUrl,
  cleanUpMediaElement,
  setSubtitleTrackActive,
  getCodecErrorMessage,
} from "../utils/mediaPlayer";
import type { SubtitleTrack, Torrent } from "../api/types";

describe("MediaPlayerModal: Core Component Contract & Behaviors", () => {
  const mockTorrent: Pick<Torrent, "id" | "name" | "mediaTitle"> = {
    id: 10,
    name: "Big.Buck.Bunny.1080p.HEVC.mkv",
    mediaTitle: "Big Buck Bunny",
  };

  const mockVideoFile = {
    id: 42,
    path: "Big.Buck.Bunny.1080p.HEVC.mkv",
    size: 276_000_000,
  };

  it("constructs correct stream URL and download URL for media player modal", () => {
    const stream = buildStreamUrl(mockTorrent.id, mockVideoFile.id);
    const download = buildDownloadUrl(mockTorrent.id, mockVideoFile.id);

    assert.equal(stream, "/api/v1/torrent/10/files/42/stream");
    assert.equal(download, "/api/v1/torrent/10/files/42/download");
  });

  it("constructs external player links (VLC, MPV) with full origin", () => {
    const stream = buildStreamUrl(mockTorrent.id, mockVideoFile.id);
    const vlc = buildExternalPlayerUrl("vlc", stream, "http://localhost:5000");
    const mpv = buildExternalPlayerUrl("mpv", stream, "http://localhost:5000");

    assert.equal(
      vlc,
      "vlc://http://localhost:5000/api/v1/torrent/10/files/42/stream",
    );
    assert.equal(
      mpv,
      "web+mpv://http://localhost:5000/api/v1/torrent/10/files/42/stream",
    );
  });

  it("cleans up media pipeline on unmount (pause, remove src, load)", () => {
    const calls: string[] = [];
    const mediaEl: any = {
      pause() {
        calls.push("pause");
      },
      removeAttribute(attr: string) {
        calls.push(`removeAttribute:${attr}`);
      },
      removeChild() {},
      firstChild: null,
      load() {
        calls.push("load");
      },
    };

    cleanUpMediaElement(mediaEl);

    assert.deepEqual(calls, ["pause", "removeAttribute:src", "load"]);
  });

  it("handles codec errors with MEDIA_ERR_SRC_NOT_SUPPORTED code 4 by providing descriptive error and player fallbacks", () => {
    const errMessage = getCodecErrorMessage(4, mockVideoFile.path);

    assert.ok(
      errMessage.includes("cannot decode this media codec"),
      "Should explain browser decode failure",
    );
    assert.ok(
      errMessage.includes("HEVC / H.265 video"),
      "Should identify HEVC video",
    );
    assert.ok(
      errMessage.includes("Matroska (.mkv) container"),
      "Should identify MKV container",
    );
  });

  it("dynamically manages multiple subtitle tracks and toggles track modes", () => {
    const tracks: any = [
      { mode: "disabled", label: "English", language: "en" },
      { mode: "disabled", label: "Spanish", language: "es" },
    ];

    const subtitles: SubtitleTrack[] = [
      {
        trackId: 1,
        title: "English",
        language: "English",
        twoLetterCode: "en",
        format: "vtt",
        path: "subs/en.vtt",
        isExternal: false,
        isForced: false,
        isHearingImpaired: false,
        isDefault: true,
        url: "/api/v1/torrent/10/files/42/subtitles/1.vtt",
      },
      {
        trackId: 2,
        title: "Spanish",
        language: "Spanish",
        twoLetterCode: "es",
        format: "vtt",
        path: "subs/es.vtt",
        isExternal: true,
        isForced: false,
        isHearingImpaired: false,
        isDefault: false,
        url: "/api/v1/torrent/10/files/42/subtitles/2.vtt",
      },
    ];

    // Select Spanish
    setSubtitleTrackActive(tracks, 2, subtitles);
    assert.equal(tracks[0].mode, "disabled");
    assert.equal(tracks[1].mode, "showing");

    // Turn off
    setSubtitleTrackActive(tracks, "off", subtitles);
    assert.equal(tracks[0].mode, "disabled");
    assert.equal(tracks[1].mode, "disabled");
  });
});

import React, {
  useRef,
  useEffect,
  useState,
  useMemo,
  useCallback,
} from "react";
import { useTranslation } from "../i18n";
import { useFocusTrap } from "../hooks/useFocusTrap";
import { useModalRegistration } from "./ModalProvider";
import { useTorrentFileSubtitles } from "../api/hooks";
import type { SubtitleTrack, Torrent } from "../api/types";
import {
  isAudioFile,
  parseMediaBadges,
  buildStreamUrl,
  buildDownloadUrl,
  buildExternalPlayerUrl,
  getAbsoluteUrl,
  cleanUpMediaElement,
  setSubtitleTrackActive,
  getCodecErrorMessage,
} from "../utils/mediaPlayer";
import { trackMediaPreview } from "../utils/analytics";

export interface MediaPlayerModalProps {
  isOpen: boolean;
  onClose: () => void;
  torrent: Pick<Torrent, "id" | "name"> & Partial<Pick<Torrent, "mediaTitle">>;
  file: {
    id: number;
    path: string;
    name?: string;
    size?: number;
  };
  subtitles?: SubtitleTrack[];
}

export type SubtitleSize = "small" | "medium" | "large" | "x-large";

export function MediaPlayerModal({
  isOpen,
  onClose,
  torrent,
  file,
  subtitles: propSubtitles,
}: MediaPlayerModalProps) {
  const { t } = useTranslation();
  const videoRef = useRef<HTMLVideoElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);

  const [hasCodecError, setHasCodecError] = useState<boolean>(false);
  const [errorCode, setErrorCode] = useState<number | undefined>(undefined);
  const [copied, setCopied] = useState<boolean>(false);
  const [activeSubtitleTrackId, setActiveSubtitleTrackId] = useState<
    number | "off"
  >("off");
  const [subtitleSize, setSubtitleSize] = useState<SubtitleSize>("medium");

  const fileName = useMemo(() => {
    if (file.name) return file.name;
    const parts = file.path.replace(/\\/g, "/").split("/");
    return parts[parts.length - 1] || file.path;
  }, [file.name, file.path]);

  const isAudio = useMemo(() => isAudioFile(fileName), [fileName]);
  const mediaBadges = useMemo(
    () => parseMediaBadges(fileName, torrent.name),
    [fileName, torrent.name],
  );

  useEffect(() => {
    if (isOpen) {
      const ext = fileName.split(".").pop()?.toLowerCase() || "unknown";
      const mimeCat = isAudio
        ? "audio"
        : ext === "mp4"
          ? "video_mp4"
          : ext === "mkv"
            ? "video_mkv"
            : "video_other";
      trackMediaPreview(mimeCat);
    }
  }, [isOpen, isAudio, fileName]);

  const streamUrl = useMemo(
    () => buildStreamUrl(torrent.id, file.id),
    [torrent.id, file.id],
  );

  const downloadUrl = useMemo(
    () => buildDownloadUrl(torrent.id, file.id),
    [torrent.id, file.id],
  );

  const { data: fetchedSubtitles } = useTorrentFileSubtitles(
    isOpen ? torrent.id : undefined,
    isOpen ? file.id : undefined,
  );

  const resolvedSubtitles = useMemo(
    () => propSubtitles ?? fetchedSubtitles ?? [],
    [propSubtitles, fetchedSubtitles],
  );

  // Reset state when a new file or torrent is opened
  useEffect(() => {
    if (isOpen) {
      setHasCodecError(false);
      setErrorCode(undefined);
      setCopied(false);
      // Auto-select default subtitle if available
      const defaultSub = resolvedSubtitles.find((s) => s.isDefault);
      setActiveSubtitleTrackId(defaultSub ? defaultSub.trackId : "off");
    }
  }, [isOpen, file.id, torrent.id, resolvedSubtitles]);

  // Stream Lifecycle Cleanup on Unmount / Close:
  useEffect(() => {
    return () => {
      if (videoRef.current) {
        cleanUpMediaElement(videoRef.current);
      }
      if (audioRef.current) {
        cleanUpMediaElement(audioRef.current);
      }
    };
  }, []);

  const handleClose = useCallback(() => {
    if (videoRef.current) {
      cleanUpMediaElement(videoRef.current);
    }
    if (audioRef.current) {
      cleanUpMediaElement(audioRef.current);
    }
    onClose();
  }, [onClose]);

  const trapRef = useFocusTrap<HTMLDivElement>({
    isOpen,
    onEscape: handleClose,
    onClose: handleClose,
  });

  useModalRegistration({
    id: "media-player-modal",
    isOpen,
    onClose: handleClose,
    modalRef: trapRef,
  });

  // Handle HTMLMediaElement onError event
  const handleMediaError = useCallback(
    (e: React.SyntheticEvent<HTMLMediaElement, Event>) => {
      const target = e.currentTarget;
      const code = target.error?.code ?? 4;
      setErrorCode(code);
      setHasCodecError(true);
    },
    [],
  );

  // Subtitle track switching synchronization with HTML5 textTracks
  const handleSubtitleChange = useCallback(
    (val: string) => {
      if (val === "off") {
        setActiveSubtitleTrackId("off");
        if (videoRef.current) {
          setSubtitleTrackActive(
            videoRef.current.textTracks,
            "off",
            resolvedSubtitles,
          );
        }
      } else {
        const id = parseInt(val, 10);
        setActiveSubtitleTrackId(id);
        if (videoRef.current) {
          setSubtitleTrackActive(
            videoRef.current.textTracks,
            id,
            resolvedSubtitles,
          );
        }
      }
    },
    [resolvedSubtitles],
  );

  const handleCopyStreamUrl = useCallback(() => {
    const fullUrl = getAbsoluteUrl(streamUrl);
    if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(fullUrl).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2500);
      });
    }
  }, [streamUrl]);

  const handleRetryPlayback = useCallback(() => {
    setHasCodecError(false);
    setErrorCode(undefined);
    const media = videoRef.current ?? audioRef.current;
    if (media) {
      media.load();
      media.play().catch(() => {
        // Ignored
      });
    }
  }, []);

  // Keyboard Shortcuts: Space, Arrows, M, F, C, [/]
  useEffect(() => {
    if (!isOpen) return;

    const SPEED_STEPS = [0.75, 1, 1.25, 1.5, 2];

    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const tagName = target?.tagName?.toLowerCase();
      if (
        tagName === "input" ||
        tagName === "textarea" ||
        tagName === "select" ||
        target?.isContentEditable
      ) {
        return;
      }

      const media = videoRef.current ?? audioRef.current;
      if (!media) return;

      // Space: play/pause
      if (e.key === " " || e.code === "Space") {
        e.preventDefault();
        if (media.paused) {
          media.play().catch(() => {});
        } else {
          media.pause();
        }
        return;
      }

      // ArrowLeft / ArrowRight: seek -/+ 5s, with Shift 30s
      if (e.key === "ArrowLeft") {
        e.preventDefault();
        const delta = e.shiftKey ? 30 : 5;
        media.currentTime = Math.max(0, media.currentTime - delta);
        return;
      }
      if (e.key === "ArrowRight") {
        e.preventDefault();
        const delta = e.shiftKey ? 30 : 5;
        const dur = Number.isFinite(media.duration) ? media.duration : Infinity;
        media.currentTime = Math.min(dur, media.currentTime + delta);
        return;
      }

      // ArrowUp / ArrowDown: volume -/+ 5%
      if (e.key === "ArrowUp") {
        e.preventDefault();
        media.volume = Math.min(
          1,
          Math.round((media.volume + 0.05) * 100) / 100,
        );
        if (media.muted && media.volume > 0) media.muted = false;
        return;
      }
      if (e.key === "ArrowDown") {
        e.preventDefault();
        media.volume = Math.max(
          0,
          Math.round((media.volume - 0.05) * 100) / 100,
        );
        return;
      }

      // M / m: mute
      if (e.key === "m" || e.key === "M") {
        e.preventDefault();
        media.muted = !media.muted;
        return;
      }

      // F / f: fullscreen
      if (e.key === "f" || e.key === "F") {
        e.preventDefault();
        if (!document.fullscreenElement) {
          const targetEl = videoRef.current ?? trapRef.current;
          if (targetEl?.requestFullscreen) {
            targetEl.requestFullscreen().catch(() => {});
          }
        } else {
          if (document.exitFullscreen) {
            document.exitFullscreen().catch(() => {});
          }
        }
        return;
      }

      // C / c: cycle subtitles
      if (e.key === "c" || e.key === "C") {
        e.preventDefault();
        if (resolvedSubtitles.length > 0) {
          const options: (number | "off")[] = [
            "off",
            ...resolvedSubtitles.map((s) => s.trackId),
          ];
          const currentIdx = options.indexOf(activeSubtitleTrackId);
          const nextIdx = (currentIdx + 1) % options.length;
          const nextVal = options[nextIdx];
          handleSubtitleChange(String(nextVal));
        }
        return;
      }

      // [ / ]: speed 0.75x, 1x, 1.25x, 1.5x, 2x
      if (e.key === "[") {
        e.preventDefault();
        const currentRate = media.playbackRate;
        let nextRate = SPEED_STEPS[0];
        for (let i = SPEED_STEPS.length - 1; i >= 0; i--) {
          if (SPEED_STEPS[i] < currentRate - 0.05) {
            nextRate = SPEED_STEPS[i];
            break;
          }
        }
        media.playbackRate = nextRate;
        return;
      }
      if (e.key === "]") {
        e.preventDefault();
        const currentRate = media.playbackRate;
        let nextRate = SPEED_STEPS[SPEED_STEPS.length - 1];
        for (let i = 0; i < SPEED_STEPS.length; i++) {
          if (SPEED_STEPS[i] > currentRate + 0.05) {
            nextRate = SPEED_STEPS[i];
            break;
          }
        }
        media.playbackRate = nextRate;
        return;
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [
    isOpen,
    resolvedSubtitles,
    activeSubtitleTrackId,
    handleSubtitleChange,
    trapRef,
  ]);

  if (!isOpen) return null;

  const titleText = torrent.mediaTitle || torrent.name;
  const vlcUrl = buildExternalPlayerUrl("vlc", streamUrl);
  const mpvUrl = buildExternalPlayerUrl("mpv", streamUrl);

  const fontSizes: Record<SubtitleSize, string> = {
    small: "14px",
    medium: "18px",
    large: "22px",
    "x-large": "28px",
  };

  return (
    <div
      className="modal-overlay"
      role="dialog"
      aria-modal="true"
      aria-labelledby="media-player-title"
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: "rgba(0, 0, 0, 0.85)",
        backdropFilter: "blur(8px)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 9999,
        padding: "1rem",
      }}
      onClick={handleClose}
    >
      <style>{`
        .media-player-dialog video::cue {
          font-size: ${fontSizes[subtitleSize]};
          background-color: rgba(0, 0, 0, 0.75);
          color: #ffffff;
          line-height: 1.3;
        }
        .media-badge {
          display: inline-flex;
          align-items: center;
          font-size: 0.68rem;
          font-weight: 700;
          padding: 0.15rem 0.45rem;
          border-radius: 4px;
          background: rgba(255, 255, 255, 0.12);
          color: var(--text-primary, #ffffff);
          border: 1px solid rgba(255, 255, 255, 0.2);
          letter-spacing: 0.5px;
          text-transform: uppercase;
        }
      `}</style>

      <div
        ref={trapRef}
        className="card media-player-dialog"
        style={{
          width: "900px",
          maxWidth: "95vw",
          maxHeight: "92vh",
          display: "flex",
          flexDirection: "column",
          borderRadius: "12px",
          overflow: "hidden",
          border: "1px solid var(--border-light, #333)",
          boxShadow: "0 24px 64px rgba(0, 0, 0, 0.8)",
          padding: 0,
          backgroundColor: "var(--bg-primary, #18191c)",
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Modal Header */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            padding: "0.85rem 1.25rem",
            borderBottom: "1px solid var(--border-light, #333)",
            backgroundColor: "var(--bg-secondary, #222328)",
            gap: "0.75rem",
          }}
        >
          <div style={{ minWidth: 0, flex: 1 }}>
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: "0.5rem",
                flexWrap: "wrap",
              }}
            >
              <h3
                id="media-player-title"
                style={{
                  margin: 0,
                  fontSize: "1.1rem",
                  fontWeight: 600,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                  maxWidth: "500px",
                }}
              >
                {titleText}
              </h3>
              {mediaBadges.badges.map((b) => (
                <span key={b} className="media-badge">
                  {b}
                </span>
              ))}
            </div>
            <div
              style={{
                fontSize: "0.8rem",
                color: "var(--text-muted, #888)",
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
                marginTop: "0.2rem",
              }}
              title={fileName}
            >
              📄 {fileName}
            </div>
          </div>

          <button
            type="button"
            className="btn btn-sm btn-default"
            aria-label={t("mediaPlayer.close", "Close media player")}
            onClick={handleClose}
            style={{
              padding: "0.35rem 0.65rem",
              fontSize: "1.1rem",
              lineHeight: 1,
              borderRadius: "6px",
              cursor: "pointer",
            }}
          >
            ✕
          </button>
        </div>

        {/* Media / Fallback Area */}
        <div
          style={{
            position: "relative",
            flex: 1,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            backgroundColor: "#000000",
            minHeight: "360px",
            maxHeight: "65vh",
            overflow: "hidden",
          }}
        >
          {/* Codec Error Fallback Card */}
          {hasCodecError ? (
            <div
              data-testid="codec-error-card"
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                padding: "2rem",
                textAlign: "center",
                maxWidth: "600px",
                color: "#f8f9fa",
                gap: "1rem",
              }}
            >
              <div style={{ fontSize: "2.5rem" }}>⚠️</div>
              <h4 style={{ margin: 0, fontSize: "1.25rem", color: "#ffb703" }}>
                {t("mediaPlayer.playbackError", "Browser Codec Playback Error")}
              </h4>
              <p
                style={{
                  margin: 0,
                  fontSize: "0.9rem",
                  color: "#d1d5db",
                  lineHeight: 1.5,
                }}
              >
                {getCodecErrorMessage(errorCode, fileName)}
              </p>

              {/* Action Buttons */}
              <div
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: "0.6rem",
                  justifyContent: "center",
                  marginTop: "0.5rem",
                }}
              >
                <a
                  href={vlcUrl}
                  className="btn btn-primary"
                  role="button"
                  style={{
                    textDecoration: "none",
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "0.4rem",
                    fontWeight: 600,
                  }}
                >
                  <span>📺</span> {t("mediaPlayer.openInVlc", "Open in VLC")}
                </a>
                <a
                  href={mpvUrl}
                  className="btn btn-secondary"
                  role="button"
                  style={{
                    textDecoration: "none",
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "0.4rem",
                    fontWeight: 600,
                  }}
                >
                  <span>⚡</span> {t("mediaPlayer.openInMpv", "Open in MPV")}
                </a>
                <a
                  href={downloadUrl}
                  download={fileName}
                  className="btn btn-default"
                  role="button"
                  style={{
                    textDecoration: "none",
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "0.4rem",
                  }}
                >
                  <span>⬇️</span>{" "}
                  {t("mediaPlayer.directDownload", "Direct Download")}
                </a>
                <button
                  type="button"
                  className="btn btn-default"
                  onClick={handleCopyStreamUrl}
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "0.4rem",
                  }}
                >
                  <span>📋</span>{" "}
                  {copied
                    ? t("mediaPlayer.copied", "Copied!")
                    : t("mediaPlayer.copyStreamUrl", "Copy Stream URL")}
                </button>
                <button
                  type="button"
                  className="btn btn-default"
                  onClick={handleRetryPlayback}
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "0.4rem",
                  }}
                >
                  <span>🔄</span> {t("mediaPlayer.retry", "Retry")}
                </button>
              </div>
            </div>
          ) : isAudio ? (
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                gap: "1.5rem",
                padding: "2rem",
                width: "100%",
              }}
            >
              <div
                style={{
                  width: "120px",
                  height: "120px",
                  borderRadius: "50%",
                  backgroundColor: "rgba(52, 152, 219, 0.15)",
                  border: "2px solid rgba(52, 152, 219, 0.4)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "3rem",
                }}
              >
                🎵
              </div>
              <audio
                ref={audioRef}
                controls
                autoPlay
                preload="metadata"
                src={streamUrl}
                onError={handleMediaError}
                style={{ width: "80%", maxWidth: "500px" }}
              />
            </div>
          ) : (
            <video
              ref={videoRef}
              controls
              autoPlay
              preload="metadata"
              src={streamUrl}
              onError={handleMediaError}
              style={{
                width: "100%",
                height: "100%",
                maxHeight: "65vh",
                backgroundColor: "#000",
                outline: "none",
              }}
            >
              {resolvedSubtitles.map((track) => (
                <track
                  key={track.trackId}
                  kind="subtitles"
                  label={
                    track.title ||
                    `${track.language || "Subtitle"} (${track.twoLetterCode || track.format || `Track ${track.trackId}`})`
                  }
                  src={track.url}
                  srcLang={track.twoLetterCode || "en"}
                  default={track.isDefault}
                />
              ))}
            </video>
          )}
        </div>

        {/* Footer Toolbar: Subtitles, Size, & External Links */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            padding: "0.75rem 1.25rem",
            borderTop: "1px solid var(--border-light, #333)",
            backgroundColor: "var(--bg-secondary, #222328)",
            flexWrap: "wrap",
            gap: "0.75rem",
          }}
        >
          {/* Subtitle controls (for video) */}
          {!isAudio && (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: "0.5rem",
                flexWrap: "wrap",
              }}
            >
              <label
                htmlFor="subtitle-select"
                style={{
                  fontSize: "0.8rem",
                  color: "var(--text-muted, #aaa)",
                  fontWeight: 500,
                }}
              >
                💬 {t("mediaPlayer.subtitles", "Subtitles:")}
              </label>
              <select
                id="subtitle-select"
                aria-label={t(
                  "mediaPlayer.selectSubtitleTrack",
                  "Select subtitle track",
                )}
                className="form-control"
                style={{
                  fontSize: "0.8rem",
                  padding: "0.2rem 0.5rem",
                  height: "auto",
                  width: "auto",
                  minWidth: "140px",
                }}
                value={activeSubtitleTrackId}
                onChange={(e) => handleSubtitleChange(e.target.value)}
              >
                <option value="off">{t("mediaPlayer.off", "Off")}</option>
                {resolvedSubtitles.map((sub) => {
                  const labelParts = [
                    sub.language || sub.title || `Track ${sub.trackId}`,
                  ];
                  if (sub.isForced) labelParts.push("(Forced)");
                  if (sub.isHearingImpaired) labelParts.push("(CC)");
                  if (sub.isExternal) labelParts.push("[Ext]");
                  return (
                    <option key={sub.trackId} value={sub.trackId}>
                      {labelParts.join(" ")}
                    </option>
                  );
                })}
              </select>

              {activeSubtitleTrackId !== "off" && (
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "0.3rem",
                  }}
                >
                  <label
                    htmlFor="subtitle-size-select"
                    style={{
                      fontSize: "0.75rem",
                      color: "var(--text-muted, #aaa)",
                    }}
                  >
                    {t("mediaPlayer.size", "Size:")}
                  </label>
                  <select
                    id="subtitle-size-select"
                    aria-label={t(
                      "mediaPlayer.subtitleTextSize",
                      "Subtitle text size",
                    )}
                    className="form-control"
                    style={{
                      fontSize: "0.75rem",
                      padding: "0.15rem 0.4rem",
                      height: "auto",
                      width: "auto",
                    }}
                    value={subtitleSize}
                    onChange={(e) =>
                      setSubtitleSize(e.target.value as SubtitleSize)
                    }
                  >
                    <option value="small">
                      {t("mediaPlayer.sizeSmall", "Small")}
                    </option>
                    <option value="medium">
                      {t("mediaPlayer.sizeNormal", "Normal")}
                    </option>
                    <option value="large">
                      {t("mediaPlayer.sizeLarge", "Large")}
                    </option>
                    <option value="x-large">
                      {t("mediaPlayer.sizeExtraLarge", "Extra Large")}
                    </option>
                  </select>
                </div>
              )}
            </div>
          )}

          {/* Quick External Player Toolbar Links */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "0.4rem",
              marginLeft: "auto",
            }}
          >
            <a
              href={vlcUrl}
              className="btn btn-xs btn-default"
              title={t(
                "mediaPlayer.tooltipVlc",
                "Open stream in VLC media player",
              )}
              style={{ textDecoration: "none" }}
            >
              VLC
            </a>
            <a
              href={mpvUrl}
              className="btn btn-xs btn-default"
              title={t("mediaPlayer.tooltipMpv", "Open stream in MPV player")}
              style={{ textDecoration: "none" }}
            >
              MPV
            </a>
            <button
              type="button"
              className="btn btn-xs btn-default"
              onClick={handleCopyStreamUrl}
              title={t("mediaPlayer.tooltipCopyUrl", "Copy direct stream URL")}
            >
              {copied
                ? t("mediaPlayer.copied", "Copied!")
                : t("mediaPlayer.copyUrl", "Copy URL")}
            </button>
            <a
              href={downloadUrl}
              download={fileName}
              className="btn btn-xs btn-default"
              title={t("mediaPlayer.tooltipDownload", "Download media file")}
              style={{ textDecoration: "none" }}
            >
              {t("mediaPlayer.download", "Download")}
            </a>
          </div>
        </div>
      </div>
    </div>
  );
}

