                    : "transparent",
                color: viewMode === "status" ? "#000" : "inherit",
                border: "1px solid var(--border-light, #38332b)",
                borderRadius: "3px",
                cursor: "pointer",
              }}
              title="Download Status: Missing, In-flight, Verified, Corrupted"
