              Status
            </button>
            <button
              type="button"
              className={`view-toggle-btn ${viewMode === "rarity" ? "active" : ""}`}
              onClick={() => setViewMode("rarity")}
              style={{
                padding: "0.2rem 0.45rem",
                fontSize: "0.7rem",
                backgroundColor:
                  viewMode === "rarity"
                    ? "var(--accent, #c8a84e)"
                    : "transparent",
                color: viewMode === "rarity" ? "#000" : "inherit",
                border: "1px solid var(--border-light, #38332b)",
                borderRadius: "3px",
                cursor: "pointer",
              }}
              title="Swarm Availability Heatmap (Rare -> Common)"
            >
              Rarity Heatmap
            </button>
            <button
              type="button"
              className={`view-toggle-btn ${viewMode === "files" ? "active" : ""}`}
              onClick={() => setViewMode("files")}
              style={{
                padding: "0.2rem 0.45rem",
                fontSize: "0.7rem",
                backgroundColor:
                  viewMode === "files"
                    ? "var(--accent, #c8a84e)"
                    : "transparent",
                color: viewMode === "files" ? "#000" : "inherit",
                border: "1px solid var(--border-light, #38332b)",
                borderRadius: "3px",
                cursor: "pointer",
              }}
              title="File Boundary Overlays"
            >
              File Boundaries
            </button>
          </div>
        </div>
      </div>

      {/* Accessible Linear Progress Bar Summary (WAI-ARIA compliant) */}
      <div
        role="progressbar"
        aria-valuenow={Math.round(Math.min(100, Math.max(0, progress * 100)))}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuetext={`${(progress * 100).toFixed(1)}% verified`}
        style={{
          position: "relative",
          width: "100%",
          height: "10px",
          backgroundColor: "rgba(255, 255, 255, 0.08)",
          borderRadius: "3px",
          overflow: "hidden",
          border: "1px solid var(--border-light, #38332b)",
        }}
      >
        <div
          style={{
            width: `${Math.min(100, Math.max(0, progress * 100))}%`,
            height: "100%",
            background:
              progress >= 1.0
                ? "linear-gradient(90deg, #27ae60 0%, #2ecc71 100%)"
                : "linear-gradient(90deg, #c8a84e 0%, #e67e22 100%)",
            transition: "width 0.3s ease",
          }}
        />
      </div>

      {/* Visualizer: Linear Bar or Matrix Grid */}
      {layoutMode === "bar" ? (
        <div
          ref={barContainerRef}
          style={{
            position: "relative",
            width: "100%",
            height: "26px",
            backgroundColor: "#151412",
            borderRadius: "4px",
            overflow: "hidden",
            border: "1px solid var(--border-light, #302c24)",
            display: "flex",
            alignItems: "center",
            padding: "1px",
          }}
        >
          <canvas
            ref={barCanvasRef}
            role="img"
            aria-label="BitTorrent Piece Map Linear Bar"
            onMouseMove={handleBarMouseMove}
            onMouseLeave={handleMouseLeave}
            style={{
              display: "block",
              width: "100%",
              height: "24px",
              cursor: "crosshair",
            }}
          />
        </div>
      ) : (
        <div
          style={{
            position: "relative",
            width: "100%",
            display: "flex",
            justifyContent: "center",
            backgroundColor: "#151412",
            borderRadius: "6px",
            padding: "4px",
            border: "1px solid var(--border-light, #302c24)",
            overflow: "hidden",
          }}
        >
          <canvas
            ref={canvasRef}
            role="img"
            aria-label="BitTorrent Piece Map Grid"
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            style={{
              display: "block",
              cursor: "crosshair",
            }}
          />
        </div>
      )}

      {/* Mode C: Interactive File Boundary List */}
      {viewMode === "files" && fileBoundaries.length > 0 && (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "0.35rem",
            backgroundColor: "rgba(0, 0, 0, 0.2)",
            padding: "0.5rem",
            borderRadius: "4px",
            border: "1px solid var(--border-light, #302c24)",
            maxHeight: "130px",
            overflowY: "auto",
          }}
        >
          <div
            style={{
              fontSize: "0.72rem",
              fontWeight: 600,
              color: "var(--text-secondary, #b0a898)",
              display: "flex",
              justifyContent: "space-between",
            }}
          >
            <span>Hover or select file to overlay piece boundaries:</span>
            {selectedFileIndex !== null && (
              <button
                type="button"
                onClick={() => setSelectedFileIndex(null)}
                style={{
                  background: "none",
                  border: "none",
                  color: "var(--accent, #c8a84e)",
                  fontSize: "0.7rem",
                  cursor: "pointer",
                  padding: 0,
                }}
              >
                Clear selection
              </button>
            )}
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: "0.35rem" }}>
            {fileBoundaries.map((fb, idx) => {
              const isSelected = selectedFileIndex === idx;
              const isHovered = hoveredFileIndex === idx;
              const color = FILE_PALETTE[fb.colorIndex % FILE_PALETTE.length];
              const fileName = fb.file.path.split("/").pop() || fb.file.path;

              return (
                <button
                  key={fb.file.id || idx}
                  type="button"
                  onMouseEnter={() => setHoveredFileIndex(idx)}
                  onMouseLeave={() => setHoveredFileIndex(null)}
                  onClick={() => setSelectedFileIndex(isSelected ? null : idx)}
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "0.35rem",
                    padding: "0.2rem 0.5rem",
                    fontSize: "0.68rem",
                    borderRadius: "3px",
                    border: isSelected
                      ? "1px solid #fff"
                      : isHovered
                        ? `1px solid ${color}`
                        : "1px solid var(--border-light, #302c24)",
                    backgroundColor:
                      isSelected || isHovered
                        ? "rgba(255,255,255,0.12)"
                        : "rgba(0,0,0,0.3)",
                    color: "#fff",
                    cursor: "pointer",
                  }}
                  title={`${fb.file.path} (Pieces ${fb.startPiece} - ${fb.endPiece})`}
                >
                  <span
                    style={{
                      width: "8px",
                      height: "8px",
                      borderRadius: "2px",
                      backgroundColor: color,
                    }}
                  />
                  <span
                    style={{
                      maxWidth: "160px",
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {fileName}
                  </span>
                  <span
                    style={{
                      color: "var(--text-muted, #888)",
                      fontSize: "0.64rem",
                    }}
                  >
                    ({formatBytes(fb.file.size)})
                  </span>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Footer Legends */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          fontSize: "0.72rem",
          color: "var(--text-muted, #9c9484)",
          gap: "0.5rem",
        }}
      >
        {/* Mode-specific Legend */}
        {viewMode === "status" && (
          <div style={{ display: "flex", gap: "0.75rem", flexWrap: "wrap" }}>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.3rem",
              }}
            >
              <span
                style={{
                  width: "8px",
                  height: "8px",
                  borderRadius: "2px",
                  backgroundColor: "#27ae60",
                }}
              />
              Verified ({stats.verified})
            </span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.3rem",
              }}
            >
              <span
                style={{
                  width: "8px",
                  height: "8px",
                  borderRadius: "2px",
                  backgroundColor: "#3498db",
                }}
              />
              In-flight ({stats.inFlight})
            </span>
            {stats.corrupted > 0 && (
              <span
                style={{
                  display: "inline-flex",
                  alignItems: "center",
                  gap: "0.3rem",
                }}
              >
                <span
                  style={{
                    width: "8px",
                    height: "8px",
                    borderRadius: "2px",
                    backgroundColor: "#e74c3c",
                  }}
                />
                Corrupted ({stats.corrupted})
              </span>
            )}
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.3rem",
              }}
            >
              <span
                style={{
                  width: "8px",
                  height: "8px",
                  borderRadius: "2px",
                  backgroundColor: "#282520",
                }}
              />
              Missing ({stats.missing})
            </span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.3rem",
              }}
            >
              {stats.completeCount} / {totalPieces} Complete
            </span>
          </div>
        )}

        {viewMode === "rarity" && (
          <div
            style={{
              display: "flex",
              gap: "0.6rem",
              alignItems: "center",
              flexWrap: "wrap",
            }}
          >
            <span>Availability:</span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.25rem",
              }}
            >
              <span
                style={{
                  width: "8px",
                  height: "8px",
                  borderRadius: "2px",
                  backgroundColor: "#282520",
                }}
              />{" "}
              0
            </span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.25rem",
              }}
            >
              <span
                style={{
                  width: "8px",
                  height: "8px",
                  borderRadius: "2px",
                  backgroundColor: "#e74c3c",
                }}
              />{" "}
              1 (Rare)
            </span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.25rem",
              }}
            >
              <span
                style={{
                  width: "8px",
                  height: "8px",
                  borderRadius: "2px",
                  backgroundColor: "#e67e22",
                }}
              />{" "}
              2-3
            </span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.25rem",
              }}
            >
              <span
                style={{
                  width: "8px",
                  height: "8px",
                  borderRadius: "2px",
                  backgroundColor: "#f1c40f",
                }}
              />{" "}
              4-5
            </span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.25rem",
              }}
            >
              <span
                style={{
                  width: "8px",
                  height: "8px",
                  borderRadius: "2px",
                  backgroundColor: "#82c91e",
                }}
              />{" "}
              6-9
            </span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.25rem",
              }}
            >
              <span
                style={{
                  width: "8px",
                  height: "8px",
                  borderRadius: "2px",
