          </div>
        )}

        {viewMode === "files" && (
          <div style={{ display: "flex", gap: "0.5rem", alignItems: "center" }}>
            <span>
              File count: {fileBoundaries.length} file
              {fileBoundaries.length === 1 ? "" : "s"}
