              {hoveredInfo.availability} peer
              {hoveredInfo.availability === 1 ? "" : "s"}
            </span>
          </div>

          {/* Containing file name(s) and offset */}
          {hoveredInfo.files.length > 0 && (
            <div
              style={{
                borderTop: "1px solid rgba(255, 255, 255, 0.08)",
                paddingTop: "0.3rem",
                marginTop: "0.15rem",
                display: "flex",
                flexDirection: "column",
                gap: "0.2rem",
              }}
            >
              <span
                style={{
                  color: "var(--text-muted, #9c9484)",
                  fontSize: "0.7rem",
                }}
              >
                Containing file{hoveredInfo.files.length > 1 ? "s" : ""}:
              </span>
              {hoveredInfo.files.map((f, idx) => (
                <div
                  key={idx}
                  style={{
                    fontSize: "0.7rem",
                    display: "flex",
                    flexDirection: "column",
                    backgroundColor: "rgba(255, 255, 255, 0.04)",
                    padding: "0.2rem 0.35rem",
                    borderRadius: "3px",
                  }}
                >
                  <span
                    style={{
                      fontWeight: 500,
                      overflow: "hidden",
                      textOverflow: "ellipsis",
                      whiteSpace: "nowrap",
                    }}
                    title={f.name}
                  >
                    📄 {f.name}
                  </span>
                  <span
                    style={{
                      color: "var(--text-muted, #888)",
                      fontSize: "0.66rem",
                    }}
                  >
                    Offset: {formatBytes(f.offset)} / {formatBytes(f.size)}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

