                  <button
                    className="context-menu-item"
                    onClick={() =>
                      handleCopy(
                        effectiveTorrents.map((t) => t.infoHash).join("\n"),
                        t("torrents.table.infoHash", undefined, "Info Hash"),
                      )
                    }
                  >
                    {t("torrents.table.infoHash", undefined, "Info Hash")}
                    {countSuffix}
                  </button>
                  <button
                    className="context-menu-item"
                    onClick={() =>
                      handleCopy(
