                        t(
                          "modals.addTorrent.byMagnet",
                          undefined,
                          "Magnet Link",
                        ),
                      )
                    }
                  >
                    {t("modals.addTorrent.byMagnet", undefined, "Magnet Link")}
                    {countSuffix}
                  </button>
                  {!isMulti && ct && (
                    <button
                      className="context-menu-item"
                      onClick={() =>
                        handleCopy(
                          ct.trackerUrl ?? "",
                          t("torrents.table.tracker", undefined, "Tracker URL"),
