                >
                  {isMulti
                    ? `Prioritize First & Last Pieces${countSuffix}`
                    : `${ct?.firstLastPiecePrio ? "Disable" : "Enable"} ${t("torrents.firstLastPiecePrio", undefined, "Prioritize First & Last Pieces")}`}
                </button>
              </>
            )}

            {/* Remove submenu */}
            {canDeleteTorrent && (
              <>
                <div className="context-menu-separator" />
                <div
