  t: (k: string, ...args: any[]) => string,
): string => {
  const i18nKey = COLUMN_I18N_KEYS[key] || `torrents.table.${key}`;
  const def = ALL_COLUMNS.find((c) => c.key === key);
  return t(i18nKey, undefined, def?.label || key);
};

