}

function getSortValue(
  t: Torrent,
  key: SortKey,
): string | number | null | undefined {
  switch (key) {
    case "#":
      return t.sortOrder ?? t.id;
    case "queuePosition":
      return t.sortOrder ?? t.id;
    case "trackerUrl":
      return t.trackerUrl ?? "";
    case "lastActive":
      return t.lastActive ?? "";
    case "creationDate":
      return t.creationDate ?? "";
    case "comment":
      return t.comment ?? "";
    case "createdBy":
      return t.createdBy ?? "";
    case "label":
      return t.label ?? "";
    case "infoHash":
      return t.infoHash ?? "";
    case "isPrivate":
      return t.isPrivate ? 1 : 0;
    case "superSeeding":
      return t.superSeeding ? 1 : 0;
    case "sequentialDownload":
      return t.sequentialDownload ? 1 : 0;
    case "forceStart":
      return t.forceStart ? 1 : 0;
    case "active":
      return t.active ? 1 : 0;
    default:
      return (t as unknown as Record<string, unknown>)[key] as
        string | number | null | undefined;
  }
}

