export interface TorrentTableRowProps {
  torrent: Torrent;
  rowIndex: number;
  virtualRow?: VirtualItem;
  columns: ColumnDef[];
  isSelected: boolean;
  isChecked: boolean;
  isFocused: boolean;
  onSelectTorrent?: (id: number | null) => void;
  onSelect?: (torrent: Torrent) => void;
  onToggleSelect?: (id: number) => void;
  onToggleActive?: () => void;
  onRowClick: (
    torrent: Torrent,
    index: number,
    event: React.MouseEvent,
  ) => void;
  onContextMenu: (e: React.MouseEvent, torrent: Torrent) => void;
  onFocus: (index: number) => void;
  historyMatch?: DownloadHistoryEntry;
  arrConnections?: any;
  measureElement?: (node: HTMLElement | null) => void;
  rowRef?: (el: HTMLTableRowElement | null) => void;
}

export const TorrentTableRow = React.memo<TorrentTableRowProps>(
  ({
    torrent: t,
    rowIndex,
    virtualRow,
    columns,
    isSelected,
    isChecked,
    isFocused,
    onSelectTorrent,
    onSelect,
    onToggleSelect,
    onToggleActive,
    onRowClick,
    onContextMenu,
    onFocus,
    historyMatch,
    arrConnections,
    measureElement,
    rowRef,
  }) => {
    const handleKeyDown = useCallback(
      (e: React.KeyboardEvent) => {
        if (
          typeof HTMLInputElement !== "undefined" &&
          e.target instanceof HTMLInputElement
        ) {
          return;
        }
        if (e.key === " ") {
          e.preventDefault();
          e.stopPropagation?.();
          if (e.shiftKey || e.ctrlKey || e.metaKey) {
            onToggleSelect?.(t.id);
          } else {
            onToggleActive?.();
          }
        } else if (e.key === "Enter") {
          e.preventDefault();
          e.stopPropagation?.();
          if (onSelectTorrent) {
            onSelectTorrent(isSelected ? null : t.id);
          } else if (onSelect) {
            onSelect(
              applyTelemetry(t, useTorrentStore.getState().telemetry[t.id]),
            );
          }
        }
      },
      [
        onToggleSelect,
        onToggleActive,
        onSelectTorrent,
        onSelect,
        isSelected,
        t,
      ],
    );

    const setRef = useCallback(
      (el: HTMLTableRowElement | null) => {
        rowRef?.(el);
        measureElement?.(el);
      },
      [rowRef, measureElement],
    );

    return (
      <tr
        key={t.id}
        ref={setRef}
        role="row"
        data-index={rowIndex}
        tabIndex={0}
        aria-selected={isSelected || isChecked}
        className={`torrent-table-row${isSelected ? " torrent-table-row-selected" : ""}${isChecked ? " torrent-table-row-selected" : ""}${isFocused ? " torrent-table-row-focused" : ""}`}
        onFocus={() => onFocus(rowIndex)}
        onKeyDown={handleKeyDown}
        onClick={(e) => onRowClick(t, rowIndex, e)}
        onContextMenu={(e) => onContextMenu(e, t)}
        style={{
          cursor: "pointer",
          backgroundColor: isSelected
            ? "var(--bg-card-hover, #23284b)"
            : isChecked
              ? "rgba(255, 209, 102, 0.05)"
              : "transparent",
          borderBottom: "1px solid var(--border-light)",
          fontSize: "0.82rem",
        }}
      >
        <td style={{ textAlign: "center", padding: "0.5rem", width: 36 }}>
          <input
            type="checkbox"
            className="torrent-checkbox"
            aria-label={`Select ${t.name}`}
            checked={isChecked}
            onChange={() => {}}
            onClick={(e) => {
              e.stopPropagation();
              onToggleSelect?.(t.id);
            }}
          />
        </td>

        {columns.map((col) => (
          <td
            key={col.key}
            className={col.key === "#" ? "torrent-table-index" : undefined}
            style={{
              padding: "0.55rem 0.75rem",
              whiteSpace: "nowrap",
            }}
          >
            <TorrentCell
              columnKey={col.key}
              torrent={t}
              rowIndex={rowIndex}
              historyMatch={historyMatch}
              arrConnections={arrConnections}
            />
          </td>
        ))}
      </tr>
    );
  },
);
TorrentTableRow.displayName = "TorrentTableRow";

