                    }}
                  />

                  <TrackerFavicon urlOrHost={item.url} size={18} />

                  <div style={{ minWidth: 0 }}>
                    <div
                      style={{
                        fontSize: "0.83rem",
                        fontFamily: "monospace",
                        fontWeight: 600,
                        overflow: "hidden",
