                      )}

                      {item.seeders !== undefined && item.seeders > 0 && (
                        <span style={{ color: "var(--accent)" }}>
                          ⚡ {item.seeders} seeds / {item.leechers ?? 0} leeches
                        </span>
                      )}
                    </div>
                  </div>
                </div>

                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "0.4rem",
                    flexShrink: 0,
                    marginLeft: "0.5rem",
                  }}
                >
                  {isAttached ? (
                    <span
                      className="badge badge-secondary"
                      style={{ fontSize: "0.72rem" }}
                    >
                      ✓ Already Attached
                    </span>
                  ) : item.isVerified ? (
                    <span
                      className="badge badge-success"
                      style={{ fontSize: "0.72rem" }}
                    >
                      🟢 Verified Swarm
                    </span>
                  ) : item.isAlive ? (
                    <span
                      className="badge badge-success"
                      style={{ fontSize: "0.72rem" }}
                    >
                      🟢 Alive
                    </span>
                  ) : item.isSlow ? (
                    <span
                      className="badge badge-warning"
                      style={{ fontSize: "0.72rem" }}
                    >
                      🟡 Slow
                    </span>
                  ) : item.isOffline ? (
                    <span
                      className="badge badge-danger"
                      style={{ fontSize: "0.72rem" }}
                    >
                      🔴 Offline
                    </span>
                  ) : (
                    <span
                      className="badge badge-secondary"
                      style={{ fontSize: "0.72rem" }}
                    >
                      ⚪ Untested
                    </span>
                  )}
