          )}
        </div>

        {/* Custom Tracker input */}
        <form
          onSubmit={handleAddCustom}
          style={{
            padding: "0.6rem 1.25rem",
            backgroundColor: "rgba(0, 0, 0, 0.1)",
            borderTop: "1px solid var(--border-light)",
            display: "flex",
            gap: "0.5rem",
            alignItems: "center",
          }}
        >
          <input
            type="text"
            className="form-control"
            placeholder="Or enter custom URL (e.g. udp://tracker.example.com:1337/announce)"
            aria-label="Enter custom tracker URL"
            value={customUrl}
            onChange={(e) => setCustomUrl(e.target.value)}
            style={{ flex: 1, fontSize: "0.82rem", padding: "0.35rem 0.6rem" }}
          />
          <button
            type="submit"
            className="btn btn-sm btn-action"
            disabled={!customUrl.trim()}
          >
            + Add to List
          </button>
        </form>

        {/* Footer actions */}
        <div
          style={{
            padding: "0.75rem 1.25rem",
            backgroundColor: "var(--bg-secondary)",
            borderTop: "1px solid var(--border-light)",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <div style={{ fontSize: "0.85rem", fontWeight: 500 }}>
            {selectedUrls.size === 0 ? (
              <span style={{ color: "var(--text-muted)" }}>
                0 trackers selected
              </span>
            ) : (
              <span style={{ color: "var(--accent)" }}>
                ✓ {selectedUrls.size} tracker(s) selected
              </span>
            )}
          </div>

          <div style={{ display: "flex", gap: "0.5rem" }}>
            <button
              type="button"
              className="btn btn-action"
              onClick={onClose}
              style={{ fontSize: "0.82rem" }}
            >
              Done (Keep Selection)
            </button>
            <button
              type="button"
              className="btn btn-primary"
              onClick={() => {
                onAddAndAnnounce();
                onClose();
              }}
              disabled={isAdding || selectedUrls.size === 0}
              style={{ fontSize: "0.82rem" }}
            >
              {isAdding
                ? "Adding & Announcing..."
                : `+ Add & Announce (${selectedUrls.size})`}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

