function levelBadgeClass(level: string): string {
  switch (level.toLowerCase()) {
    case "debug":
    case "trace":
      return "torrent-log-level-debug";
    case "warn":
    case "warning":
      return "torrent-log-level-warn";
    case "error":
    case "fatal":
      return "torrent-log-level-error";
    default:
      return "torrent-log-level-info";
  }
}

function sourceBadgeStyle(source: string): React.CSSProperties {
  switch (source.toLowerCase()) {
    case "tracker":
      return {
        backgroundColor: "rgba(59, 130, 246, 0.2)",
        color: "#60a5fa",
        borderColor: "rgba(59, 130, 246, 0.4)",
      };
    case "peers":
    case "peer":
      return {
        backgroundColor: "rgba(168, 85, 247, 0.2)",
        color: "#c084fc",
        borderColor: "rgba(168, 85, 247, 0.4)",
      };
    case "seeding":
    case "seeder":
      return {
        backgroundColor: "rgba(34, 197, 94, 0.2)",
        color: "#4ade80",
        borderColor: "rgba(34, 197, 94, 0.4)",
      };
    case "trackerboost":
      return {
        backgroundColor: "rgba(245, 158, 11, 0.2)",
        color: "#fbbf24",
        borderColor: "rgba(245, 158, 11, 0.4)",
      };
    default:
      return {
        backgroundColor: "rgba(148, 163, 184, 0.2)",
        color: "#cbd5e1",
        borderColor: "rgba(148, 163, 184, 0.4)",
      };
  }
}

export function LogTab({ torrent }: { torrent: Torrent }) {
  const [isLive, setIsLive] = useState(true);
  const [levelFilter, setLevelFilter] = useState<string>("ALL");
  const [sourceFilter, setSourceFilter] = useState<string>("ALL");
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [copied, setCopied] = useState(false);

  const {
    data: rawLogs,
    isLoading,
    isError,
    refetch,
  } = useTorrentLogs(torrent.id, {
    polling: isLive,
  });

  const logs = useMemo(() => {
    return (rawLogs ?? []).slice(0, 100);
  }, [rawLogs]);

  const sources = useMemo(() => {
    const set = new Set<string>();
    for (const log of logs) {
      if (log.source) set.add(log.source);
    }
    return Array.from(set).sort();
  }, [logs]);

  const filteredLogs = useMemo(() => {
    return logs.filter((entry) => {
      if (levelFilter !== "ALL" && entry.level.toUpperCase() !== levelFilter) {
        return false;
      }
      if (
        sourceFilter !== "ALL" &&
        entry.source.toLowerCase() !== sourceFilter.toLowerCase()
      ) {
        return false;
      }
      if (searchTerm) {
        const query = searchTerm.toLowerCase();
        const matchMsg = entry.message.toLowerCase().includes(query);
        const matchSrc = entry.source.toLowerCase().includes(query);
        const matchLvl = entry.level.toLowerCase().includes(query);
        if (!matchMsg && !matchSrc && !matchLvl) return false;
      }
      return true;
    });
  }, [logs, levelFilter, sourceFilter, searchTerm]);

  function copyLogsToClipboard() {
    const text = filteredLogs
      .map(
        (l) =>
          `[${formatDate(l.timeStamp)}] [${l.level.toUpperCase()}] [${l.source}] ${l.message}`,
      )
      .join("\n");
    navigator.clipboard.writeText(text).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }

  if (isLoading && logs.length === 0)
    return <PanelLoading>Loading seeder & tracker log entries...</PanelLoading>;
  if (isError && logs.length === 0)
    return <PanelEmpty>Failed to load log entries.</PanelEmpty>;

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
      {/* Controls toolbar */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: "0.4rem",
          paddingBottom: "0.35rem",
          borderBottom: "1px solid var(--border-light)",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "0.4rem" }}>
          <span
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: "0.25rem",
              fontSize: "0.7rem",
              fontWeight: 500,
              padding: "0.15rem 0.4rem",
              borderRadius: "10px",
              backgroundColor: isLive
                ? "rgba(34, 197, 94, 0.15)"
                : "rgba(148, 163, 184, 0.15)",
              color: isLive ? "#4ade80" : "#94a3b8",
              border: `1px solid ${isLive ? "rgba(34, 197, 94, 0.3)" : "rgba(148, 163, 184, 0.3)"}`,
            }}
          >
            <span
              style={{
                width: "5px",
                height: "5px",
                borderRadius: "50%",
                backgroundColor: isLive ? "#22c55e" : "#94a3b8",
              }}
            />
            {isLive ? "Live (3s)" : "Paused"}
          </span>
          <span style={{ fontSize: "0.72rem", color: "var(--text-dim, #888)" }}>
            {filteredLogs.length} of latest {logs.length} (max 100)
          </span>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: "0.3rem" }}>
          <button
            className={`btn btn-xs ${isLive ? "btn-outline" : "btn-primary"}`}
            style={{ fontSize: "0.72rem", padding: "0.15rem 0.4rem" }}
            onClick={() => setIsLive(!isLive)}
          >
            {isLive ? "⏸ Pause" : "▶ Resume"}
          </button>
          <button
            className="btn btn-outline btn-xs"
            style={{ fontSize: "0.72rem", padding: "0.15rem 0.4rem" }}
            onClick={() => refetch()}
          >
            🔄 Refresh
          </button>
          <button
            className="btn btn-outline btn-xs"
            style={{ fontSize: "0.72rem", padding: "0.15rem 0.4rem" }}
            onClick={copyLogsToClipboard}
          >
            {copied ? "✓" : "📋 Copy"}
          </button>
        </div>
      </div>

      {/* Filter and search bar */}
      <div
        style={{
          display: "flex",
          gap: "0.4rem",
          flexWrap: "wrap",
          alignItems: "center",
        }}
      >
        <input
          type="text"
          className="form-control"
          placeholder="Filter logs..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            flex: "1 1 120px",
            padding: "0.2rem 0.45rem",
            fontSize: "0.75rem",
            height: "26px",
            backgroundColor: "var(--bg-primary)",
            color: "inherit",
          }}
        />
        <div style={{ display: "flex", gap: "0.2rem" }}>
          {["ALL", "INFO", "DEBUG", "WARN", "ERROR"].map((lvl) => (
            <button
