          ))}
        </div>
      </div>

      {/* Table wrap */}
      <div
        className="detail-panel-table-wrap"
        style={{
          maxHeight: "360px",
          overflowY: "auto",
          backgroundColor: "#0d1117",
          borderRadius: "4px",
