      >
        <table
          className="torrent-table"
          style={{
            fontSize: "0.75rem",
            width: "100%",
            borderCollapse: "collapse",
          }}
        >
          <thead>
            <tr style={{ backgroundColor: "#161b22" }}>
              <th
                className="torrent-table-th"
                style={{ width: "130px", padding: "0.3rem 0.4rem" }}
