                >
                  {logs.length === 0
                    ? "No events recorded yet"
                    : "No logs match filter"}
                </td>
              </tr>
            ) : (
              filteredLogs.map((entry) => (
                <tr
                  key={entry.id}
                  className="torrent-table-row"
                  style={{
