      btn2.focus();
      const tabEvent = new MockKeyboardEvent("Tab", { shiftKey: false });
      trap.handleKeyDown(tabEvent as unknown as KeyboardEvent);
      // Not at boundary: browser default Tab moves focus naturally
      assert.equal(tabEvent.defaultPrevented, false);

      const shiftTabEvent = new MockKeyboardEvent("Tab", { shiftKey: true });
      trap.handleKeyDown(shiftTabEvent as unknown as KeyboardEvent);
      // Not at boundary: browser default Shift+Tab moves focus naturally
      assert.equal(shiftTabEvent.defaultPrevented, false);

      trap.deactivate();
    });

    it("invokes onEscape and prevents default when Escape is pressed", () => {
      const container = new MockElement("div", "container");
      const btn1 = new MockElement("button", "btn1");
      container.appendChild(btn1);
      rootBody.appendChild(container);

      let escapeCalled = false;
      const trap = new FocusTrap({
        container: container as unknown as HTMLElement,
        onEscape: () => {
          escapeCalled = true;
        },
      });
      trap.activate();

      const escapeEvent = new MockKeyboardEvent("Escape");
      trap.handleKeyDown(escapeEvent as unknown as KeyboardEvent);

      assert.equal(escapeCalled, true);
      assert.equal(escapeEvent.defaultPrevented, true);

      trap.deactivate();
    });

    it("handles keydown dispatched through mockDocument listener", () => {
      const container = new MockElement("div", "container");
      const btn1 = new MockElement("button", "btn1");
      const btn2 = new MockElement("button", "btn2");
      container.appendChild(btn1);
      container.appendChild(btn2);
      rootBody.appendChild(container);

      let escapeCalled = false;
      const trap = new FocusTrap({
        container: container as unknown as HTMLElement,
        onEscape: () => {
          escapeCalled = true;
        },
      });
      trap.activate();

      const escapeEvent = new MockKeyboardEvent("Escape");
      mockDocument.dispatchEvent(escapeEvent);

      assert.equal(escapeCalled, true);
      assert.equal(escapeEvent.defaultPrevented, true);

      trap.deactivate();
      escapeCalled = false;

      // After deactivation, listener is removed
      const secondEscape = new MockKeyboardEvent("Escape");
      mockDocument.dispatchEvent(secondEscape);
      assert.equal(escapeCalled, false);
    });
  });
});

import { useEffect, useRef } from "react";

export const FOCUSABLE_SELECTOR =
  'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

export function isHtmlElement(el: any): el is HTMLElement {
  if (!el) return false;
  if (typeof HTMLElement !== "undefined") {
    return el instanceof HTMLElement;
  }
  return typeof el === "object" && typeof el.focus === "function";
}

export function isElementConnected(el: HTMLElement): boolean {
  if (typeof el.isConnected === "boolean") {
    return el.isConnected;
  }
  if (
    typeof document !== "undefined" &&
    typeof document.contains === "function"
  ) {
    return document.contains(el);
  }
  return true;
}

export function isElementVisible(el: HTMLElement): boolean {
  if (el.hidden) return false;
  if (el.getAttribute?.("aria-hidden") === "true") return false;
  if (el.style?.display === "none" || el.style?.visibility === "hidden")
    return false;
  return true;
}

export function getFocusableElements(
  container: HTMLElement | null,
): HTMLElement[] {
  if (!container || typeof container.querySelectorAll !== "function") return [];
  const elements = Array.from(
    container.querySelectorAll<HTMLElement>(FOCUSABLE_SELECTOR),
  );
  return elements.filter(isElementVisible);
}

export interface FocusTrapOptions {
  container: HTMLElement | null;
  initialFocusElement?: HTMLElement | null;
  onEscape?: () => void;
  disableRestoreFocus?: boolean;
}

export class FocusTrap {
  private container: HTMLElement | null;
  private initialFocusElement?: HTMLElement | null;
  private onEscape?: () => void;
  private disableRestoreFocus: boolean;
  private previousActiveElement: HTMLElement | null = null;
  private isActive = false;
  private boundKeyDown: ((e: KeyboardEvent) => void) | null = null;

  constructor(options: FocusTrapOptions) {
    this.container = options.container;
    this.initialFocusElement = options.initialFocusElement;
    this.onEscape = options.onEscape;
    this.disableRestoreFocus = options.disableRestoreFocus ?? false;
  }

  public setContainer(container: HTMLElement | null): void {
    this.container = container;
  }

  public setInitialFocusElement(element?: HTMLElement | null): void {
    this.initialFocusElement = element;
  }

  public setOnEscape(onEscape?: () => void): void {
    this.onEscape = onEscape;
  }

  public setDisableRestoreFocus(disable: boolean): void {
    this.disableRestoreFocus = disable;
  }

  public getIsActive(): boolean {
    return this.isActive;
  }

  public getPreviousActiveElement(): HTMLElement | null {
    return this.previousActiveElement;
  }

  public activate(): void {
    if (this.isActive) return;
    this.isActive = true;

    if (
      typeof document !== "undefined" &&
      isHtmlElement(document.activeElement)
    ) {
      this.previousActiveElement = document.activeElement;
    }

    this.focusInitial();

    this.boundKeyDown = (e: KeyboardEvent) => this.handleKeyDown(e);
    if (typeof document !== "undefined") {
      document.addEventListener("keydown", this.boundKeyDown);
    }
  }

  public deactivate(): void {
    if (!this.isActive) return;
    this.isActive = false;

    if (this.boundKeyDown && typeof document !== "undefined") {
      document.removeEventListener("keydown", this.boundKeyDown);
      this.boundKeyDown = null;
    }

    if (!this.disableRestoreFocus && this.previousActiveElement) {
      const el = this.previousActiveElement;
      this.previousActiveElement = null;
      if (typeof el.focus === "function" && isElementConnected(el)) {
        try {
          el.focus();
        } catch {
          // Ignore if element is no longer focusable
        }
      }
    }
  }

  public focusInitial(): void {
    if (!this.container) return;

    if (
      this.initialFocusElement &&
      isElementConnected(this.initialFocusElement)
    ) {
      this.initialFocusElement.focus();
      return;
    }

    const focusables = getFocusableElements(this.container);
    if (focusables.length > 0) {
      focusables[0].focus();
    } else {
      if (!this.container.hasAttribute("tabindex")) {
        this.container.setAttribute("tabindex", "-1");
      }
      this.container.focus();
    }
  }

  public handleKeyDown(event: KeyboardEvent): void {
    if (!this.isActive || !this.container) return;
    if (event.defaultPrevented) return;

    if (event.key === "Escape") {
      if (this.onEscape) {
        event.preventDefault();
        this.onEscape();
      }
      return;
    }

    if (event.key === "Tab") {
      const focusables = getFocusableElements(this.container);

      if (focusables.length === 0) {
        event.preventDefault();
        if (!this.container.hasAttribute("tabindex")) {
          this.container.setAttribute("tabindex", "-1");
        }
        this.container.focus();
        return;
      }

      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      const active =
        typeof document !== "undefined" ? document.activeElement : null;

      if (event.shiftKey) {
        if (active === first || !this.container.contains(active as Node)) {
          event.preventDefault();
          last.focus();
        }
      } else {
        if (active === last || !this.container.contains(active as Node)) {
          event.preventDefault();
          first.focus();
        }
      }
    }
  }
}

export interface UseFocusTrapOptions {
  isOpen?: boolean;
  initialFocusRef?: React.RefObject<HTMLElement | null>;
  onEscape?: () => void;
  onClose?: () => void;
  disableRestoreFocus?: boolean;
}

export function useFocusTrap<T extends HTMLElement = HTMLDivElement>(
  options?: UseFocusTrapOptions | boolean,
  onCloseCallback?: () => void,
): React.RefObject<T | null> {
  const normalizedOptions: UseFocusTrapOptions =
    typeof options === "boolean"
      ? { isOpen: options, onClose: onCloseCallback }
      : (options ?? {});

  const {
    isOpen = true,
    initialFocusRef,
    onEscape,
    onClose = onCloseCallback,
    disableRestoreFocus = false,
  } = normalizedOptions;

  const effectiveEscape = onEscape ?? onClose;

  const containerRef = useRef<T | null>(null);
  const trapRef = useRef<FocusTrap | null>(null);

  const onEscapeRef = useRef(effectiveEscape);
  onEscapeRef.current = effectiveEscape;
  const disableRestoreFocusRef = useRef(disableRestoreFocus);
  disableRestoreFocusRef.current = disableRestoreFocus;

  useEffect(() => {
    if (!isOpen) {
      if (trapRef.current) {
        trapRef.current.deactivate();
        trapRef.current = null;
      }
      return;
    }

    const trap = new FocusTrap({
      container: containerRef.current,
      initialFocusElement: initialFocusRef?.current,
      onEscape: () => onEscapeRef.current?.(),
      disableRestoreFocus: disableRestoreFocusRef.current,
    });

    trapRef.current = trap;
    trap.activate();

    let animId: number | null = null;
    let timerId: ReturnType<typeof setTimeout> | null = null;

    const delayedCheck = () => {
      if (!trap.getIsActive() || !containerRef.current) return;
      if (
        typeof document !== "undefined" &&
        (!document.activeElement ||
          !containerRef.current.contains(document.activeElement))
      ) {
        trap.setContainer(containerRef.current);
        if (initialFocusRef?.current) {
          trap.setInitialFocusElement(initialFocusRef.current);
        }
        trap.focusInitial();
      }
    };

    if (typeof requestAnimationFrame === "function") {
      animId = requestAnimationFrame(delayedCheck);
    } else {
      timerId = setTimeout(delayedCheck, 0);
    }

    return () => {
      if (animId !== null && typeof cancelAnimationFrame === "function") {
        cancelAnimationFrame(animId);
      }
      if (timerId !== null) {
        clearTimeout(timerId);
      }
      trap.deactivate();
      if (trapRef.current === trap) {
        trapRef.current = null;
      }
    };
  }, [isOpen, initialFocusRef]);

  return containerRef;
}

export default useFocusTrap;

import { describe, it, beforeEach, afterEach } from "node:test";
import assert from "node:assert/strict";
import {
  IdleTimerTracker,
  getStoredIdleTimeout,
  setStoredIdleTimeout,
  IDLE_TIMEOUT_STORAGE_KEY,
  DEFAULT_IDLE_TIMEOUT_SECONDS,
  DEFAULT_WARNING_SECONDS,
  TIMEOUT_OPTIONS,
} from "./useIdleTimer";

class MockLocalStorage {
  private store = new Map<string, string>();

  getItem(key: string): string | null {
    return this.store.get(key) ?? null;
  }

  setItem(key: string, value: string): void {
    const oldValue = this.store.get(key) ?? null;
    this.store.set(key, value);

    if (typeof (globalThis as any).window !== "undefined") {
      const storageEvent = {
        key,
        newValue: value,
        oldValue,
      } as StorageEvent;

      const listeners = (globalThis as any).__storageListeners || [];
      for (const listener of listeners) {
        listener(storageEvent);
      }
    }
  }

  removeItem(key: string): void {
    this.store.delete(key);
  }

  clear(): void {
    this.store.clear();
  }
}

describe("useIdleTimer / IdleTimerTracker", () => {
  let originalWindow: any;
  let mockStorage: MockLocalStorage;
  let storageListeners: Array<(e: StorageEvent) => void>;
  let windowListeners: Map<string, Set<EventListener>>;

  beforeEach(() => {
    originalWindow = (globalThis as any).window;
    mockStorage = new MockLocalStorage();
    storageListeners = [];
    windowListeners = new Map();

    (globalThis as any).__storageListeners = storageListeners;
    (globalThis as any).window = {
      localStorage: mockStorage,
      addEventListener: (type: string, listener: any) => {
        if (type === "storage") {
          storageListeners.push(listener);
        } else {
          if (!windowListeners.has(type)) {
            windowListeners.set(type, new Set());
          }
          windowListeners.get(type)!.add(listener);
        }
      },
      removeEventListener: (type: string, listener: any) => {
        if (type === "storage") {
          const idx = storageListeners.indexOf(listener);
          if (idx !== -1) storageListeners.splice(idx, 1);
        } else {
          windowListeners.get(type)?.delete(listener);
        }
      },
      dispatchEvent: (e: any) => {
        if (e.type === "storage") {
          for (const l of storageListeners) {
            l(e);
          }
        }
        return true;
      },
    };
  });

  afterEach(() => {
    (globalThis as any).window = originalWindow;
    delete (globalThis as any).__storageListeners;
  });

  it("loads default timeout when localStorage is empty", () => {
    assert.equal(getStoredIdleTimeout(), DEFAULT_IDLE_TIMEOUT_SECONDS);
  });

  it("loads and parses valid timeout from localStorage", () => {
    mockStorage.setItem(IDLE_TIMEOUT_STORAGE_KEY, "300");
    assert.equal(getStoredIdleTimeout(), 300);

    mockStorage.setItem(IDLE_TIMEOUT_STORAGE_KEY, "0");
    assert.equal(getStoredIdleTimeout(), 0);
  });

  it("falls back to default on invalid or corrupted storage values", () => {
    mockStorage.setItem(IDLE_TIMEOUT_STORAGE_KEY, "not-a-number");
    assert.equal(getStoredIdleTimeout(), DEFAULT_IDLE_TIMEOUT_SECONDS);

    mockStorage.setItem(IDLE_TIMEOUT_STORAGE_KEY, "-50");
    assert.equal(getStoredIdleTimeout(), DEFAULT_IDLE_TIMEOUT_SECONDS);
  });

  it("setStoredIdleTimeout saves to localStorage and dispatches storage event", () => {
    let receivedEvent: StorageEvent | null = null;
    (globalThis as any).window.addEventListener(
      "storage",
      (e: StorageEvent) => {
        receivedEvent = e;
      },
    );

    setStoredIdleTimeout(1800);
    assert.equal(mockStorage.getItem(IDLE_TIMEOUT_STORAGE_KEY), "1800");
    assert.ok(receivedEvent);
    assert.equal((receivedEvent as StorageEvent).key, IDLE_TIMEOUT_STORAGE_KEY);
    assert.equal((receivedEvent as StorageEvent).newValue, "1800");
  });

  it("provides expected timeout options with disabled and preset options", () => {
    assert.ok(TIMEOUT_OPTIONS.some((o) => o.value === 0));
    assert.ok(TIMEOUT_OPTIONS.some((o) => o.value === 300));
    assert.ok(TIMEOUT_OPTIONS.some((o) => o.value === 900));
    assert.ok(TIMEOUT_OPTIONS.some((o) => o.value === 1800));
    assert.ok(TIMEOUT_OPTIONS.some((o) => o.value === 3600));
  });

  it("tracks countdown and transitions to warning window then idle state", () => {
    let idleTriggered = false;
    let warningTriggeredWith: number | null = null;
    const tracker = new IdleTimerTracker({
      timeoutSeconds: 10,
      warningSeconds: 4,
      onIdle: () => {
        idleTriggered = true;
      },
      onWarning: (sec) => {
        warningTriggeredWith = sec;
      },
    });

    try {
      const state0 = tracker.getState();
      assert.equal(state0.isIdle, false);
      assert.equal(state0.isWarning, false);
      assert.equal(state0.remainingSeconds, 10);

      // Tick 5 seconds later: 5s remaining, warning threshold is 4s -> neither warning nor idle
      const baseTime = Date.now();
      tracker.tick(baseTime + 5000);
      assert.equal(tracker.getState().isIdle, false);
      assert.equal(tracker.getState().isWarning, false);
      assert.equal(tracker.getState().remainingSeconds, 5);

      // Tick 7 seconds later: 3s remaining, <= warningSeconds (4s) -> isWarning true
      tracker.tick(baseTime + 7000);
      assert.equal(tracker.getState().isIdle, false);
      assert.equal(tracker.getState().isWarning, true);
      assert.equal(tracker.getState().remainingSeconds, 3);
      assert.equal(warningTriggeredWith, 3);

      // Tick 10 seconds later: 0s remaining -> isIdle true
      tracker.tick(baseTime + 10000);
      assert.equal(tracker.getState().isIdle, true);
      assert.equal(tracker.getState().isWarning, false);
      assert.equal(tracker.getState().remainingSeconds, 0);
      assert.equal(idleTriggered, true);
    } finally {
      tracker.destroy();
    }
  });

  it("user activity resets timer and clears warning state", () => {
    let activeTriggered = false;
    const tracker = new IdleTimerTracker({
      timeoutSeconds: 10,
      warningSeconds: 4,
      onActive: () => {
        activeTriggered = true;
      },
    });

    try {
      const baseTime = Date.now();
      tracker.tick(baseTime + 8000);
      assert.equal(tracker.getState().isWarning, true);

      // Activity occurs
      const handled = tracker.recordActivity(baseTime + 8500);
      assert.equal(handled, true);
      assert.equal(tracker.getState().isWarning, false);
      assert.equal(tracker.getState().remainingSeconds, 10);
      assert.equal(activeTriggered, true);
    } finally {
      tracker.destroy();
    }
  });

  it("user activity does NOT dismiss idle lock once already idle", () => {
    const tracker = new IdleTimerTracker({
      timeoutSeconds: 5,
      warningSeconds: 2,
    });

    try {
      tracker.lock();
      assert.equal(tracker.getState().isIdle, true);

      const handled = tracker.recordActivity(Date.now() + 10000);
      assert.equal(handled, false);
      assert.equal(tracker.getState().isIdle, true);
    } finally {
      tracker.destroy();
    }
  });

  it("manual lock immediately locks session and manual unlock resets it", () => {
    let idleTriggered = false;
    const tracker = new IdleTimerTracker({
      timeoutSeconds: 100,
      onIdle: () => {
        idleTriggered = true;
      },
    });

    try {
      tracker.lock();
      assert.equal(tracker.getState().isIdle, true);
      assert.equal(tracker.getState().remainingSeconds, 0);
      assert.equal(idleTriggered, true);

      tracker.unlock();
      assert.equal(tracker.getState().isIdle, false);
      assert.equal(tracker.getState().remainingSeconds, 100);
    } finally {
      tracker.destroy();
    }
  });

  it("disabled timeout (0) never triggers warning or idle", () => {
    let idleTriggered = false;
    let warningTriggered = false;
    const tracker = new IdleTimerTracker({
      timeoutSeconds: 0,
      warningSeconds: 5,
      onIdle: () => {
        idleTriggered = true;
      },
      onWarning: () => {
        warningTriggered = true;
      },
    });

    try {
      const future = Date.now() + 1000000;
      tracker.tick(future);
      assert.equal(tracker.getState().isIdle, false);
      assert.equal(tracker.getState().isWarning, false);
      assert.equal(idleTriggered, false);
      assert.equal(warningTriggered, false);
    } finally {
      tracker.destroy();
    }
  });

  it("synchronizes timeout changes via storage events", () => {
    const tracker = new IdleTimerTracker({
      timeoutSeconds: 900,
    });

    try {
      assert.equal(tracker.getState().timeoutSeconds, 900);

      // Simulate storage event from another tab
      mockStorage.setItem(IDLE_TIMEOUT_STORAGE_KEY, "1800");

      assert.equal(tracker.getState().timeoutSeconds, 1800);
      assert.equal(tracker.getState().remainingSeconds, 1800);
    } finally {
      tracker.destroy();
    }
  });
});

import { useState, useEffect, useRef, useCallback } from "react";

export const IDLE_TIMEOUT_STORAGE_KEY = "seedarr-idle-timeout";
export const DEFAULT_IDLE_TIMEOUT_SECONDS = 900; // 15 minutes
export const DEFAULT_WARNING_SECONDS = 60; // 60 seconds warning countdown

export interface TimeoutOption {
  value: number;
  label: string;
}

export const TIMEOUT_OPTIONS: TimeoutOption[] = [
  { value: 0, label: "Disabled" },
  { value: 300, label: "5 minutes" },
  { value: 900, label: "15 minutes (Default)" },
  { value: 1800, label: "30 minutes" },
  { value: 3600, label: "1 hour" },
];

/**
 * Retrieves the configured idle timeout from localStorage.
 * Defaults to 900 seconds (15 minutes).
 */
export function getStoredIdleTimeout(): number {
  if (typeof window === "undefined" || !window.localStorage) {
    return DEFAULT_IDLE_TIMEOUT_SECONDS;
  }
  try {
    const raw = window.localStorage.getItem(IDLE_TIMEOUT_STORAGE_KEY);
    if (raw === null || raw === undefined) {
      return DEFAULT_IDLE_TIMEOUT_SECONDS;
    }
    const parsed = parseInt(raw, 10);
    return Number.isNaN(parsed) || parsed < 0
      ? DEFAULT_IDLE_TIMEOUT_SECONDS
      : parsed;
  } catch {
    return DEFAULT_IDLE_TIMEOUT_SECONDS;
  }
}

/**
 * Stores the idle timeout preference to localStorage and dispatches a storage event.
 */
export function setStoredIdleTimeout(seconds: number): void {
  const val = Math.max(0, seconds);
  if (typeof window !== "undefined" && window.localStorage) {
    try {
      window.localStorage.setItem(IDLE_TIMEOUT_STORAGE_KEY, String(val));
      if (typeof window.dispatchEvent === "function") {
        window.dispatchEvent(
          new StorageEvent("storage", {
            key: IDLE_TIMEOUT_STORAGE_KEY,
            newValue: String(val),
          }),
        );
      }
    } catch {
      // ignore quota or security exceptions
    }
  }
}

export interface IdleTimerTrackerOptions {
  timeoutSeconds?: number;
  warningSeconds?: number;
  enabled?: boolean;
  throttleMs?: number;
  onIdle?: () => void;
  onWarning?: (remainingSeconds: number) => void;
  onActive?: () => void;
  onChange?: (state: IdleTimerState) => void;
}

export interface IdleTimerState {
  isIdle: boolean;
  isWarning: boolean;
  remainingSeconds: number;
  timeoutSeconds: number;
}

export class IdleTimerTracker {
  private timeoutSeconds: number;
  private warningSeconds: number;
  private enabled: boolean;
  private throttleMs: number;
  private isIdle = false;
  private isWarning = false;
  private remainingSeconds: number;
  private lastActivity: number;
  private lastThrottled = 0;
  private timerId: ReturnType<typeof setInterval> | null = null;
  private boundActivityHandler: (() => void) | null = null;
  private boundStorageHandler: ((e: StorageEvent) => void) | null = null;

  public onIdle?: () => void;
  public onWarning?: (remainingSeconds: number) => void;
  public onActive?: () => void;
  public onChange?: (state: IdleTimerState) => void;

  constructor(options: IdleTimerTrackerOptions = {}) {
    this.timeoutSeconds =
      options.timeoutSeconds !== undefined
        ? options.timeoutSeconds
        : getStoredIdleTimeout();
    this.warningSeconds = options.warningSeconds ?? DEFAULT_WARNING_SECONDS;
    this.enabled = options.enabled ?? true;
    this.throttleMs = options.throttleMs ?? 500;
    this.remainingSeconds = this.timeoutSeconds;
    this.lastActivity = Date.now();

    this.onIdle = options.onIdle;
    this.onWarning = options.onWarning;
    this.onActive = options.onActive;
    this.onChange = options.onChange;

    this.setupListeners();
    this.startInterval();
  }

  public getState(): IdleTimerState {
    return {
      isIdle: this.isIdle,
      isWarning: this.isWarning,
      remainingSeconds: this.remainingSeconds,
      timeoutSeconds: this.timeoutSeconds,
    };
  }

  private emitChange(): void {
    if (this.onChange) {
      this.onChange(this.getState());
    }
  }

  public setTimeoutSeconds(seconds: number): void {
    this.timeoutSeconds = Math.max(0, seconds);
    this.remainingSeconds = this.timeoutSeconds;
    this.isWarning = false;
    this.lastActivity = Date.now();
    setStoredIdleTimeout(this.timeoutSeconds);
    this.emitChange();
  }

  public setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    if (!enabled) {
      this.isWarning = false;
      this.emitChange();
    }
  }

  public reset(): void {
    this.lastActivity = Date.now();
    this.isIdle = false;
    this.isWarning = false;
    this.remainingSeconds = this.timeoutSeconds;
    this.emitChange();
    this.onActive?.();
  }

  public lock(): void {
    this.isIdle = true;
    this.isWarning = false;
    this.remainingSeconds = 0;
    this.emitChange();
    this.onIdle?.();
  }

  public unlock(): void {
    this.reset();
  }

  public recordActivity(now: number = Date.now()): boolean {
    // If screen is locked, activity does NOT unlock it!
    if (this.isIdle) {
      return false;
    }

    if (now - this.lastThrottled < this.throttleMs) {
      return false;
    }

    this.lastThrottled = now;
    this.lastActivity = now;

    const hadWarning = this.isWarning;
    this.isWarning = false;
    this.remainingSeconds = this.timeoutSeconds;
    this.emitChange();

    if (hadWarning) {
      this.onActive?.();
    }
    return true;
  }

  public tick(now: number = Date.now()): void {
    if (!this.enabled || this.timeoutSeconds <= 0 || this.isIdle) {
      if ((!this.enabled || this.timeoutSeconds <= 0) && this.isWarning) {
        this.isWarning = false;
        this.emitChange();
      }
      return;
    }

    const elapsed = Math.floor((now - this.lastActivity) / 1000);
    const remaining = Math.max(0, this.timeoutSeconds - elapsed);
    this.remainingSeconds = remaining;

    if (remaining <= 0) {
      this.isIdle = true;
      this.isWarning = false;
      this.remainingSeconds = 0;
      this.emitChange();
      this.onIdle?.();
    } else if (remaining <= this.warningSeconds) {
      const wasWarning = this.isWarning;
      this.isWarning = true;
      this.emitChange();
      if (!wasWarning) {
        this.onWarning?.(remaining);
      }
    } else {
      if (this.isWarning) {
        this.isWarning = false;
        this.emitChange();
      }
    }
  }

  private setupListeners(): void {
    if (
      typeof window === "undefined" ||
      typeof window.addEventListener !== "function"
    ) {
      return;
    }

    const events = [
      "keydown",
      "pointerdown",
      "mousemove",
      "touchstart",
      "scroll",
      "wheel",
    ];

    this.boundActivityHandler = () => {
      this.recordActivity();
    };

    events.forEach((evt) => {
      window.addEventListener(evt, this.boundActivityHandler!, {
        passive: true,
      });
    });

    this.boundStorageHandler = (e: StorageEvent) => {
      if (e.key === IDLE_TIMEOUT_STORAGE_KEY && e.newValue !== null) {
        const val = parseInt(e.newValue, 10);
        if (!Number.isNaN(val) && val >= 0 && val !== this.timeoutSeconds) {
          this.timeoutSeconds = val;
          this.remainingSeconds = val;
          this.isWarning = false;
          this.lastActivity = Date.now();
          this.emitChange();
        }
      }
    };

    window.addEventListener("storage", this.boundStorageHandler);
  }

  private startInterval(): void {
    if (typeof setInterval === "function") {
      this.timerId = setInterval(() => {
        this.tick();
      }, 1000);
    }
  }

  public destroy(): void {
    if (this.timerId) {
      clearInterval(this.timerId);
      this.timerId = null;
    }

    if (
      typeof window !== "undefined" &&
      typeof window.removeEventListener === "function"
    ) {
      if (this.boundActivityHandler) {
        const events = [
          "keydown",
          "pointerdown",
          "mousemove",
          "touchstart",
          "scroll",
          "wheel",
        ];
        events.forEach((evt) => {
          window.removeEventListener(evt, this.boundActivityHandler!);
        });
        this.boundActivityHandler = null;
      }

      if (this.boundStorageHandler) {
        window.removeEventListener("storage", this.boundStorageHandler);
        this.boundStorageHandler = null;
      }
    }
  }
}

export interface UseIdleTimerOptions {
  timeoutSeconds?: number;
  warningSeconds?: number;
  enabled?: boolean;
  onIdle?: () => void;
  onWarning?: (remainingSeconds: number) => void;
  onActive?: () => void;
}

export interface UseIdleTimerReturn {
  isIdle: boolean;
  isWarning: boolean;
  remainingSeconds: number;
  timeoutSeconds: number;
  setTimeoutSeconds: (seconds: number) => void;
  resetTimer: () => void;
  lockSession: () => void;
  unlockSession: () => void;
}

/**
 * React Hook for tracking user activity and session inactivity timeout.
 */
export function useIdleTimer(
  options: UseIdleTimerOptions = {},
): UseIdleTimerReturn {
  const {
    timeoutSeconds: explicitTimeout,
    warningSeconds = DEFAULT_WARNING_SECONDS,
    enabled = true,
    onIdle,
    onWarning,
    onActive,
  } = options;

  const [state, setState] = useState<IdleTimerState>(() => {
    const timeout =
      explicitTimeout !== undefined ? explicitTimeout : getStoredIdleTimeout();
    return {
      isIdle: false,
      isWarning: false,
      remainingSeconds: timeout,
      timeoutSeconds: timeout,
    };
  });

  const trackerRef = useRef<IdleTimerTracker | null>(null);
  const callbacksRef = useRef({ onIdle, onWarning, onActive });
  callbacksRef.current = { onIdle, onWarning, onActive };

  useEffect(() => {
    const tracker = new IdleTimerTracker({
      timeoutSeconds: explicitTimeout,
      warningSeconds,
      enabled,
      onIdle: () => callbacksRef.current.onIdle?.(),
      onWarning: (sec) => callbacksRef.current.onWarning?.(sec),
      onActive: () => callbacksRef.current.onActive?.(),
      onChange: (next) => setState(next),
    });

    trackerRef.current = tracker;

    return () => {
      tracker.destroy();
      trackerRef.current = null;
    };
  }, [explicitTimeout, warningSeconds]);

  useEffect(() => {
    if (trackerRef.current) {
      trackerRef.current.setEnabled(enabled);
    }
  }, [enabled]);

  const setTimeoutSeconds = useCallback((seconds: number) => {
    trackerRef.current?.setTimeoutSeconds(seconds);
  }, []);

  const resetTimer = useCallback(() => {
    trackerRef.current?.reset();
  }, []);

  const lockSession = useCallback(() => {
    trackerRef.current?.lock();
  }, []);

  const unlockSession = useCallback(() => {
    trackerRef.current?.unlock();
  }, []);

  return {
    isIdle: state.isIdle,
    isWarning: state.isWarning,
    remainingSeconds: state.remainingSeconds,
    timeoutSeconds: state.timeoutSeconds,
    setTimeoutSeconds,
    resetTimer,
    lockSession,
    unlockSession,
  };
}

import { create } from "zustand";
import { LocaleCode, TranslationDictionary, TranslationParams } from "./types";
import {
  DEFAULT_LOCALE,
  STORAGE_KEY_LANGUAGE,
  detectBrowserLanguage,
  getLanguageMetadata,
  isSupportedLocale,
} from "./languages";
import { dictionaries } from "./locales";

function getNestedValue(
  obj: TranslationDictionary | undefined,
  path: string,
): string | undefined {
  if (!obj) return undefined;
  const parts = path.split(".");
  let current: any = obj;
  for (const part of parts) {
    if (
      current === undefined ||
      current === null ||
      typeof current !== "object"
    ) {
      return undefined;
    }
    current = current[part];
  }
  return typeof current === "string" ? current : undefined;
}

function interpolate(text: string, params?: TranslationParams): string {
  if (!params) return text;
  let result = text;
  if (Array.isArray(params)) {
    params.forEach((val, idx) => {
      result = result.split(`{${idx}}`).join(String(val));
    });
  } else if (typeof params === "object") {
    for (const [key, val] of Object.entries(params)) {
      result = result
        .split(`{{${key}}}`)
        .join(String(val))
        .split(`{${key}}`)
        .join(String(val));
    }
  }
  return result;
}

function syncDomAttributes(locale: LocaleCode) {
  if (typeof document === "undefined") return;
  const meta = getLanguageMetadata(locale);
  document.documentElement.lang = locale;
  document.documentElement.dir = meta.rtl ? "rtl" : "ltr";
}

export function extractDefaultValue(
  params?: any,
  defaultVal?: any,
): { fallbackDefault?: string; interpolationParams?: TranslationParams } {
  if (typeof params === "string") {
    if (typeof defaultVal === "object" && defaultVal !== null) {
      return { fallbackDefault: params, interpolationParams: defaultVal };
    }
    return { fallbackDefault: params, interpolationParams: undefined };
  }
  let fallbackDefault = typeof defaultVal === "string" ? defaultVal : undefined;
  let interpolationParams = params;
  if (
    params &&
    typeof params === "object" &&
    !Array.isArray(params) &&
    "defaultValue" in params
  ) {
    fallbackDefault =
      (params as { defaultValue?: string }).defaultValue ?? fallbackDefault;
    const { defaultValue: _, ...rest } = params as Record<string, any>;
    interpolationParams = rest;
  }
  return { fallbackDefault, interpolationParams };
}

export interface I18nState {
  locale: LocaleCode;
  setLocale: (locale: LocaleCode) => void;
  t: (key: string, params?: TranslationParams, defaultVal?: string) => string;
}

const initialLocale: LocaleCode = detectBrowserLanguage();
syncDomAttributes(initialLocale);

export const useI18nStore = create<I18nState>((set, get) => ({
  locale: initialLocale,
  setLocale: (locale: LocaleCode) => {
    if (!isSupportedLocale(locale)) return;
    try {
      localStorage.setItem(STORAGE_KEY_LANGUAGE, locale);
    } catch {
      // ignore
    }
    syncDomAttributes(locale);
    set({ locale });
  },
  t: (key: string, params?: TranslationParams, defaultVal?: string): string => {
    const { fallbackDefault, interpolationParams } = extractDefaultValue(
      params,
      defaultVal,
    );
    const currentLocale = get().locale;
    const currentDict = dictionaries[currentLocale];
    const defaultDict = dictionaries[DEFAULT_LOCALE];

    // 1. Current locale lookup
    let template = getNestedValue(currentDict, key);

    // 2. Fallback to default (en) locale
    if (template === undefined && currentLocale !== DEFAULT_LOCALE) {
      template = getNestedValue(defaultDict, key);
    }

    // 3. Fallback to fallbackDefault or key itself
    if (template === undefined) {
      template = fallbackDefault !== undefined ? fallbackDefault : key;
    }

    return interpolate(template, interpolationParams);
  },
}));

export type LocaleCode =
  | "en"
  | "zh-CN"
  | "es"
  | "de"
  | "fr"
  | "pt"
  | "ru"
  | "it"
  | "ja"
  | "ko"
  | "hi"
  | "ar"
  | "id"
  | "tr"
  | "vi"
  | "bn"
  | "mr"
  | "te"
  | "ta"
  | "ur";

export interface Language {
  code: LocaleCode;
  name: string;
  nativeName: string;
  flag: string;
  rtl?: boolean;
}

export interface TranslationOptions {
  defaultValue?: string;
  [key: string]: any;
}

export type TranslationParams =
  TranslationOptions | (string | number)[] | string;

export type TranslationDictionary = {
  [key: string]: string | TranslationDictionary;
};

import { useCallback } from "react";
import { extractDefaultValue, useI18nStore } from "./i18nStore";
import { SUPPORTED_LANGUAGES, getLanguageMetadata } from "./languages";
import { LocaleCode, TranslationParams } from "./types";

export type TFunction = {
  (key: string, defaultValue?: string, params?: TranslationParams): string;
  (key: string, params?: TranslationParams, defaultValue?: string): string;
};

export function useTranslation() {
  const locale = useI18nStore((state) => state.locale);
  const setLocale = useI18nStore((state) => state.setLocale);
  const rawT = useI18nStore((state) => state.t);

  const t: TFunction = useCallback(
    (key: string, arg1?: any, arg2?: any) => {
      const { fallbackDefault, interpolationParams } = extractDefaultValue(
        arg1,
        arg2,
      );
      return rawT(key, interpolationParams, fallbackDefault);
    },
    [rawT, locale],
  ) as TFunction;

  const currentLanguage = getLanguageMetadata(locale);

  return {
    t,
    locale,
    setLocale,
    currentLanguage,
    languages: SUPPORTED_LANGUAGES,
  };
}

export function translate(key: string, arg1?: any, arg2?: any): string {
  const { fallbackDefault, interpolationParams } = extractDefaultValue(
    arg1,
    arg2,
  );
  return useI18nStore.getState().t(key, interpolationParams, fallbackDefault);
}

