export interface PropertyDef {
  value: string;
  label: string;
  group: string;
  type: "boolean" | "enum" | "category" | "number" | "string" | "custom";
  options?: { value: string; label: string }[];
  defaultOp: ">" | "<" | ">=" | "<=" | "==" | "!=";
  defaultValue: string;
  placeholder?: string;
  unit?: "bytes" | "speed" | "ratio" | "percent" | "count";
  presets?: { label: string; value: string }[];
}

