      if (v)
        currentStep.actions.push({
          id: `act-${Date.now()}-${Math.random()}`,
          type: "runScript",
          value: v[1],
        });
    } else if (
      currentStep &&
      inActions &&
      (trimmed.startsWith("- delay:") || trimmed.startsWith("- sleep:"))
    ) {
      const v = trimmed.match(/- (?:delay|sleep):\s*['"]?([^'"]+)['"]?/);
      if (v)
        currentStep.actions.push({
          id: `act-${Date.now()}-${Math.random()}`,
          type: "delay",
          value: v[1],
        });
