  const [logModalOpen, setLogModalOpen] = useState(false);
  const [viewingLog, setViewingLog] = useState<{
    name: string;
    trigger?: string;
    time?: string;
    log: string;
    status: string;
    durationMs?: number;
  } | null>(null);

  const [installModalOpen, setInstallModalOpen] = useState(false);
  const [selectedTemplate, setSelectedTemplate] =
    useState<AutomationMarketplaceTemplate | null>(null);
  const [templateInputs, setTemplateInputs] = useState<Record<string, string>>(
    {},
  );
  const [customInstallName, setCustomInstallName] = useState("");

  // Test Runner state in Editor
  const [testTorrentId, setTestTorrentId] = useState<number | undefined>(
    undefined,
  );
  const [testResult, setTestResult] =
    useState<AutomationExecutionResult | null>(null);
  const [isTesting, setIsTesting] = useState(false);
  const [isRunningId, setIsRunningId] = useState<number | null>(null);

  const scriptList = scripts || [];
  const templateList = templates || [];

  const filteredScripts = useMemo(() => {
    return scriptList.filter((s) => {
      if (
        selectedTriggerFilter !== "All" &&
        s.trigger.toString() !== selectedTriggerFilter
      ) {
        return false;
      }
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const matchName = s.name.toLowerCase().includes(q);
        const matchDesc = s.description?.toLowerCase().includes(q) || false;
        if (!matchName && !matchDesc) return false;
      }
      return true;
    });
  }, [scriptList, selectedTriggerFilter, searchQuery]);

  const filteredTemplates = useMemo(() => {
    return templateList.filter((tmpl) => {
      if (
        selectedCategoryFilter !== "All" &&
        tmpl.category !== selectedCategoryFilter
      ) {
        return false;
      }
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const matchName = tmpl.name.toLowerCase().includes(q);
        const matchDesc = tmpl.description.toLowerCase().includes(q);
        if (!matchName && !matchDesc) return false;
      }
      return true;
    });
  }, [templateList, selectedCategoryFilter, searchQuery]);

  const marketplaceCategories = useMemo(() => {
    const set = new Set<string>();
    templateList.forEach((tmpl) => set.add(tmpl.category));
    return ["All", ...Array.from(set)];
  }, [templateList]);

  // Sync visual steps when editing script opens
  useEffect(() => {
    if (editingScript) {
      if (editingScript.language === "Yaml" || editingScript.language === 1) {
        setVisualSteps(yamlToVisualSteps(editingScript.code || ""));
      } else {
        setEditorMode("code");
      }
    }
  }, [editingScript?.id, editingScript?.language]);

  // Sync visual steps back to YAML code
  function updateVisualSteps(newSteps: VisualStep[]) {
    setVisualSteps(newSteps);
    if (editingScript) {
      const generatedYaml = visualStepsToYaml(
        editingScript.name || "Automation Pipeline",
        editingScript.trigger?.toString() || "TorrentCompleted",
        newSteps,
      );
      setEditingScript({ ...editingScript, code: generatedYaml });
    }
  }

  function openNewScript(language: "Yaml" | "JavaScript" = "Yaml") {
    const initialSteps: VisualStep[] = [
      {
        id: "step-1",
        name: "Filter Large Torrents",
        conditionEnabled: true,
        conditionLeft: "${torrent.size}",
        conditionOp: ">",
        conditionRight: "5000000000",
        hasHttp: false,
        http: { method: "POST", url: "", json: true, body: "{}", register: "" },
        actions: [
          { id: "act-1", type: "addTag", value: "Large-Release" },
          { id: "act-2", type: "command", value: "Backup" },
        ],
      },
    ];

    const initialCode =
      language === "Yaml"
        ? visualStepsToYaml(
            "New Automation Pipeline",
            "TorrentCompleted",
            initialSteps,
          )
        : `// Contexts: torrent, system, api, http, html, inputs, secrets, console
if (torrent && torrent.size > 5000000000) {
  torrent.addTag('Large-Release');
}
`;

    setEditingScript({
      name:
        language === "Yaml" ? "New Automation Pipeline" : "New Custom Script",
      description: "",
      trigger: "TorrentCompleted",
      language: language,
      code: initialCode,
      inputsJson: "{}",
      isEnabled: true,
      targetCategories: [],
      targetTagIds: [],
    });
    setVisualSteps(initialSteps);
    setEditorMode(language === "Yaml" ? "visual" : "code");
    setTestResult(null);
    setEditorOpen(true);
  }

  function openEditScript(script: AutomationScript) {
    setEditingScript({
      ...script,
      targetCategories: script.targetCategories || [],
      targetTagIds: script.targetTagIds || [],
    });
    const isYaml = script.language === "Yaml" || script.language === 1;
    if (isYaml) {
      setVisualSteps(yamlToVisualSteps(script.code || ""));
      setEditorMode("visual");
    } else {
      setEditorMode("code");
    }
    setTestResult(null);
    setEditorOpen(true);
  }

  function handleSaveScript() {
    if (!editingScript || !editingScript.name?.trim()) return;

    let finalScript = { ...editingScript };
    if (
      (finalScript.language === "Yaml" || finalScript.language === 1) &&
      editorMode === "visual"
    ) {
      finalScript.code = visualStepsToYaml(
        finalScript.name || "Pipeline",
        finalScript.trigger?.toString() || "TorrentCompleted",
        visualSteps,
      );
    }

    if (finalScript.id && finalScript.id > 0) {
      trackAutomationAction("update", String(finalScript.trigger || "manual"));
      updateScript.mutate(finalScript as AutomationScript, {
        onSuccess: () => setEditorOpen(false),
      });
    } else {
      trackAutomationAction("create", String(finalScript.trigger || "manual"));
      createScript.mutate(finalScript, {
        onSuccess: () => setEditorOpen(false),
      });
    }
  }

  function handleDeleteScript(id: number) {
    if (
      window.confirm(
        "Are you sure you want to delete this automation pipeline?",
      )
    ) {
      trackAutomationAction("delete");
      deleteScript.mutate(id);
    }
  }

  function handleToggleEnabled(script: AutomationScript) {
    trackAutomationAction(
      script.isEnabled ? "disable" : "enable",
      String(script.trigger || "manual"),
    );
    updateScript.mutate({
      ...script,
      isEnabled: !script.isEnabled,
    });
  }

  function handleRunNow(id: number, torrentId?: number) {
    setIsRunningId(id);
    const targetScript = scriptList.find((s) => s.id === id);
    trackAutomationAction("run_now", String(targetScript?.trigger || "manual"));
    runScript.mutate(
      { id, torrentId },
      {
        onSuccess: (res) => {
          setIsRunningId(null);
          setViewingLog({
            name: targetScript?.name || `Script #${id}`,
            trigger: targetScript?.trigger?.toString() || "Manual",
            time: new Date().toLocaleTimeString(),
            log:
              res.outputLog ||
              (res.success
                ? "Completed with no output."
                : res.error || "Failed"),
            status: res.success ? "Success" : "Failed",
            durationMs: res.executionTimeMs,
          });
          setLogModalOpen(true);
        },
        onError: (err) => {
          setIsRunningId(null);
          alert(`Execution error: ${err.message}`);
        },
      },
    );
  }

  function handleDryRun() {
    if (!editingScript) return;
    setIsTesting(true);
    setTestResult(null);

    let scriptPayload = { ...editingScript };
    if (
      (scriptPayload.language === "Yaml" || scriptPayload.language === 1) &&
      editorMode === "visual"
    ) {
      scriptPayload.code = visualStepsToYaml(
        scriptPayload.name || "Pipeline",
        scriptPayload.trigger?.toString() || "TorrentCompleted",
        visualSteps,
      );
    }

    testScript.mutate(
      {
        script: scriptPayload,
        torrentId: testTorrentId || (torrents && torrents[0]?.id),
      },
      {
        onSuccess: (res) => {
          setTestResult(res);
          setIsTesting(false);
        },
        onError: (err) => {
          setIsTesting(false);
          setTestResult({
            success: false,
            error: err.message,
            executionTimeMs: 0,
            tagsToAdd: [],
            tagsToRemove: [],
            shouldPause: false,
            shouldResume: false,
            shouldRemove: false,
            deleteDataOnRemove: false,
            shouldRecheck: false,
            shouldReannounce: false,
            shouldBoostTracker: false,
          });
        },
      },
    );
  }

  function handleInstallTemplate() {
    if (!selectedTemplate) return;

    for (const field of selectedTemplate.inputFields || []) {
      const val =
        templateInputs[field.key] !== undefined
          ? templateInputs[field.key]
          : field.defaultValue;
      if (field.required && (!val || !val.trim())) {
        alert(`Field "${field.label}" is required.`);
        return;
      }
      if (val && field.type === "number" && isNaN(Number(val))) {
        alert(`Field "${field.label}" must be a valid number.`);
        return;
      }
      if (val && field.type === "url") {
        let isValidUrl = false;
        try {
          const u = new URL(val);
          isValidUrl = u.protocol === "http:" || u.protocol === "https:";
        } catch {
          isValidUrl = false;
        }

        if (!isValidUrl) {
          alert(`Field "${field.label}" must be a valid HTTP or HTTPS URL.`);
          return;
        }
      }
      if (val && field.maxLength && val.length > field.maxLength) {
        alert(
          `Field "${field.label}" exceeds maximum length of ${field.maxLength} characters.`,
        );
        return;
      }
    }

    trackAutomationAction(
      "install_template",
      selectedTemplate.name || selectedTemplate.id,
    );
    installTemplate.mutate(
      {
        templateId: selectedTemplate.id,
        customName: customInstallName || selectedTemplate.name,
        customInputs: templateInputs,
      },
      {
        onSuccess: () => {
          setInstallModalOpen(false);
          setActiveTab("scripts");
        },
        onError: (err) => {
          alert(`Installation failed: ${err.message}`);
        },
      },
    );
  }

  return (
    <div className="content-area" style={{ padding: "1.5rem" }}>
      {/* Header Banner */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "1.5rem",
          flexWrap: "wrap",
          gap: "1rem",
        }}
      >
        <div>
          <h1
            style={{
              fontSize: "1.75rem",
              fontWeight: 700,
              margin: 0,
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
            }}
          >
            <span>⚡</span> {t("automation.ui.automationPipelinesMarketplace")}
          </h1>
          <p
            style={{
              color: "var(--text-muted, #888)",
              margin: "0.25rem 0 0 0",
              fontSize: "0.9rem",
            }}
          >
            {t("automation.ui.visualDraganddropWorkflowBuild")}
          </p>
        </div>

        <div style={{ display: "flex", gap: "0.75rem" }}>
          <button
            className={`btn ${activeTab === "scripts" ? "btn-primary" : "btn-secondary"}`}
            onClick={() => setActiveTab("scripts")}
          >
            {t("automation.tabs.visual")} ({scriptList.length})
          </button>
          <button
            className={`btn ${activeTab === "history" ? "btn-primary" : "btn-secondary"}`}
            onClick={() => setActiveTab("history")}
          >
            {t("automation.tabs.logs")}
          </button>
          <button
            className={`btn ${activeTab === "marketplace" ? "btn-primary" : "btn-secondary"}`}
            onClick={() => setActiveTab("marketplace")}
          >
            {t("automation.tabs.marketplace")} ({templateList.length})
          </button>
        </div>
      </div>

      {/* TAB 1: MY SCRIPTS / PIPELINES */}
      {activeTab === "scripts" && (
        <div>
          {/* Action Bar */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "1rem",
              flexWrap: "wrap",
              gap: "0.75rem",
            }}
          >
            <div
              style={{ display: "flex", gap: "0.5rem", alignItems: "center" }}
            >
              <input
                type="text"
                placeholder={t("automation.ui.searchPipelines")}
                className="input"
                style={{ width: "240px" }}
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
              <select
                className="input"
                style={{ width: "190px" }}
                value={selectedTriggerFilter}
                onChange={(e) => setSelectedTriggerFilter(e.target.value)}
              >
                <option value="All">{t("automation.ui.allTriggers")}</option>
                {Object.entries(getTriggerLabels(t)).map(([k, label]) => (
                  <option key={k} value={k}>
                    {label}
                  </option>
                ))}
              </select>
            </div>

            <div style={{ display: "flex", gap: "0.5rem" }}>
              <button
                className="btn btn-primary"
                onClick={() => openNewScript("Yaml")}
              >
                ✨ + {t("automation.tabs.visual")}
              </button>
              <button
                className="btn btn-secondary"
                onClick={() => openNewScript("JavaScript")}
              >
                {t("automation.ui.javascriptScript")}
              </button>
            </div>
          </div>

          {loadingScripts ? (
            <div
              className="panel"
              style={{
                padding: "2rem",
                textAlign: "center",
                color: "var(--text-muted)",
              }}
            >
              {t("automation.ui.loadingAutomationPipelines")}
            </div>
          ) : filteredScripts.length === 0 ? (
            <div
              className="panel"
              style={{ padding: "3rem", textAlign: "center" }}
            >
              <div style={{ fontSize: "2.5rem", marginBottom: "0.5rem" }}>
                {t("automation.ui.text1")}
              </div>
              <h3 style={{ margin: "0 0 0.5rem 0" }}>
                {t("automation.ui.noAutomationPipelinesFound")}
              </h3>
              <p
                style={{
                  color: "var(--text-muted)",
                  maxWidth: "480px",
                  margin: "0 auto 1.5rem auto",
                }}
              >
                {t("automation.ui.createAutomatedActionsForWhen")}
              </p>
              <div
                style={{
                  display: "flex",
                  gap: "0.5rem",
                  justifyContent: "center",
                }}
              >
                <button
                  className="btn btn-primary"
                  onClick={() => openNewScript("Yaml")}
                >
                  {t("automation.ui.buildVisualPipeline")}
                </button>
                <button
                  className="btn btn-secondary"
                  onClick={() => setActiveTab("marketplace")}
                >
                  {t("automation.ui.browseMarketplace")}
                </button>
              </div>
            </div>
          ) : (
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(360px, 1fr))",
                gap: "1rem",
              }}
            >
              {filteredScripts.map((script) => (
                <div
                  key={script.id}
                  className="panel"
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "space-between",
                    borderLeft: `4px solid ${script.isEnabled ? "var(--accent, #3b82f6)" : "var(--border, #444)"}`,
                    padding: "1.25rem",
                  }}
                >
                  <div>
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "flex-start",
                        marginBottom: "0.5rem",
                      }}
                    >
                      <div>
                        <h3
                          style={{
                            margin: 0,
                            fontSize: "1.1rem",
                            fontWeight: 600,
                          }}
                        >
                          {script.name}
                        </h3>
                        <span
                          style={{
                            fontSize: "0.75rem",
                            color: "var(--text-muted)",
                          }}
                        >
                          {script.language === 1 || script.language === "Yaml"
                            ? "📦 Visual Pipeline (YAML)"
                            : "💻 JavaScript"}
                        </span>
                      </div>
                      <label
                        style={{
                          display: "flex",
                          alignItems: "center",
                          cursor: "pointer",
                          gap: "0.35rem",
                        }}
                      >
                        <input
                          type="checkbox"
                          checked={script.isEnabled}
                          onChange={() => handleToggleEnabled(script)}
                        />
                        <span style={{ fontSize: "0.8rem", fontWeight: 600 }}>
                          {script.isEnabled ? "Active" : "Disabled"}
                        </span>
                      </label>
                    </div>

                    <p
                      style={{
                        fontSize: "0.85rem",
                        color: "var(--text-muted)",
                        margin: "0 0 0.75rem 0",
                        minHeight: "2.4rem",
                      }}
                    >
                      {script.description || "No description provided."}
                    </p>

                    <div
                      style={{
                        display: "flex",
                        flexWrap: "wrap",
                        gap: "0.35rem",
                        marginBottom: "1rem",
                      }}
                    >
                      <span
                        className="badge"
                        style={{
                          backgroundColor: "rgba(59, 130, 246, 0.15)",
                          color: "#60a5fa",
                        }}
                      >
                        {tTrigger(
                          t,
                          script.trigger.toString(),
                          getTriggerLabels(t)[script.trigger.toString()],
                        ) || script.trigger.toString()}
                      </span>
                      {script.targetCategories &&
                        script.targetCategories.length > 0 && (
                          <span
                            className="badge"
                            style={{
                              backgroundColor: "rgba(168, 85, 247, 0.15)",
                              color: "#c084fc",
                            }}
                          >
                            {t("automation.ui.text2")}
                            {script.targetCategories.join(", ")}
                          </span>
                        )}
                      {script.targetTagIds &&
                        script.targetTagIds.length > 0 && (
                          <span
                            className="badge"
                            style={{
                              backgroundColor: "rgba(234, 179, 8, 0.15)",
                              color: "#facc15",
                            }}
                          >
                            🏷️{" "}
                            {script.targetTagIds
                              .map(
                                (id) =>
                                  tags?.find((tg) => tg.id === id)?.label ||
                                  `#${id}`,
                              )
                              .join(", ")}
                          </span>
                        )}
                    </div>
                  </div>

                  {/* Footer metadata & buttons */}
                  <div>
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        fontSize: "0.75rem",
                        color: "var(--text-muted)",
                        borderTop: "1px solid var(--border, #333)",
                        paddingTop: "0.75rem",
                        marginBottom: "0.75rem",
                      }}
                    >
                      <span>
                        {t("automation.ui.lastRun")}{" "}
                        {script.lastExecutedAt
                          ? new Date(script.lastExecutedAt).toLocaleTimeString()
                          : "Never"}
                      </span>
                      {script.lastExecutionStatus && (
                        <span
                          style={{
                            fontWeight: 600,
                            color:
                              script.lastExecutionStatus === "Success"
                                ? "#22c55e"
                                : "#ef4444",
                          }}
                        >
                          {script.lastExecutionStatus === "Success"
                            ? "● Succeeded"
                            : "● Failed"}
                        </span>
                      )}
                    </div>

                    <div
                      style={{
                        display: "flex",
                        gap: "0.4rem",
                        justifyContent: "flex-end",
                      }}
                    >
                      {script.lastExecutionLog && (
                        <button
                          className="btn btn-sm btn-secondary"
                          onClick={() => {
                            setViewingLog({
                              name: script.name,
                              trigger: script.trigger.toString(),
                              time: script.lastExecutedAt
                                ? new Date(
                                    script.lastExecutedAt,
                                  ).toLocaleString()
                                : undefined,
                              log: script.lastExecutionLog || "",
                              status: script.lastExecutionStatus || "Unknown",
                            });
                            setLogModalOpen(true);
                          }}
                          title={t("automation.ui.viewExecutionLog")}
                        >
                          {t("automation.ui.logs")}
                        </button>
                      )}
                      <button
                        className="btn btn-sm btn-secondary"
                        onClick={() => handleRunNow(script.id)}
                        disabled={isRunningId === script.id}
                        title={t("automation.ui.triggerRunImmediately")}
                      >
                        {isRunningId === script.id ? "⏳ Running..." : "▶️ Run"}
                      </button>
                      <button
                        className="btn btn-sm btn-secondary"
                        onClick={() => openEditScript(script)}
                      >
                        {t("automation.ui.edit")}
                      </button>
                      <button
                        className="btn btn-sm btn-danger"
                        onClick={() => handleDeleteScript(script.id)}
                        title={t("automation.ui.deleteScript")}
                      >
                        {t("automation.ui.text3")}
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* TAB 2: PIPELINE RUN HISTORY & VIEWER */}
      {activeTab === "history" && (
        <div>
          <div className="panel" style={{ padding: "1.5rem" }}>
            <h2 style={{ fontSize: "1.2rem", margin: "0 0 1rem 0" }}>
              {t("automation.ui.pipelineExecutionHistory")}
            </h2>
            <p
              style={{
                color: "var(--text-muted)",
                fontSize: "0.9rem",
                marginBottom: "1.5rem",
              }}
            >
              {t("automation.ui.detailedExecutionTracesAndStep")}
            </p>

            <table
              style={{
                width: "100%",
                borderCollapse: "collapse",
                fontSize: "0.9rem",
              }}
            >
              <thead>
                <tr
                  style={{
                    borderBottom: "1px solid var(--border)",
                    textAlign: "left",
                  }}
                >
                  <th style={{ padding: "0.75rem 0.5rem" }}>
                    {t("automation.ui.status")}
                  </th>
                  <th style={{ padding: "0.75rem 0.5rem" }}>
                    {t("automation.ui.pipelineName")}
                  </th>
                  <th style={{ padding: "0.75rem 0.5rem" }}>
                    {t("automation.ui.trigger")}
                  </th>
                  <th style={{ padding: "0.75rem 0.5rem" }}>
                    {t("automation.ui.executedAt")}
                  </th>
                  <th style={{ padding: "0.75rem 0.5rem" }}>
                    {t("automation.ui.actions")}
                  </th>
                </tr>
              </thead>
              <tbody>
                {scriptList.filter((s) => s.lastExecutedAt).length === 0 ? (
                  <tr>
                    <td
                      colSpan={5}
                      style={{
                        textAlign: "center",
                        padding: "2rem",
                        color: "var(--text-muted)",
                      }}
                    >
                      {t("automation.ui.noPipelineExecutionRunsRecorde")}
                    </td>
                  </tr>
                ) : (
                  scriptList
                    .filter((s) => s.lastExecutedAt)
                    .sort(
                      (a, b) =>
                        new Date(b.lastExecutedAt!).getTime() -
                        new Date(a.lastExecutedAt!).getTime(),
                    )
                    .map((s) => (
                      <tr
                        key={s.id}
                        style={{ borderBottom: "1px solid var(--border)" }}
                      >
                        <td style={{ padding: "0.75rem 0.5rem" }}>
                          <span
                            className="badge"
                            style={{
                              backgroundColor:
                                s.lastExecutionStatus === "Success"
                                  ? "rgba(34, 197, 94, 0.15)"
                                  : "rgba(239, 68, 68, 0.15)",
                              color:
                                s.lastExecutionStatus === "Success"
                                  ? "#22c55e"
                                  : "#ef4444",
                            }}
                          >
                            {s.lastExecutionStatus === "Success"
                              ? "✅ Success"
                              : "❌ Failed"}
                          </span>
                        </td>
                        <td
                          style={{ padding: "0.75rem 0.5rem", fontWeight: 600 }}
                        >
                          {s.name}
                        </td>
                        <td style={{ padding: "0.75rem 0.5rem" }}>
                          <span className="badge">
                            {tTrigger(
                              t,
                              s.trigger.toString(),
                              getTriggerLabels(t)[s.trigger.toString()],
                            ) || s.trigger.toString()}
                          </span>
                        </td>
                        <td
                          style={{
                            padding: "0.75rem 0.5rem",
                            color: "var(--text-muted)",
                          }}
