                          borderRadius: "6px",
                          marginBottom: "1rem",
                        }}
                      >
                        <label
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: "0.6rem",
                            fontSize: "0.85rem",
                            fontWeight: 600,
                            cursor: "pointer",
                            color: "var(--text-primary)",
                          }}
                        >
                          <input
                            type="checkbox"
                            checked={step.conditionEnabled}
                            onChange={(e) => {
                              const copy = [...visualSteps];
                              copy[stepIdx].conditionEnabled = e.target.checked;
                              updateVisualSteps(copy);
                            }}
                          />
                          {t("automation.ui.onlyRunThisStepIf")}
                        </label>

                        {step.conditionEnabled &&
                          (() => {
                            const propDef = getConditionProperties(t).find(
                              (p) => p.value === step.conditionLeft,
                            ) || {
                              value: "custom",
                              label: "Custom",
                              group: "Custom / Dynamic",
                              type: "custom" as const,
                              defaultOp: "==" as const,
                              defaultValue: "",
                            };

                            const isCustomLeft = !getConditionProperties(
                              t,
                            ).some(
                              (p) =>
                                p.value === step.conditionLeft &&
                                p.value !== "custom",
                            );

                            // Operator definitions per type
                            const opOptions = (() => {
                              switch (propDef.type) {
                                case "boolean":
                                  return [
                                    { value: "==", label: "is / equals (==)" },
                                    { value: "!=", label: "is not (!=)" },
                                  ];
                                case "enum":
                                case "category":
                                case "string":
                                  return [
                                    { value: "==", label: "equals (==)" },
                                    { value: "!=", label: "not equals (!=)" },
                                  ];
                                case "number":
                                  return [
                                    { value: ">=", label: ">= (at least)" },
                                    { value: ">", label: "> (greater than)" },
                                    { value: "<=", label: "<= (at most)" },
                                    { value: "<", label: "< (less than)" },
                                    { value: "==", label: "== (exact)" },
                                    { value: "!=", label: "!= (not equal)" },
                                  ];
                                case "custom":
                                default:
                                  return [
                                    { value: "==", label: "==" },
                                    { value: "!=", label: "!=" },
                                    { value: ">=", label: ">=" },
                                    { value: "<=", label: "<=" },
                                    { value: ">", label: ">" },
                                    { value: "<", label: "<" },
                                  ];
                              }
                            })();

                            // Auto-correct operator if invalid for current type
                            if (
                              !opOptions.some(
                                (op) => op.value === step.conditionOp,
                              )
                            ) {
                              step.conditionOp = propDef.defaultOp;
                            }

                            // Determine available preset options for Right Value
                            let presetOptions:
                              { value: string; label: string }[] | null = null;
                            if (propDef.type === "boolean" && propDef.options) {
                              presetOptions = propDef.options;
                            } else if (
                              propDef.type === "enum" &&
                              propDef.options
                            ) {
                              presetOptions = propDef.options;
                            } else if (propDef.type === "category") {
                              presetOptions = (categories || []).map((c) => ({
                                value: `'${c.name}'`,
                                label: `📁 ${c.name}`,
                              }));
                            }

                            // Boolean value normalization & custom toggle check
                            const isCustomRight = (() => {
                              if (propDef.type === "boolean") {
                                const trimmed = step.conditionRight
                                  .trim()
                                  .toLowerCase();
                                if (trimmed === "true" || trimmed === "false")
                                  return false;
                                if (
                                  trimmed.startsWith("${") ||
                                  trimmed.includes("inputs.") ||
                                  trimmed.includes("secrets.")
                                )
                                  return true;
                                // Invalid/legacy value: normalize immediately
                                step.conditionRight = "true";
                                return false;
                              }
                              if (presetOptions) {
                                const isPresetMatch = presetOptions.some(
                                  (o) =>
                                    o.value.toLowerCase() ===
                                    step.conditionRight.trim().toLowerCase(),
                                );
                                return (
                                  !isPresetMatch &&
                                  step.conditionRight.trim() !== ""
                                );
                              }
                              return true;
                            })();

                            // Formatted live hint for numeric values
                            const numericLiveHint = (() => {
                              if (
                                propDef.type !== "number" ||
                                !step.conditionRight
                              )
                                return null;
                              const num = Number(step.conditionRight);
                              if (isNaN(num)) return null;
                              if (propDef.unit === "bytes") {
                                return formatBytes(num);
                              }
                              if (propDef.unit === "speed") {
                                return `${formatBytes(num)}/s`;
                              }
                              if (propDef.unit === "ratio") {
                                return `${num.toFixed(2)}x ratio`;
                              }
                              if (propDef.unit === "percent") {
                                return `${num}%`;
                              }
                              if (propDef.unit === "count") {
                                return `${num} peers`;
                              }
                              return null;
                            })();

                            return (
                              <div
                                style={{
                                  marginTop: "0.75rem",
                                  display: "flex",
                                  flexDirection: "column",
                                  gap: "0.5rem",
                                }}
                              >
                                <div
                                  style={{
                                    display: "flex",
                                    gap: "0.5rem",
                                    alignItems: "center",
                                    width: "100%",
                                  }}
                                >
                                  {/* Left Property Select (L-Value) */}
                                  <div
                                    style={{
                                      width: isCustomLeft ? "260px" : "220px",
                                      flexShrink: 0,
                                      display: "flex",
                                      flexDirection: "column",
                                      gap: "0.2rem",
                                    }}
                                  >
                                    <select
                                      className="form-control"
                                      style={{ width: "100%", fontWeight: 500 }}
                                      value={
                                        isCustomLeft
                                          ? "custom"
                                          : step.conditionLeft
                                      }
                                      onChange={(e) => {
                                        const copy = [...visualSteps];
                                        const newVal = e.target.value;
                                        if (newVal === "custom") {
                                          copy[stepIdx].conditionLeft =
                                            "${inputs.customProp}";
                                          copy[stepIdx].conditionOp = "==";
                                          copy[stepIdx].conditionRight = "";
                                        } else {
                                          copy[stepIdx].conditionLeft = newVal;
                                          const found = getConditionProperties(
                                            t,
                                          ).find((p) => p.value === newVal);
                                          if (found) {
                                            copy[stepIdx].conditionOp =
                                              found.defaultOp;
                                            copy[stepIdx].conditionRight =
                                              found.defaultValue;
                                          }
                                        }
                                        updateVisualSteps(copy);
                                      }}
                                    >
                                      {Array.from(
                                        new Set(
                                          getConditionProperties(t).map(
                                            (p) => p.group,
                                          ),
                                        ),
                                      ).map((groupName) => (
                                        <optgroup
                                          key={groupName}
                                          label={groupName}
                                        >
                                          {getConditionProperties(t)
                                            .filter(
                                              (p) => p.group === groupName,
                                            )
                                            .map((p) => (
                                              <option
                                                key={p.value}
                                                value={p.value}
                                              >
                                                {p.label}
                                              </option>
                                            ))}
                                        </optgroup>
                                      ))}
                                    </select>
                                    {isCustomLeft && (
                                      <input
                                        type="text"
                                        className="form-control"
                                        style={{
                                          width: "100%",
                                          fontSize: "0.8rem",
                                          padding: "0.25rem 0.5rem",
                                        }}
                                        value={step.conditionLeft}
                                        onChange={(e) => {
                                          const copy = [...visualSteps];
                                          copy[stepIdx].conditionLeft =
                                            e.target.value;
                                          updateVisualSteps(copy);
                                        }}
                                        placeholder={t(
                                          "automation.ui.egInputsmyproperty",
                                        )}
                                      />
                                    )}
                                  </div>

                                  {/* Operator Select (Comparison) */}
                                  <div
                                    style={{ width: "150px", flexShrink: 0 }}
                                  >
                                    <select
                                      className="form-control"
                                      style={{
                                        width: "100%",
                                        textAlign: "center",
                                        fontWeight: 700,
                                      }}
                                      value={step.conditionOp}
                                      onChange={(e) => {
                                        const copy = [...visualSteps];
                                        copy[stepIdx].conditionOp = e.target
                                          .value as any;
                                        updateVisualSteps(copy);
                                      }}
                                    >
                                      {opOptions.map((op) => (
                                        <option key={op.value} value={op.value}>
                                          {op.label}
                                        </option>
                                      ))}
                                    </select>
                                  </div>

                                  {/* Right Value (R-Value): Type-Aware Presets, Numeric Chips or Custom Input */}
                                  <div
                                    style={{
                                      flex: 1,
                                      minWidth: 0,
                                      display: "flex",
                                      gap: "0.35rem",
                                      alignItems: "center",
                                    }}
                                  >
                                    {presetOptions && !isCustomRight ? (
                                      <div
                                        style={{
                                          display: "flex",
                                          gap: "0.35rem",
                                          width: "100%",
                                          alignItems: "center",
                                        }}
                                      >
                                        <select
                                          className="form-control"
                                          style={{
                                            width: "100%",
                                            fontWeight: 500,
                                          }}
                                          value={step.conditionRight.trim()}
                                          onChange={(e) => {
                                            const copy = [...visualSteps];
                                            if (
                                              e.target.value === "__custom__"
                                            ) {
                                              copy[stepIdx].conditionRight =
                                                propDef.type === "boolean"
                                                  ? "${inputs.isPrivate}"
                                                  : "";
                                            } else {
                                              copy[stepIdx].conditionRight =
                                                e.target.value;
                                            }
                                            updateVisualSteps(copy);
                                          }}
                                        >
                                          {presetOptions.map((opt) => (
                                            <option
                                              key={opt.value}
                                              value={opt.value}
                                            >
                                              {opt.label}
                                            </option>
                                          ))}
                                          <option value="__custom__">
                                            {t(
                                              "automation.ui.customExpressionVariable",
                                            )}
                                          </option>
                                        </select>
                                      </div>
                                    ) : propDef.type === "number" ? (
                                      <div
                                        style={{
                                          display: "flex",
                                          flexDirection: "column",
                                          gap: "0.3rem",
                                          width: "100%",
                                        }}
                                      >
                                        <div
                                          style={{
                                            display: "flex",
                                            gap: "0.35rem",
                                            alignItems: "center",
                                            width: "100%",
                                          }}
                                        >
                                          <input
                                            type="text"
                                            className="form-control"
                                            style={{ flex: 1, minWidth: 0 }}
                                            value={step.conditionRight}
                                            onChange={(e) => {
                                              const copy = [...visualSteps];
                                              copy[stepIdx].conditionRight =
                                                e.target.value;
                                              updateVisualSteps(copy);
                                            }}
                                            placeholder={
                                              propDef.placeholder ||
                                              "e.g. 1000000000"
                                            }
                                          />
                                          {numericLiveHint && (
                                            <span
                                              className="badge"
                                              style={{
                                                padding: "0.35rem 0.6rem",
                                                fontSize: "0.8rem",
                                                whiteSpace: "nowrap",
                                                backgroundColor:
                                                  "rgba(59, 130, 246, 0.15)",
                                                color: "var(--accent, #38bdf8)",
                                                border:
                                                  "1px solid rgba(59, 130, 246, 0.3)",
                                                borderRadius: "4px",
                                                flexShrink: 0,
                                              }}
                                            >
                                              {numericLiveHint}
                                            </span>
                                          )}
                                        </div>
                                        {propDef.presets &&
                                          propDef.presets.length > 0 && (
                                            <div
                                              style={{
                                                display: "flex",
                                                gap: "0.3rem",
                                                flexWrap: "wrap",
                                                alignItems: "center",
                                              }}
                                            >
                                              <span
                                                style={{
                                                  fontSize: "0.7rem",
                                                  color: "var(--text-muted)",
                                                  marginRight: "0.15rem",
                                                }}
                                              >
                                                {t("automation.ui.quickSet")}
                                              </span>
                                              {propDef.presets.map((preset) => (
                                                <button
                                                  key={preset.value}
                                                  type="button"
                                                  className="btn btn-secondary"
                                                  style={{
                                                    fontSize: "0.7rem",
                                                    padding: "0.15rem 0.45rem",
                                                    backgroundColor:
                                                      step.conditionRight ===
                                                      preset.value
                                                        ? "var(--accent, #38bdf8)"
                                                        : undefined,
                                                    color:
                                                      step.conditionRight ===
                                                      preset.value
                                                        ? "#000"
                                                        : undefined,
                                                    fontWeight:
                                                      step.conditionRight ===
                                                      preset.value
                                                        ? 700
                                                        : 400,
                                                  }}
                                                  onClick={() => {
                                                    const copy = [
                                                      ...visualSteps,
                                                    ];
                                                    copy[
                                                      stepIdx
                                                    ].conditionRight =
                                                      preset.value;
                                                    updateVisualSteps(copy);
                                                  }}
                                                >
                                                  {preset.label}
                                                </button>
                                              ))}
                                            </div>
                                          )}
                                      </div>
                                    ) : (
                                      <div
                                        style={{
                                          display: "flex",
                                          gap: "0.35rem",
                                          width: "100%",
                                          alignItems: "center",
                                        }}
                                      >
                                        <input
                                          type="text"
                                          className="form-control"
                                          style={{ flex: 1, minWidth: 0 }}
                                          value={step.conditionRight}
                                          onChange={(e) => {
                                            const copy = [...visualSteps];
                                            copy[stepIdx].conditionRight =
                                              e.target.value;
                                            updateVisualSteps(copy);
                                          }}
                                          placeholder={
                                            propDef.placeholder ||
                                            "e.g. 'Custom Value' or ${inputs.val}"
                                          }
                                        />
                                        {presetOptions && (
                                          <button
                                            type="button"
                                            className="btn btn-sm btn-secondary"
                                            title={t(
                                              "automation.ui.switchBackToPresetsDropdown",
                                            )}
                                            style={{
                                              padding: "0.35rem 0.6rem",
                                              fontSize: "0.75rem",
                                              whiteSpace: "nowrap",
                                              flexShrink: 0,
                                            }}
                                            onClick={() => {
                                              const copy = [...visualSteps];
                                              copy[stepIdx].conditionRight =
                                                presetOptions![0].value;
                                              updateVisualSteps(copy);
                                            }}
                                          >
                                            {t("automation.ui.presets")}
                                          </button>
                                        )}
                                      </div>
                                    )}
                                  </div>
                                </div>

                                {/* Helper text based on type */}
                                <div
                                  style={{
                                    fontSize: "0.75rem",
                                    color: "var(--text-muted)",
                                    paddingLeft: "2px",
                                  }}
                                >
                                  {propDef.type === "boolean" &&
                                    "💡 Boolean flag: Evaluates True (On/Yes) or False (Off/No)."}
                                  {propDef.type === "enum" &&
                                    "💡 State evaluation: Matches against the torrent's lifecycle state or enter a custom status."}
                                  {propDef.type === "category" &&
                                    "💡 Category evaluation: Select an existing category or enter a custom pattern."}
                                  {propDef.type === "number" &&
                                    "💡 Numeric comparison: Value is evaluated in bytes, ratios, counts, or percentages."}
                                  {propDef.type === "string" &&
                                    "💡 String matching: Supports exact matches or pattern values in quotes."}
                                  {propDef.type === "custom" &&
                                    "💡 Custom expression: Uses lazy matching with variables, inputs, or system properties."}
                                </div>
                              </div>
                            );
                          })()}
                      </div>

                      {/* Step Fault Tolerance & Retries */}
                      <div
                        style={{
                          display: "flex",
                          gap: "1.5rem",
                          alignItems: "center",
                          backgroundColor: "var(--bg-secondary, #2a2620)",
                          border: "1px solid var(--border-light, #3a352e)",
                          padding: "0.6rem 1rem",
                          borderRadius: "6px",
                          marginBottom: "1rem",
                          fontSize: "0.85rem",
                          flexWrap: "wrap",
                        }}
                      >
                        <label
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: "0.5rem",
                            cursor: "pointer",
                            color: "var(--text-primary)",
                          }}
                        >
                          <input
                            type="checkbox"
                            checked={step.continueOnError || false}
                            onChange={(e) => {
                              const copy = [...visualSteps];
                              copy[stepIdx].continueOnError = e.target.checked;
                              updateVisualSteps(copy);
                            }}
                          />
                          Continue on Error
                        </label>
                        <div
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: "0.5rem",
                          }}
                        >
                          <label
                            style={{
                              color: "var(--text-muted, #9c9484)",
                              fontSize: "0.8rem",
                            }}
                          >
                            Retries:
                          </label>
                          <input
                            type="number"
                            min={0}
                            max={10}
                            value={step.retries || 0}
                            onChange={(e) => {
                              const copy = [...visualSteps];
                              copy[stepIdx].retries = Math.max(
                                0,
                                parseInt(e.target.value, 10) || 0,
                              );
                              updateVisualSteps(copy);
                            }}
                            className="form-control form-control-sm"
                            style={{ width: "70px", padding: "0.2rem 0.4rem" }}
                          />
                        </div>
                        <span
                          style={{
                            fontSize: "0.75rem",
                            color: "var(--text-muted, #9c9484)",
                          }}
                        >
                          {step.continueOnError
                            ? "Step failure will record a warning and continue subsequent steps."
                            : "Step failure will abort workflow execution."}
                        </span>
                      </div>

                      {/* Actions List */}
                      <div>
                        <div
                          style={{
                            display: "flex",
                            justifyContent: "space-between",
                            alignItems: "center",
                            marginBottom: "0.65rem",
                            flexWrap: "wrap",
                            gap: "0.5rem",
                          }}
                        >
                          <span
                            style={{
                              fontSize: "0.85rem",
                              fontWeight: 600,
                              color: "var(--text-secondary)",
                            }}
                          >
                            {t("automation.ui.stepActions")}
                          </span>
                          <div
                            style={{
                              display: "flex",
                              gap: "0.35rem",
                              flexWrap: "wrap",
                            }}
                          >
                            <button
                              type="button"
                              className="btn btn-sm btn-secondary"
                              style={{
                                fontSize: "0.75rem",
                                padding: "0.2rem 0.5rem",
                              }}
                              onClick={() => {
                                const copy = [...visualSteps];
                                copy[stepIdx].actions.push({
                                  id: `act-${Date.now()}`,
                                  type: "addTag",
                                  value: "New-Tag",
                                });
                                updateVisualSteps(copy);
                              }}
                            >
                              {t("automation.ui.tag")}
                            </button>
                            <button
                              type="button"
                              className="btn btn-sm btn-secondary"
                              style={{
                                fontSize: "0.75rem",
                                padding: "0.2rem 0.5rem",
                              }}
                              onClick={() => {
                                const copy = [...visualSteps];
                                copy[stepIdx].actions.push({
                                  id: `act-${Date.now()}`,
                                  type: "setCategory",
                                  value: categories?.[0]?.name || "Movies",
                                });
                                updateVisualSteps(copy);
                              }}
                            >
                              {t("automation.ui.category")}
                            </button>
                            <button
                              type="button"
                              className="btn btn-sm btn-secondary"
                              style={{
                                fontSize: "0.75rem",
                                padding: "0.2rem 0.5rem",
                              }}
                              onClick={() => {
                                const copy = [...visualSteps];
                                copy[stepIdx].actions.push({
                                  id: `act-${Date.now()}`,
                                  type: "setUploadLimit",
                                  value: "1024",
                                });
                                updateVisualSteps(copy);
                              }}
                            >
                              {t("automation.ui.limit")}
                            </button>
                            <button
                              type="button"
                              className="btn btn-sm btn-secondary"
                              style={{
                                fontSize: "0.75rem",
                                padding: "0.2rem 0.5rem",
                              }}
                              onClick={() => {
                                const copy = [...visualSteps];
                                copy[stepIdx].actions.push({
                                  id: `act-${Date.now()}`,
                                  type: "sendNotification",
                                  value: "Torrent event triggered notification",
                                });
                                updateVisualSteps(copy);
                              }}
                            >
                              {t("automation.ui.alert")}
                            </button>
                            <button
                              type="button"
                              className="btn btn-sm btn-secondary"
                              style={{
                                fontSize: "0.75rem",
                                padding: "0.2rem 0.5rem",
                              }}
                              onClick={() => {
                                const copy = [...visualSteps];
                                copy[stepIdx].actions.push({
                                  id: `act-${Date.now()}`,
                                  type: "notifyArr",
                                  value: "",
                                });
                                updateVisualSteps(copy);
                              }}
                            >
                              {t("automation.ui.servarr")}
                            </button>
                            <button
                              type="button"
                              className="btn btn-sm btn-secondary"
                              style={{
                                fontSize: "0.75rem",
                                padding: "0.2rem 0.5rem",
                              }}
                              onClick={() => {
                                const copy = [...visualSteps];
                                copy[stepIdx].actions.push({
                                  id: `act-${Date.now()}`,
                                  type: "command",
                                  value: "Backup",
                                });
                                updateVisualSteps(copy);
                              }}
                            >
                              {t("automation.ui.command")}
                            </button>
                          </div>
                        </div>

                        {step.actions.length === 0 ? (
                          <div
                            style={{
                              fontSize: "0.825rem",
                              color: "var(--text-muted)",
                              fontStyle: "italic",
                              padding: "0.6rem 0",
                            }}
                          >
                            {t("automation.ui.noActionsAddedClickAny")}
                          </div>
                        ) : (
                          step.actions.map((act, actIdx) => {
                            const actDef = getActionGroups(t)
                              .flatMap((g) => g.items)
                              .find((i) => i.type === act.type);
                            const placeholder =
                              actDef?.placeholder || "Action value";

                            return (
                              <div
                                key={act.id}
                                style={{
                                  display: "flex",
                                  alignItems: "center",
                                  gap: "0.5rem",
                                  marginBottom: "0.5rem",
                                  backgroundColor:
                                    "var(--bg-secondary, #2a2620)",
                                  border:
                                    "1px solid var(--border-light, #3a352e)",
                                  padding: "0.5rem 0.75rem",
                                  borderRadius: "6px",
                                  flexWrap: "wrap",
                                }}
                              >
                                <select
                                  className="form-control"
                                  style={{
                                    width: "220px",
                                    flexShrink: 0,
                                    fontWeight: 500,
                                  }}
                                  value={act.type}
                                  onChange={(e) => {
                                    const copy = [...visualSteps];
                                    const newType = e.target
                                      .value as VisualActionType;
                                    copy[stepIdx].actions[actIdx].type =
                                      newType;
                                    if (
                                      newType === "setCategory" &&
                                      categories?.[0]
                                    ) {
                                      copy[stepIdx].actions[actIdx].value =
                                        categories[0].name;
                                    } else if (newType === "command") {
                                      copy[stepIdx].actions[actIdx].value =
                                        getCommonCommands(t)[0].name;
                                    } else if (newType === "setPriority") {
                                      copy[stepIdx].actions[actIdx].value =
                                        "High";
                                    } else if (
                                      newType === "setSequentialDownload" ||
                                      newType === "setSuperSeeding"
                                    ) {
                                      copy[stepIdx].actions[actIdx].value =
