const STATUS_COLORS: Record<string, string> = {
  Seeding: "var(--color-success, #27ae60)",
  Stopped: "var(--color-danger, #e74c3c)",
  Queued: "var(--color-warning, #f39c12)",
  Error: "#c0392b",
};

function StatusDonut({
  counts,
  total,
}: {
  counts: Record<string, number>;
  total: number;
}) {
  if (total === 0) return null;
  const entries = Object.entries(counts).filter(([, v]) => v > 0);
  let offset = 0;
  const radius = 40;
  const circumference = 2 * Math.PI * radius;

  return (
    <div
      className="card"
      style={{
        display: "flex",
        alignItems: "center",
        gap: 24,
        borderRadius: "8px",
        boxShadow:
          "0 4px 14px rgba(0, 0, 0, 0.32), 0 1px 3px rgba(0, 0, 0, 0.18)",
      }}
    >
      <svg width={100} height={100} viewBox="0 0 100 100">
        {entries.map(([status, count]) => {
          const pct = count / total;
          const dashLength = pct * circumference;
          const dashOffset = -offset * circumference;
          offset += pct;
          return (
            <circle
              key={status}
              cx={50}
              cy={50}
              r={radius}
              fill="none"
              stroke={STATUS_COLORS[status] || "#666"}
              strokeWidth={16}
              strokeDasharray={`${dashLength} ${circumference - dashLength}`}
              strokeDashoffset={dashOffset}
              transform="rotate(-90 50 50)"
            />
          );
        })}
        <text
          x={50}
          y={54}
          textAnchor="middle"
          fontSize={16}
          fontWeight={700}
          fill="var(--color-text, #ccc)"
        >
          {total}
        </text>
      </svg>
      <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        {entries.map(([status, count]) => (
          <div
            key={status}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              fontSize: 13,
            }}
          >
            <div
              style={{
                width: 10,
                height: 10,
                borderRadius: "50%",
                backgroundColor: STATUS_COLORS[status] || "#666",
              }}
            />
            <span>
              {status}: {count}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

function Dashboard() {
  const { data: torrents, isLoading, isError } = useTorrents();
  const {
    data: stats,
    isLoading: statsLoading,
    isError: statsError,
  } = useSeedingStats();
  const { data: activeLimits } = useActiveSpeedLimits();
  const { data: arrConnections } = useArrConnections();
  const { data: indexers } = useIndexers();
  const { data: downloadClients } = useDownloadClients();
  const { data: history } = useDownloadHistory();
  const { data: diskSpace, isLoading: diskLoading } = useDiskSpace();
  const { data: categories } = useCategories();

  const achievements = useMemo(
    () => calculateAchievements(torrents, stats),
    [torrents, stats],
  );

  const hnrPendingCount = useMemo(() => {
    return (torrents ?? []).filter(
      (t) => Boolean(t.isPrivate) && !calculateHnrStatus(t).isCleared,
    ).length;
  }, [torrents]);

  const totalSize = (torrents ?? []).reduce((sum, t) => sum + t.totalSize, 0);

  // Storage utilization & category breakdown
  const storageUtilization = useMemo(() => {
    const totalCapacity = (diskSpace ?? []).reduce(
      (sum, d) => sum + d.totalSpace,
      0,
    );
    const totalFree = (diskSpace ?? []).reduce(
      (sum, d) => sum + d.freeSpace,
      0,
    );
    const totalUsed = totalCapacity > 0 ? totalCapacity - totalFree : 0;
    const usedPercentage =
      totalCapacity > 0 ? (totalUsed / totalCapacity) * 100 : 0;

    const catMap: Record<
      string,
      { category: string; count: number; totalBytes: number }
    > = {};

    for (const t of torrents ?? []) {
      const cat = t.category?.trim() || "Uncategorized";
      if (!catMap[cat]) {
        catMap[cat] = { category: cat, count: 0, totalBytes: 0 };
      }
      catMap[cat].count += 1;
      catMap[cat].totalBytes += t.totalSize;
    }

    const categoryBreakdown = Object.values(catMap).sort(
      (a, b) => b.totalBytes - a.totalBytes,
    );

    return {
      totalCapacity,
      totalFree,
      totalUsed,
      usedPercentage,
      categoryBreakdown,
    };
  }, [diskSpace, torrents]);
  const recent = [...(torrents ?? [])]
    .sort(
      (a, b) =>
        new Date(b.dateAdded).getTime() - new Date(a.dateAdded).getTime(),
    )
    .slice(0, 6);

  const statusCounts: Record<string, number> = {};
  (torrents ?? []).forEach((t) => {
    const s = t.status || "Unknown";
    statusCounts[s] = (statusCounts[s] || 0) + 1;
  });

  const topTrackers = useMemo(() => {
    const trackerCounts: Record<string, number> = {};
    (torrents ?? []).forEach((t) => {
      let domain = "No tracker";
