                    gap: "0.4rem",
                    cursor: "pointer",
                    fontSize: "0.9rem",
                  }}
                >
                  <input
                    type="radio"
                    name="exportFormat"
                    value="json"
                    checked={exportFormat === "json"}
                    onChange={() => setExportFormat("json")}
                  />
                  <span>JSON (.json)</span>
                </label>
                <label
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: "0.4rem",
                    cursor: "pointer",
                    fontSize: "0.9rem",
                  }}
                >
                  <input
                    type="radio"
                    name="exportFormat"
                    value="csv"
                    checked={exportFormat === "csv"}
                    onChange={() => setExportFormat("csv")}
                  />
                  <span>CSV (.csv)</span>
                </label>
              </div>
            </div>

            <div
              className="modal-actions"
              style={{
                display: "flex",
                justifyContent: "flex-end",
                gap: "0.5rem",
              }}
            >
              <button
                className="btn btn-outline btn-small"
                onClick={() => setShowExportModal(false)}
                disabled={isExporting}
              >
                Cancel
              </button>
              <button
                className="btn btn-primary btn-small"
                disabled={isExporting}
                onClick={async () => {
                  setIsExporting(true);
                  try {
                    const searchParams = new URLSearchParams();
                    if (searchTerm.trim())
                      searchParams.set("query", searchTerm.trim());
                    if (statusFilter !== "all")
                      searchParams.set("status", statusFilter);
                    const qStr = searchParams.toString();
                    const exportUrl = `/downloadhistory/export${qStr ? `?${qStr}` : ""}`;
                    const fullData =
                      await apiClient.get<DownloadHistoryEntry[]>(exportUrl);

                    if (!fullData || fullData.length === 0) {
                      showToast(
                        "No download history records to export",
                        "info",
                      );
                      return;
                    }

                    const dateStr = new Date().toISOString().slice(0, 10);
                    if (exportFormat === "json") {
                      const blob = new Blob(
                        [JSON.stringify(fullData, null, 2)],
                        {
                          type: "application/json",
                        },
                      );
                      const url = URL.createObjectURL(blob);
                      const a = document.createElement("a");
                      a.href = url;
                      a.download = `seedarr-history-${dateStr}.json`;
                      a.click();
                      URL.revokeObjectURL(url);
                    } else {
                      const headers = [
                        "ID",
                        "Title",
                        "InfoHash",
                        "Source",
                        "Status",
                        "TotalSize",
                        "Uploaded",
                        "Ratio",
                        "SeedingTimeSeconds",
                        "DateAdded",
                        "DateCompleted",
                      ];
                      const rows = fullData.map((h) => [
                        h.id,
                        sanitizeCsvField(h.title),
                        sanitizeCsvField(h.infoHash),
                        sanitizeCsvField(h.source),
                        sanitizeCsvField(h.status),
                        h.totalSize,
                        h.uploaded,
                        h.ratio,
                        h.seedingTime,
                        sanitizeCsvField(h.dateAdded),
                        sanitizeCsvField(h.dateCompleted),
                      ]);
                      const csvContent = [
                        headers.join(","),
                        ...rows.map((r) => r.join(",")),
                      ].join("\r\n");
                      const blob = new Blob([csvContent], {
                        type: "text/csv;charset=utf-8;",
                      });
                      const url = URL.createObjectURL(blob);
                      const a = document.createElement("a");
                      a.href = url;
                      a.download = `seedarr-history-${dateStr}.csv`;
                      a.click();
                      URL.revokeObjectURL(url);
                    }
                    setShowExportModal(false);
                    showToast(
                      "Download history exported successfully",
                      "success",
                    );
                  } catch (err: any) {
                    showToast(
                      `Failed to export history: ${err.message || "Unknown error"}`,
                      "error",
                    );
                  } finally {
                    setIsExporting(false);
                  }
                }}
              >
                {isExporting
                  ? "Exporting..."
                  : `Download ${exportFormat.toUpperCase()}`}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

