interface EventDetailsModalProps {
  event: EventEntry;
  onClose: () => void;
}

function EventDetailsModal({ event, onClose }: EventDetailsModalProps) {
  const [stackTraceExpanded, setStackTraceExpanded] = useState(true);
  const [copied, setCopied] = useState(false);

  const trapRef = useFocusTrap<HTMLDivElement>({
    isOpen: true,
    onEscape: onClose,
  });
  useModalRegistration({
    id: "event-details-modal",
    isOpen: true,
    onClose,
    modalRef: trapRef,
  });

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  const handleCopy = useCallback(async () => {
    const textToCopy = [
      `Timestamp: ${event.timestamp} (${formatEventTime(event.timestamp)})`,
      `Level: ${event.level}`,
      `Component: ${event.component}`,
      `Message: ${event.message}`,
      event.exception ? `Exception:\n${event.exception}` : null,
    ]
      .filter(Boolean)
      .join("\n");

    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(textToCopy);
      } else {
        const textarea = document.createElement("textarea");
        textarea.value = textToCopy;
        textarea.style.position = "fixed";
        textarea.style.opacity = "0";
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand("copy");
        document.body.removeChild(textarea);
      }
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Failed to copy event to clipboard", err);
    }
  }, [event]);

  return (
    <div
      className="modal-overlay"
      onClick={handleBackdropClick}
      role="dialog"
      aria-modal="true"
      aria-labelledby="event-details-title"
    >
      <div
        ref={trapRef}
        className="modal"
        style={{
          maxWidth: "760px",
          width: "92%",
          maxHeight: "85vh",
          display: "flex",
          flexDirection: "column",
          padding: "1.5rem",
