function SystemEvents() {
  const { data: entries, isLoading, isError } = useEventEntries();
  const queryClient = useQueryClient();
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("desc");
  const [levelFilter, setLevelFilter] = useState<LevelFilter>("All");
  const [searchText, setSearchText] = useState("");
  const [pageSize, setPageSize] = useState<number>(50);
  const [currentPage, setCurrentPage] = useState<number>(1);
  const [clearedAt, setClearedAt] = useState<number | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<EventEntry | null>(null);
  const tableBodyRef = useRef<HTMLDivElement>(null);

  const filteredEntries = useMemo(() => {
    if (!entries) return [];

    let result = entries;

    if (clearedAt !== null) {
      result = result.filter(
        (entry) => new Date(entry.timestamp).getTime() > clearedAt,
      );
    }

    if (levelFilter !== "All") {
      result = result.filter(
        (entry) => entry.level.toLowerCase() === levelFilter.toLowerCase(),
      );
    }

    if (searchText.trim()) {
      const q = searchText.trim().toLowerCase();
      result = result.filter(
        (entry) =>
          entry.component.toLowerCase().includes(q) ||
          entry.message.toLowerCase().includes(q) ||
          (entry.exception && entry.exception.toLowerCase().includes(q)),
      );
    }

    const sorted = [...result];
    sorted.sort((a, b) => {
      const ta = new Date(a.timestamp).getTime();
      const tb = new Date(b.timestamp).getTime();
      return sortDirection === "desc" ? tb - ta : ta - tb;
    });

    return sorted;
  }, [entries, sortDirection, clearedAt, levelFilter, searchText]);

  const totalPages = Math.max(1, Math.ceil(filteredEntries.length / pageSize));
  const activePage = Math.min(Math.max(1, currentPage), totalPages);

  const startIndex = (activePage - 1) * pageSize;
  const endIndex = Math.min(startIndex + pageSize, filteredEntries.length);
  const currentEntries = useMemo(() => {
    return filteredEntries.slice(startIndex, endIndex);
  }, [filteredEntries, startIndex, endIndex]);

  const pageNumbers = useMemo(() => {
    return getPageNumbers(activePage, totalPages);
  }, [activePage, totalPages]);

  const handleRefresh = useCallback(() => {
    setClearedAt(null);
    queryClient.invalidateQueries({ queryKey: ["system", "events"] });
  }, [queryClient]);

  const handleClear = useCallback(() => {
    setClearedAt(Date.now());
    setCurrentPage(1);
  }, []);

  const toggleSort = useCallback(() => {
    setSortDirection((prev) => (prev === "desc" ? "asc" : "desc"));
  }, []);

  return (
    <div className="content-area" style={{ padding: "1.5rem" }}>
      {/* Header Banner */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "1.5rem",
          flexWrap: "wrap",
          gap: "1rem",
        }}
      >
        <div>
          <h1
            style={{
              fontSize: "1.75rem",
              fontWeight: 700,
              margin: 0,
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
            }}
          >
            <span>📜</span> System: Events
          </h1>
          <p
            style={{
              color: "var(--text-muted, #888)",
              margin: "0.25rem 0 0 0",
              fontSize: "0.9rem",
            }}
          >
            Real-time audit log events, application exceptions, and background
            routine updates
          </p>
        </div>

        <div style={{ display: "flex", gap: "0.75rem", alignItems: "center" }}>
          <button
            className="btn btn-outline btn-small"
            onClick={handleRefresh}
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: "0.4rem",
            }}
          >
            <RefreshIcon />
            <span>Refresh</span>
          </button>
          <button
            className="btn btn-outline btn-small"
            onClick={handleClear}
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: "0.4rem",
            }}
          >
            <ClearIcon />
            <span>Clear</span>
          </button>
        </div>
      </div>

      {/* Events Table Card */}
      <div
        className="card"
        style={{
          borderRadius: "8px",
          border: "1px solid var(--border-light)",
          boxShadow:
            "0 4px 14px rgba(0, 0, 0, 0.32), 0 1px 3px rgba(0, 0, 0, 0.18)",
          padding: 0,
          overflow: "hidden",
        }}
      >
        {/* Filter and Search Toolbar */}
        <div className="log-toolbar">
          <div className="log-toolbar-filters">
            {LEVEL_FILTER_OPTIONS.map((level) => (
              <button
                key={level}
                type="button"
                title={
                  level === "All" ? "Show all events" : `Show ${level} events`
                }
                className={`btn btn-small ${levelFilter === level ? "log-filter-active" : ""} ${level !== "All" ? `log-filter-${level.toLowerCase()}` : ""}`}
                onClick={() => {
                  setLevelFilter(level);
                  setCurrentPage(1);
                }}
              >
                {level}
              </button>
            ))}
          </div>

          <div className="log-toolbar-actions">
            <input
              type="text"
              className="search-input"
              placeholder="Filter component or message..."
              value={searchText}
              onChange={(e) => {
                setSearchText(e.target.value);
                setCurrentPage(1);
              }}
              style={{ width: "220px" }}
            />
            {searchText && (
              <button
                type="button"
                className="btn btn-small btn-outline"
                onClick={() => {
                  setSearchText("");
                  setCurrentPage(1);
                }}
                title="Clear search"
              >
                ✕
              </button>
            )}
          </div>
        </div>

        {/* Table View */}
        <div className="torrent-table-wrapper" ref={tableBodyRef}>
          <table className="torrent-table">
            <thead>
              <tr>
                <th className="torrent-table-th" style={{ width: "90px" }}>
                  Level
                </th>
                <th
                  className="torrent-table-th"
                  onClick={toggleSort}
                  style={{
                    width: "190px",
                    cursor: "pointer",
                    userSelect: "none",
                  }}
                  title="Click to sort by timestamp"
                >
                  <span
                    style={{ display: "inline-flex", alignItems: "center" }}
                  >
                    Time <SortArrow direction={sortDirection} />
                  </span>
                </th>
                <th className="torrent-table-th" style={{ width: "220px" }}>
                  Component / Logger
                </th>
                <th className="torrent-table-th">Event Message</th>
              </tr>
            </thead>
            <tbody>
              {isLoading && (
                <tr>
                  <td colSpan={4} className="torrent-table-empty">
                    Loading event stream...
                  </td>
                </tr>
              )}
              {!isLoading && isError && (
                <tr>
                  <td colSpan={4} className="torrent-table-empty">
                    Failed to load events.
                  </td>
                </tr>
              )}
              {!isLoading && !isError && filteredEntries.length === 0 && (
                <tr>
                  <td colSpan={4} className="torrent-table-empty">
                    {searchText || levelFilter !== "All"
                      ? "No events match the selected filters."
                      : "No recent events logged."}
                  </td>
                </tr>
              )}
              {currentEntries.map((entry) => (
                <tr
                  key={entry.id}
                  className="torrent-table-row"
                  onClick={() => setSelectedEvent(entry)}
                  style={{ cursor: "pointer" }}
                  title="Click to view event details"
                >
                  <td>
                    <EventLevelIcon level={entry.level} />
                  </td>
                  <td
                    style={{
                      color: "var(--text-muted)",
                      fontSize: "0.85rem",
                      whiteSpace: "nowrap",
                    }}
                    title={entry.timestamp}
                  >
                    {formatEventTime(entry.timestamp)}
                  </td>
                  <td>
                    <code
                      style={{
                        fontSize: "0.8rem",
                        color: "var(--accent, #c8a84e)",
                      }}
                    >
                      {entry.component}
                    </code>
                  </td>
                  <td style={{ fontSize: "0.85rem" }}>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "baseline",
                        justifyContent: "space-between",
                        gap: "0.75rem",
                      }}
                    >
                      <span
                        style={{
                          whiteSpace: "pre-wrap",
                          wordBreak: "break-word",
                          display: "-webkit-box",
                          WebkitLineClamp: 3,
                          WebkitBoxOrient: "vertical",
                          overflow: "hidden",
                        }}
                      >
                        {entry.message}
                      </span>
                      {entry.exception && (
                        <span
                          className="badge badge-error"
                          style={{
                            fontSize: "0.7rem",
                            padding: "0.1rem 0.35rem",
                            flexShrink: 0,
                          }}
                          title="Has exception stack trace"
                        >
                          Exception
                        </span>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination Card Footer */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            padding: "0.75rem 1rem",
            backgroundColor: "var(--bg-secondary)",
            borderTop: "1px solid var(--border-light)",
            flexWrap: "wrap",
            gap: "0.75rem",
          }}
        >
          {/* Left: Range info & Page Size selector */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "1.25rem",
              flexWrap: "wrap",
            }}
          >
            <span style={{ fontSize: "0.85rem", color: "var(--text-muted)" }}>
              {filteredEntries.length === 0
                ? "Showing 0-0 of 0"
                : `Showing ${startIndex + 1}-${endIndex} of ${filteredEntries.length}`}
            </span>

            <div
              style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}
            >
              <span style={{ fontSize: "0.85rem", color: "var(--text-muted)" }}>
                Per page:
              </span>
              <select
                className="form-select"
                value={pageSize}
                onChange={(e) => {
                  setPageSize(Number(e.target.value));
                  setCurrentPage(1);
                }}
                style={{
                  padding: "0.25rem 1.75rem 0.25rem 0.5rem",
                  fontSize: "0.82rem",
                  width: "auto",
                  minWidth: "70px",
                  height: "30px",
                }}
              >
                {PAGE_SIZE_OPTIONS.map((size) => (
                  <option key={size} value={size}>
                    {size}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Right: Page Navigation */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "0.35rem",
              flexWrap: "wrap",
            }}
          >
            <button
              type="button"
              className="btn btn-small btn-outline"
              onClick={() => setCurrentPage(1)}
              disabled={activePage <= 1}
              title="First Page"
              style={{ minWidth: "30px", padding: "0.25rem 0.5rem" }}
            >
              «
            </button>
            <button
              type="button"
              className="btn btn-small btn-outline"
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              disabled={activePage <= 1}
              title="Previous Page"
              style={{ minWidth: "30px", padding: "0.25rem 0.5rem" }}
            >
              ‹
            </button>

            {pageNumbers.map((p, idx) =>
              typeof p === "number" ? (
                <button
                  key={p}
                  type="button"
                  className={`btn btn-small ${activePage === p ? "log-filter-active" : "btn-outline"}`}
                  onClick={() => setCurrentPage(p)}
                  style={{ minWidth: "30px", padding: "0.25rem 0.5rem" }}
                >
                  {p}
                </button>
              ) : (
                <span
                  key={`ellipsis-${idx}`}
                  style={{
                    padding: "0 0.35rem",
                    color: "var(--text-muted)",
                    userSelect: "none",
                  }}
                >
                  {p}
                </span>
              ),
            )}

            <button
              type="button"
              className="btn btn-small btn-outline"
              onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
              disabled={activePage >= totalPages}
              title="Next Page"
              style={{ minWidth: "30px", padding: "0.25rem 0.5rem" }}
            >
              ›
            </button>
            <button
              type="button"
              className="btn btn-small btn-outline"
              onClick={() => setCurrentPage(totalPages)}
              disabled={activePage >= totalPages}
              title="Last Page"
              style={{ minWidth: "30px", padding: "0.25rem 0.5rem" }}
            >
              »
            </button>
          </div>
        </div>
      </div>

      {/* Event Details Modal */}
      {selectedEvent && (
        <EventDetailsModal
          event={selectedEvent}
          onClose={() => setSelectedEvent(null)}
        />
      )}
    </div>
  );
}

