export default SystemResources;

import { useState } from "react";
import { Link } from "react-router";
import { useQueryClient } from "@tanstack/react-query";
import { useTranslation } from "../i18n";
import {
  useSystemStatus,
  useHealthChecks,
  useDiskSpace,
  useArrConnections,
  useDownloadClients,
  useIndexers,
} from "../api/hooks";
import { apiClient } from "../api/client";
import { useToast } from "../context/ToastContext";
import { formatBytes, formatUptime } from "../utils/formatters";
import { getDownloadClientUrl } from "../utils/arrLinks";
import { trackSystemLifecycle } from "../utils/analytics";

function SystemStatus() {
  const { t } = useTranslation();
  const { data: status, isLoading: statusLoading } = useSystemStatus();
  const { data: health, isLoading: healthLoading } = useHealthChecks();
  const { data: diskSpace, isLoading: diskLoading } = useDiskSpace();
  const { data: arrConnections } = useArrConnections();
  const { data: downloadClients } = useDownloadClients();
  const { data: indexers } = useIndexers();

  const { showToast } = useToast();
  const queryClient = useQueryClient();
  const [showRestartModal, setShowRestartModal] = useState(false);
  const [showShutdownModal, setShowShutdownModal] = useState(false);
  const [isRestarting, setIsRestarting] = useState(false);
  const [isShuttingDown, setIsShuttingDown] = useState(false);

  const isLoading = statusLoading || healthLoading || diskLoading;

  const isWarningOrError = (type?: string) => {
    const t = type?.toLowerCase();
    return t === "warning" || t === "error";
  };

  const warningOrErrorChecks =
    health?.filter((c) => isWarningOrError(c.type)) ?? [];

  const handleRestart = async () => {
    trackSystemLifecycle("restart");
    setIsRestarting(true);
    setShowRestartModal(false);
    window.dispatchEvent(new CustomEvent("seedarr:restarting"));
    try {
      await apiClient.post("/system/restart");
      showToast(
        t(
          "systemStatus.restartingToast",
          undefined,
          "System is restarting. Waiting for reconnection...",
        ),
        "info",
      );
      pollReconnect();
    } catch (err: any) {
      setIsRestarting(false);
      showToast(
        t(
          "systemStatus.restartFailedToast",
          { error: err?.message || "Unknown error" },
          `Failed to trigger restart: ${err?.message || "Unknown error"}`,
        ),
        "error",
      );
    }
  };

  const pollReconnect = () => {
    let attempts = 0;
    const maxAttempts = 30;
    const interval = setInterval(async () => {
      attempts++;
      try {
        const res = await fetch("/api/v1/system/status");
        if (res.ok) {
          clearInterval(interval);
          setIsRestarting(false);
          showToast(
            t(
              "systemStatus.reconnectedToast",
              undefined,
              "Seedarr has reconnected successfully!",
            ),
            "success",
          );
          queryClient.invalidateQueries({ queryKey: ["systemStatus"] });
        }
      } catch {
        // Service is restarting, continue waiting
      }

      if (attempts >= maxAttempts) {
        clearInterval(interval);
        setIsRestarting(false);
        showToast(
          t(
            "systemStatus.reconnectTimeoutToast",
            undefined,
            "Reconnection timed out. Please refresh the page manually.",
          ),
          "error",
        );
      }
    }, 2000);
  };

  const handleShutdown = async () => {
    trackSystemLifecycle("shutdown");
    setIsShuttingDown(true);
    setShowShutdownModal(false);
    try {
      await apiClient.post("/system/shutdown");
      showToast(
        t(
          "systemStatus.shuttingDownToast",
          undefined,
          "System is shutting down. Service is terminating.",
        ),
        "info",
      );
    } catch (err: any) {
      setIsShuttingDown(false);
      showToast(
        t(
          "systemStatus.shutdownFailedToast",
          { error: err?.message || "Unknown error" },
          `Failed to trigger shutdown: ${err?.message || "Unknown error"}`,
        ),
        "error",
      );
    }
  };

  return (
    <div className="content-area" style={{ padding: "1.5rem" }}>
      {/* Header Banner */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "1.5rem",
          flexWrap: "wrap",
          gap: "1rem",
        }}
      >
        <div>
          <h1
            style={{
              fontSize: "1.75rem",
              fontWeight: 700,
              margin: 0,
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
            }}
          >
            <span>🖥️</span> System: Status
          </h1>
          <p
            style={{
              color: "var(--text-muted, #888)",
              margin: "0.25rem 0 0 0",
              fontSize: "0.9rem",
            }}
          >
            Runtime environment, service health checks, disk allocations, and
            integrated ecosystem endpoints
          </p>
        </div>

        <div
          style={{
            display: "flex",
            gap: "0.75rem",
            alignItems: "center",
            flexWrap: "wrap",
          }}
        >
          {status && (
            <span
              className="badge badge-seeding"
              style={{ padding: "0.35rem 0.75rem", fontSize: "0.85rem" }}
            >
              ● Uptime: {formatUptime(status.uptimeSeconds)}
            </span>
          )}
          <button
            type="button"
            className="btn btn-outline btn-small"
            onClick={() => setShowRestartModal(true)}
            disabled={isRestarting || isShuttingDown}
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: "0.4rem",
            }}
          >
            <span>🔄</span>
            <span>{isRestarting ? "Restarting..." : "Restart"}</span>
          </button>
          <button
            type="button"
            className="btn btn-danger btn-small"
            onClick={() => setShowShutdownModal(true)}
            disabled={isRestarting || isShuttingDown}
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: "0.4rem",
            }}
          >
            <span>⏻</span>
            <span>{isShuttingDown ? "Shutting Down..." : "Shutdown"}</span>
          </button>
        </div>
      </div>

      {isLoading && <p className="loading">Loading system status...</p>}

      {/* Health Section Card */}
      <div
        className="card"
        style={{
          marginBottom: "1.25rem",
          borderRadius: "8px",
          border: "1px solid var(--border-light)",
          boxShadow:
            "0 4px 14px rgba(0, 0, 0, 0.32), 0 1px 3px rgba(0, 0, 0, 0.18)",
          padding: "1.25rem",
        }}
      >
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginBottom: "0.85rem",
          }}
        >
          <div>
            <h2
              style={{
                fontSize: "1.05rem",
                fontWeight: 600,
                color: "var(--accent, #c8a84e)",
                margin: 0,
              }}
            >
              System Health & Diagnostics
            </h2>
            <div
              style={{
                fontSize: "0.8rem",
                color: "var(--text-muted)",
                marginTop: "0.2rem",
              }}
            >
              Automated configuration verifiers and daemon liveness checks
            </div>
          </div>
          <span
            className={`badge ${warningOrErrorChecks.length === 0 ? "badge-seeding" : "badge-error"}`}
          >
            {warningOrErrorChecks.length === 0
              ? "All Systems Operational"
              : `${warningOrErrorChecks.length} Issue${warningOrErrorChecks.length > 1 ? "s" : ""}`}
          </span>
        </div>

        {warningOrErrorChecks.length === 0 ? (
          <div
            style={{
              padding: "0.85rem 1.15rem",
              borderRadius: "6px",
              backgroundColor: "rgba(40, 167, 69, 0.12)",
              border: "1px solid rgba(40, 167, 69, 0.3)",
