                  >
                    Fix in Settings ⚙️
                  </Link>
                </div>
              );
            })}
          </div>
        )}

        {/* File Descriptors & Sockets Telemetry */}
        {status && status.openFileDescriptors !== undefined && (
          <div
            style={{
              marginTop: "1.25rem",
              paddingTop: "1rem",
              borderTop:
                "1px solid var(--border-light, rgba(255, 255, 255, 0.08))",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "0.5rem",
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "0.5rem",
                }}
              >
                <strong
                  style={{
                    fontSize: "0.9rem",
                    color: "var(--text-primary)",
                  }}
                >
                  {t(
                    "systemStatus.fileDescriptorsAndSockets",
                    "File Descriptors & Sockets",
                  )}
                </strong>
                <span
                  style={{
                    fontSize: "0.8rem",
                    color: "var(--text-muted)",
                  }}
                >
                  ({status.openFileDescriptors?.toLocaleString() ?? 0}
                  {" / "}
                  {status.maxFileDescriptors && status.maxFileDescriptors > 0
                    ? status.maxFileDescriptors.toLocaleString()
                    : t("systemStatus.unlimited", "Unlimited")}
                  )
                </span>
              </div>
              {status.fileDescriptorUsagePercentage != null ? (
                <span
                  className={`badge ${
                    status.fileDescriptorUsagePercentage >= 90
                      ? "badge-error"
                      : status.fileDescriptorUsagePercentage >= 80
                        ? "badge-warning"
                        : "badge-seeding"
                  }`}
                  style={{ fontSize: "0.75rem", padding: "0.2rem 0.5rem" }}
                >
                  {t(
                    "systemStatus.percentUsed",
                    {
                      percent: status.fileDescriptorUsagePercentage.toFixed(1),
                    },
                    `${status.fileDescriptorUsagePercentage.toFixed(1)}% Used`,
                  )}
                </span>
              ) : (
                <span
                  className="badge badge-primary"
                  style={{ fontSize: "0.75rem", padding: "0.2rem 0.5rem" }}
                >
                  {t("systemStatus.osHandles", "OS Handles")}
                </span>
              )}
            </div>

            {status.fileDescriptorUsagePercentage != null && (
              <div
