describe("Tags: calculateTagUsageCounts", () => {
  const tags: Tag[] = [
    createMockTag({ id: 1, label: "Anime" }),
    createMockTag({ id: 2, label: "4K" }),
    createMockTag({ id: 3, label: "Music" }),
  ];

  it("should return empty object when torrents list is empty or null", () => {
    assert.deepEqual(calculateTagUsageCounts(null, "All", tags), {});
    assert.deepEqual(calculateTagUsageCounts([], "All", tags), {});
    assert.deepEqual(calculateTagUsageCounts(undefined, "All", tags), {});
  });

  it("should calculate usage count from torrent.tagIds", () => {
    const torrents: Torrent[] = [
      createMockTorrent({ id: 101, tagIds: [1, 2] }),
      createMockTorrent({ id: 102, tagIds: [1] }),
      createMockTorrent({ id: 103, tagIds: [3] }),
      createMockTorrent({ id: 104, tagIds: [] }),
    ];

    const counts = calculateTagUsageCounts(torrents, "All", tags);
    assert.equal(counts[1], 2);
    assert.equal(counts[2], 1);
    assert.equal(counts[3], 1);
    assert.equal(counts[999], undefined);
  });

  it("should support fallback to torrent.tags if tagIds is absent", () => {
    const torrents = [
      createMockTorrent({ id: 201, tagIds: undefined }),
      createMockTorrent({ id: 202, tagIds: undefined }),
    ];
    (torrents[0] as any).tags = [2];
    (torrents[1] as any).tags = [2, 3];

    const counts = calculateTagUsageCounts(torrents, "All", tags);
    assert.equal(counts[2], 2);
    assert.equal(counts[3], 1);
  });

  it("should support backward compatibility with legacy torrent.label", () => {
    const torrents: Torrent[] = [
      createMockTorrent({ id: 301, tagIds: [], label: "Anime" }),
      createMockTorrent({ id: 302, tagIds: [], label: "4K, Music" }),
    ];

    const counts = calculateTagUsageCounts(torrents, "All", tags);
    assert.equal(counts[1], 1);
    assert.equal(counts[2], 1);
    assert.equal(counts[3], 1);
  });

  it("should not duplicate count if torrent has both matching tagId and legacy label", () => {
    const torrents: Torrent[] = [
      createMockTorrent({ id: 401, tagIds: [1], label: "Anime" }),
    ];

    const counts = calculateTagUsageCounts(torrents, "All", tags);
    assert.equal(counts[1], 1);
  });

  it("should filter tag counts by selectedCategory", () => {
    const torrents: Torrent[] = [
      createMockTorrent({ id: 501, tagIds: [1], category: "Movies" }),
      createMockTorrent({ id: 502, tagIds: [1], category: "Series" }),
      createMockTorrent({ id: 503, tagIds: [1, 2], category: "Series" }),
      createMockTorrent({ id: 504, tagIds: [1], category: null }),
    ];

    const seriesCounts = calculateTagUsageCounts(torrents, "Series", tags);
    assert.equal(seriesCounts[1], 2);
    assert.equal(seriesCounts[2], 1);

    const moviesCounts = calculateTagUsageCounts(torrents, "Movies", tags);
    assert.equal(moviesCounts[1], 1);
    assert.equal(moviesCounts[2], undefined);

    const uncatCounts = calculateTagUsageCounts(
      torrents,
      "Uncategorized",
      tags,
    );
    assert.equal(uncatCounts[1], 1);
  });
});

describe("Tags: Deletion and Filter State Synchronization", () => {
  it("should sanitize active tag filter when a tag is deleted", () => {
    let selectedTag = "Anime";
    let selectedTagIds = new Set([1, 2]);

    const handleTagDeleted = (detail: { id: number; label: string }) => {
      if (selectedTagIds.has(detail.id)) {
        selectedTagIds.delete(detail.id);
      }
      if (selectedTag === detail.label) {
        selectedTag = "All";
      }
    };

    // Delete tag 1 (Anime)
    handleTagDeleted({ id: 1, label: "Anime" });

    assert.equal(selectedTag, "All");
    assert.equal(selectedTagIds.has(1), false);
    assert.equal(selectedTagIds.has(2), true);
  });

  it("should strip leading and trailing whitespace when creating or editing tags", () => {
    const inputLabel = "   seedbox-vip   ";
    const trimmed = inputLabel.trim();
    assert.equal(trimmed, "seedbox-vip");
  });
});

import { useState, useMemo } from "react";
import {
  useTags,
  useCreateTag,
  useUpdateTag,
  useDeleteTag,
  useTorrents,
  useCategories,
} from "../api/hooks";
import type { Tag, Torrent } from "../api/types";
import { trackTagAction } from "../utils/analytics";

const COLOR_PRESETS = [
  "#3b82f6", // Blue
  "#10b981", // Emerald
  "#f59e0b", // Amber
  "#ef4444", // Red
  "#8b5cf6", // Purple
  "#ec4899", // Pink
  "#06b6d4", // Cyan
  "#6366f1", // Indigo
];

function formatTime(seconds?: number): string {
  if (!seconds || seconds <= 0) return "";
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.round(seconds / 60)}m`;
  if (seconds < 86400) return `${(seconds / 3600).toFixed(1)}h`;
  return `${(seconds / 86400).toFixed(1)}d`;
}

export function calculateTagUsageCounts(
  torrents?: Torrent[] | null,
  selectedCategory: string = "All",
  tags?: Tag[] | null,
): Record<number, number> {
  const counts: Record<number, number> = {};
  if (torrents) {
    for (const t of torrents) {
      if (selectedCategory !== "All") {
        const cat = t.category?.trim() || "Uncategorized";
        if (cat !== selectedCategory) continue;
      }
      const ids = t.tagIds ?? (t as any).tags ?? [];
      for (const id of ids) {
        counts[id] = (counts[id] ?? 0) + 1;
      }
      // Also support legacy t.label match if tag.label matches, for backward compatibility
      if (t.label && tags) {
        const labels = t.label.split(",").map((s) => s.trim().toLowerCase());
        for (const tag of tags) {
          if (
            labels.includes(tag.label.toLowerCase()) &&
            !ids.includes(tag.id)
          ) {
            counts[tag.id] = (counts[tag.id] ?? 0) + 1;
          }
        }
      }
    }
  }
  return counts;
}

function Tags() {
  const { data: tags, isLoading, isError } = useTags();
  const { data: torrents } = useTorrents();
  const { data: categories } = useCategories();
  const createTag = useCreateTag();
  const updateTag = useUpdateTag();
  const deleteTag = useDeleteTag();

  const [modalTag, setModalTag] = useState<Partial<Tag> | null>(null);
  const [deletingTag, setDeletingTag] = useState<Tag | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<string>("All");

  const tagList = tags ?? [];

  const tagUsageCounts = useMemo(() => {
    return calculateTagUsageCounts(torrents, selectedCategory, tags);
  }, [torrents, selectedCategory, tags]);

  const getTagUsageCount = (tag: Tag) => {
    if (
      selectedCategory === "All" &&
      !torrents &&
      tag.torrentCount !== undefined
    ) {
      return tag.torrentCount;
    }
    return tagUsageCounts[tag.id] ?? 0;
  };

  function handleDelete(id: number) {
    const target = tagList.find((t) => t.id === id);
    if (target) {
      setDeletingTag(target);
    }
  }

  function handleSaveModal() {
    if (!modalTag || !modalTag.label?.trim()) return;

    const trimmedLabel = modalTag.label.trim();
    const payload: Partial<Tag> = {
      ...modalTag,
      label: trimmedLabel,
      color: modalTag.color?.trim() || undefined,
      uploadLimitKbps: modalTag.uploadLimitKbps
        ? Number(modalTag.uploadLimitKbps)
        : undefined,
      downloadLimitKbps: modalTag.downloadLimitKbps
        ? Number(modalTag.downloadLimitKbps)
        : undefined,
      minSeedRatio: modalTag.minSeedRatio
        ? Number(modalTag.minSeedRatio)
        : undefined,
      minSeedTimeSeconds: modalTag.minSeedTimeSeconds
        ? Number(modalTag.minSeedTimeSeconds)
        : undefined,
    };

    if (payload.id) {
      updateTag.mutate(payload as Tag, {
        onSuccess: () => {
          trackTagAction("update");
          setModalTag(null);
        },
      });
    } else {
      createTag.mutate(payload, {
        onSuccess: () => {
          trackTagAction("create");
          setModalTag(null);
        },
      });
    }
  }

  function confirmDeleteTag() {
    if (!deletingTag) return;
    const deletedId = deletingTag.id;
    const deletedLabel = deletingTag.label;
    deleteTag.mutate(deletedId, {
      onSuccess: () => {
        trackTagAction("delete");
        if (typeof window !== "undefined") {
          window.dispatchEvent(
            new CustomEvent("seedarr:tag-deleted", {
              detail: { id: deletedId, label: deletedLabel },
            }),
          );
        }
        setDeletingTag(null);
      },
    });
  }

  return (
    <div className="content-area" style={{ padding: "1.5rem" }}>
      {/* Header Banner */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "1.5rem",
          flexWrap: "wrap",
          gap: "1rem",
        }}
      >
        <div>
          <h1
            style={{
              fontSize: "1.75rem",
              fontWeight: 700,
              margin: 0,
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
            }}
          >
            <span>🏷️</span> Tags ({tagList.length})
          </h1>
          <p
            style={{
              color: "var(--text-muted, #888)",
              margin: "0.25rem 0 0 0",
              fontSize: "0.9rem",
            }}
          >
            Organize and filter torrent swarms by custom labels, colors, and
            seeding policies
          </p>
        </div>

        <div style={{ display: "flex", gap: "0.75rem", alignItems: "center" }}>
          {categories && categories.length > 0 && (
            <div
              style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}
            >
              <label
                htmlFor="category-filter"
                style={{ fontSize: "0.85rem", color: "var(--text-muted)" }}
              >
                Category:
              </label>
              <select
                id="category-filter"
                className="form-input"
                style={{
                  padding: "0.35rem 0.6rem",
                  fontSize: "0.85rem",
                  height: "auto",
                }}
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
              >
                <option value="All">All Categories</option>
                {categories.map((c) => (
                  <option key={c.id} value={c.name}>
                    {c.name}
                  </option>
                ))}
                <option value="Uncategorized">Uncategorized</option>
              </select>
            </div>
          )}
          <button
            className="btn btn-primary"
            onClick={() => setModalTag({ label: "", color: "#3b82f6" })}
