                </tr>
              </thead>
              <tbody>
                {tagList.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="torrent-table-empty">
                      No tags defined yet. Click &quot;+ Add Tag&quot; to create
                      one.
                    </td>
                  </tr>
                ) : (
                  tagList.map((tag) => (
                    <tr key={tag.id} className="torrent-table-row">
                      <td>
                        <span
                          className={`badge ${!tag.color ? "badge-primary" : ""}`}
                          style={{
                            fontSize: "0.82rem",
                            padding: "0.25rem 0.65rem",
                            backgroundColor: tag.color || undefined,
                            borderColor: tag.color || undefined,
                            color: tag.color ? "#fff" : undefined,
                            fontWeight: 600,
                            display: "inline-flex",
                            alignItems: "center",
                            gap: "0.35rem",
                          }}
                        >
                          🏷️ {tag.label}
                        </span>
                      </td>
                      <td>
                        <div
                          style={{
                            display: "flex",
                            gap: "0.4rem",
                            flexWrap: "wrap",
                            fontSize: "0.8rem",
                          }}
                        >
                          {tag.uploadLimitKbps ? (
                            <span
                              className="badge badge-secondary"
                              title="Upload Limit"
                            >
                              ↑ {tag.uploadLimitKbps} KB/s
                            </span>
                          ) : null}
                          {tag.downloadLimitKbps ? (
                            <span
                              className="badge badge-secondary"
                              title="Download Limit"
                            >
                              ↓ {tag.downloadLimitKbps} KB/s
                            </span>
