                            !tag.downloadLimitKbps &&
                            !tag.minSeedRatio &&
                            !tag.minSeedTimeSeconds && (
                              <span
                                style={{
                                  color: "var(--text-muted)",
                                  fontStyle: "italic",
                                }}
                              >
                                Default
                              </span>
                            )}
                        </div>
                      </td>
                      <td>
                        <span style={{ fontWeight: 600 }}>
                          {getTagUsageCount(tag)}
                        </span>{" "}
                        <span
                          style={{
                            color: "var(--text-muted)",
                            fontSize: "0.8rem",
                          }}
                        >
                          {selectedCategory !== "All"
                            ? `torrents (${selectedCategory})`
                            : "torrents"}
                        </span>
                      </td>
                      <td style={{ textAlign: "right" }}>
                        <div style={{ display: "inline-flex", gap: "0.5rem" }}>
                          <button
                            className="btn btn-outline btn-small"
                            onClick={() => setModalTag({ ...tag })}
                          >
                            Edit
                          </button>
                          <button
                            className="btn btn-danger btn-small"
                            onClick={() => handleDelete(tag.id)}
                          >
                            Delete
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Add / Edit Tag Modal */}
      {modalTag && (
        <div className="modal-overlay" onClick={() => setModalTag(null)}>
          <div
            className="modal"
            onClick={(e) => e.stopPropagation()}
            style={{
              maxWidth: 520,
              borderRadius: "8px",
              boxShadow: "0 16px 40px rgba(0,0,0,0.7)",
              border: "1px solid var(--border-light)",
            }}
          >
            <h3
              className="modal-title"
              style={{ fontSize: "1.15rem", marginBottom: "1rem" }}
            >
              {modalTag.id ? `Edit Tag: "${modalTag.label}"` : "Add Tag"}
            </h3>

            {/* Label Input */}
            <div style={{ marginBottom: "1rem" }}>
              <label
                style={{
                  display: "block",
                  fontSize: "0.85rem",
                  fontWeight: 600,
                  marginBottom: "0.35rem",
                }}
              >
                Tag Label *
              </label>
              <input
                type="text"
                className="form-input"
                placeholder="e.g. 4k-hdr, seedbox, ptp"
                value={modalTag.label || ""}
                onChange={(e) =>
                  setModalTag({ ...modalTag, label: e.target.value })
                }
                autoFocus
              />
            </div>

            {/* Color Customization */}
            <div style={{ marginBottom: "1.25rem" }}>
              <label
                style={{
                  display: "block",
                  fontSize: "0.85rem",
                  fontWeight: 600,
                  marginBottom: "0.35rem",
                }}
              >
                Color Customization
              </label>
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "0.5rem",
                  marginBottom: "0.5rem",
                }}
              >
                <input
                  type="color"
                  value={modalTag.color || "#3b82f6"}
