                  style={{
                    width: "36px",
                    height: "36px",
                    padding: "0",
                    border: "1px solid var(--border-light)",
                    borderRadius: "4px",
                    cursor: "pointer",
                    backgroundColor: "transparent",
                  }}
                />
                <input
                  type="text"
                  className="form-input"
                  placeholder="#3b82f6"
