            </h3>

            <div
              style={{
                padding: "0.75rem 1rem",
                borderRadius: "6px",
                backgroundColor: "rgba(220, 53, 69, 0.15)",
                border: "1px solid rgba(220, 53, 69, 0.35)",
                color: "var(--danger, #dc3545)",
                fontSize: "0.85rem",
                marginBottom: "1rem",
                lineHeight: 1.4,
              }}
            >
              ⚠️ Warning: Deleting this tag will remove it from all assigned
              torrents, indexers, and automated rules. This action cannot be
              undone.
            </div>

            <p
              style={{
                fontSize: "0.875rem",
                color: "var(--text-secondary)",
                marginBottom: "1.25rem",
                lineHeight: 1.5,
              }}
            >
              Are you sure you want to delete tag{" "}
              <strong>{deletingTag.label}</strong>?
              {getTagUsageCount(deletingTag) ? (
                <>
                  <br />
                  Currently assigned to{" "}
                  <strong>{getTagUsageCount(deletingTag)}</strong>{" "}
                  {getTagUsageCount(deletingTag) === 1 ? "torrent" : "torrents"}
                  .
                </>
              ) : (
                <>
                  <br />
                  This tag is not currently assigned to any torrents.
                </>
              )}
            </p>

            <div
              className="modal-actions"
              style={{
                display: "flex",
                justifyContent: "flex-end",
                gap: "0.5rem",
              }}
            >
              <button
                className="btn btn-outline btn-small"
                onClick={() => setDeletingTag(null)}
                disabled={deleteTag.isPending}
              >
                Cancel
              </button>
              <button
                className="btn btn-danger btn-small"
                onClick={confirmDeleteTag}
                disabled={deleteTag.isPending}
              >
                {deleteTag.isPending ? "Deleting..." : "Delete Tag"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Tags;

import { useState, useEffect, useCallback } from "react";
import { useNavigate } from "react-router";
import TorrentTable from "../components/TorrentTable";
import TorrentGrid from "../components/TorrentGrid";
import TorrentDetailPanel from "../components/TorrentDetailPanel";
import AddTorrentModal from "../components/AddTorrentModal";
import ImportPackageModal from "../components/ImportPackageModal";
import DeleteTorrentModal from "../components/DeleteTorrentModal";
import BulkTagModal from "../components/BulkTagModal";
import { QuickSettingsDrawer } from "../components/quicksettings";
import { TorrentToolbar } from "./torrentindex/TorrentToolbar";
import { TorrentFilterPanel } from "./torrentindex/TorrentFilterPanel";
import { useTorrentIndexState } from "./torrentindex/useTorrentIndexState";
import { useColumnPreferences } from "./torrentindex/columnPreferences";
import {
  useAnnounceTorrent,
  useBulkTorrentAction,
  useMoveTorrentQueue,
  useRecheckTorrent,
} from "../api/hooks";
import { useToast } from "../context/ToastContext";
import { useModalStack } from "../components/ModalProvider";
import { trackBulkAction, trackQueueMove } from "../utils/analytics";

function TorrentIndex() {
  const navigate = useNavigate();
  const { showToast } = useToast();
  const announceTorrent = useAnnounceTorrent();
  const recheckTorrent = useRecheckTorrent();
  const bulkAction = useBulkTorrentAction();
  const { modalCount } = useModalStack();
  const {
    visibleColumns,
    toggleColumn,
    resetToDefaults: resetColumns,
    resetSort,
    selectAll: selectAllColumns,
    deselectAll: deselectAllColumns,
    applyPreset: applyColumnPreset,
    toggleCategory: toggleCategoryColumns,
    columnOrder,
    setColumnOrder,
    columnWidths,
    setColumnWidths,
  } = useColumnPreferences();
  const {
    torrents,
    filteredTorrents,
    startSeeding,
    stopSeeding,
    startAll,
    stopAll,
    seedingConfig,
    filter,
    setFilter,
    showAddModal,
    setShowAddModal,
    selectedIds,
    setSelectedIds,
    viewMode,
    selectedState,
    setSelectedState,
    selectedTracker,
    setSelectedTracker,
    selectedCategory,
    setSelectedCategory,
    selectedTag,
    setSelectedTag,
    tags,
    selectedTagIds,
    toggleTag,
    clearTags,
    tagMatchMode,
    setTagMatchMode,
    untaggedCount,
    selectedTorrentId,
    setSelectedTorrentId,
    adjustSpeed,
    stateCounts,
    trackerGroups,
    categoryGroups,
    tagGroups,
    totalUploadSpeed,
    totalDownloadSpeed,
    handleViewMode,
    handleToggleSelect,
    handleSelectAll,
    handleSelectRange,
    setAnchorIndex,
    isFilterCollapsed,
    toggleFilterCollapse,
    isQuickControlsOpen,
    toggleQuickControls,
    closeQuickControls,
  } = useTorrentIndexState();

  const [bulkPending, setBulkPending] = useState(false);
  const [showImportPackageModal, setShowImportPackageModal] = useState(false);
  const [bulkTagModalState, setBulkTagModalState] = useState<{
    isOpen: boolean;
    mode: "add" | "remove";
  } | null>(null);
  const [deleteModalState, setDeleteModalState] = useState<{
    isOpen: boolean;
    targetIds: number[];
    torrentName?: string;
  } | null>(null);

  const handleBulkAddTags = useCallback(() => {
    if (selectedIds.size === 0) return;
    setBulkTagModalState({ isOpen: true, mode: "add" });
  }, [selectedIds]);

  const handleBulkRemoveTags = useCallback(() => {
    if (selectedIds.size === 0) return;
    setBulkTagModalState({ isOpen: true, mode: "remove" });
  }, [selectedIds]);

  const handleConfirmBulkTag = useCallback(
    async (tagIds: number[]) => {
      if (!bulkTagModalState || selectedIds.size === 0 || tagIds.length === 0)
        return;
      const mode = bulkTagModalState.mode;
      const ids = Array.from(selectedIds);
      setBulkPending(true);
      try {
        const res = await bulkAction.mutateAsync({
          torrentIds: ids,
          action: mode === "add" ? "addtags" : "removetags",
          tagIds,
        });

        if (res.failedCount === 0) {
          showToast(
            mode === "add"
              ? `Successfully assigned tags to ${res.successCount} torrent(s).`
              : `Successfully removed tags from ${res.successCount} torrent(s).`,
            "success",
          );
        } else {
          showToast(
            `${res.successCount} succeeded, ${res.failedCount} failed`,
            "warning",
          );
        }
        setBulkTagModalState(null);
      } catch (err: unknown) {
        const msg =
          err instanceof Error
            ? err.message
            : `Failed to ${mode === "add" ? "assign" : "remove"} tags`;
        showToast(msg, "error");
      } finally {
        setBulkPending(false);
      }
    },
    [bulkTagModalState, selectedIds, bulkAction, showToast],
  );

  const handleBulkStart = useCallback(async () => {
    if (selectedIds.size === 0) return;
    setBulkPending(true);
    const ids = [...selectedIds];
    try {
      const res = await bulkAction.mutateAsync({
        torrentIds: ids,
        action: "start",
      });
      trackBulkAction("start", ids.length);
      const succeeded = res.succeededIds ?? [];

      setSelectedIds((prev) => {
        const next = new Set(prev);
        succeeded.forEach((id) => next.delete(id));
        return next;
      });

      if (res.failedCount === 0) {
        showToast(
          `Successfully started ${res.successCount} torrent(s).`,
          "success",
        );
      } else {
        showToast(
          `${res.successCount} started, ${res.failedCount} failed`,
          "warning",
        );
      }
    } catch (err: unknown) {
      const msg =
        err instanceof Error ? err.message : "Failed to start torrents";
      showToast(msg, "error");
    } finally {
      setBulkPending(false);
    }
  }, [selectedIds, bulkAction, setSelectedIds, showToast]);

  const handleBulkStop = useCallback(async () => {
    if (selectedIds.size === 0) return;
    setBulkPending(true);
    const ids = [...selectedIds];
    try {
      const res = await bulkAction.mutateAsync({
        torrentIds: ids,
        action: "stop",
      });
      trackBulkAction("stop", ids.length);
      const succeeded = res.succeededIds ?? [];

      setSelectedIds((prev) => {
        const next = new Set(prev);
        succeeded.forEach((id) => next.delete(id));
        return next;
      });

      if (res.failedCount === 0) {
        showToast(
          `Successfully stopped ${res.successCount} torrent(s).`,
          "success",
        );
      } else {
        showToast(
          `${res.successCount} stopped, ${res.failedCount} failed`,
          "warning",
        );
      }
    } catch (err: unknown) {
      const msg =
        err instanceof Error ? err.message : "Failed to stop torrents";
      showToast(msg, "error");
    } finally {
      setBulkPending(false);
    }
  }, [selectedIds, bulkAction, setSelectedIds, showToast]);

  const handleBulkDelete = useCallback(() => {
    const targetIds =
      selectedIds.size > 0
        ? Array.from(selectedIds)
        : selectedTorrentId != null
          ? [selectedTorrentId]
          : [];
    if (targetIds.length === 0) return;
    const torrentName =
      targetIds.length === 1
        ? (torrents ?? []).find((t) => t.id === targetIds[0])?.name
        : undefined;
    setDeleteModalState({
      isOpen: true,
      targetIds,
      torrentName,
    });
  }, [selectedIds, selectedTorrentId, torrents]);

  const handleConfirmBulkDelete = useCallback(
    async (deleteFiles: boolean) => {
      if (!deleteModalState || deleteModalState.targetIds.length === 0) return;
      const targetIds = deleteModalState.targetIds;
      setBulkPending(true);
      try {
        const res = await bulkAction.mutateAsync({
          torrentIds: targetIds,
          action: "delete",
          deleteFiles,
        });
        trackBulkAction("delete", targetIds.length);
        const succeeded = res.succeededIds ?? [];

        setSelectedIds((prev) => {
          const next = new Set(prev);
          succeeded.forEach((id) => next.delete(id));
          return next;
        });

        if (
          selectedTorrentId != null &&
          succeeded.includes(selectedTorrentId)
        ) {
          setSelectedTorrentId(null);
        }

        if (res.failedCount === 0) {
          showToast(
            `Successfully deleted ${res.successCount} torrent(s).`,
            "success",
          );
        } else {
          showToast(
            `${res.successCount} deleted, ${res.failedCount} failed`,
            "warning",
          );
        }
        setDeleteModalState(null);
      } catch (err: unknown) {
        const msg =
          err instanceof Error ? err.message : "Failed to delete torrents";
        showToast(msg, "error");
      } finally {
        setBulkPending(false);
      }
    },
    [
      deleteModalState,
      bulkAction,
      selectedTorrentId,
      setSelectedIds,
      setSelectedTorrentId,
      showToast,
    ],
  );

  const handleToggleActiveSelected = useCallback(() => {
    if (selectedIds.size > 0) {
      const selectedTorrents = (torrents ?? []).filter((t) =>
        selectedIds.has(t.id),
      );
      const anyActive = selectedTorrents.some(
        (t) => t.status === "Seeding" || t.active,
      );
      if (anyActive) {
        handleBulkStop();
      } else {
        handleBulkStart();
      }
      return;
    }

    if (selectedTorrentId != null) {
      const targetTorrent = torrents?.find((t) => t.id === selectedTorrentId);
      if (targetTorrent?.status === "Seeding" || targetTorrent?.active) {
        stopSeeding.mutate(selectedTorrentId);
      } else {
        startSeeding.mutate(selectedTorrentId);
      }
      return;
    }
  }, [
    selectedIds,
    torrents,
    handleBulkStop,
    handleBulkStart,
    selectedTorrentId,
    stopSeeding,
    startSeeding,
  ]);

  const moveTorrentQueue = useMoveTorrentQueue();

  const handleBulkMoveQueue = useCallback(
    async (position: "top" | "up" | "down" | "bottom") => {
      const activeIds = new Set((torrents ?? []).map((t) => t.id));
      let validSelectedIds = Array.from(selectedIds).filter((id) =>
        activeIds.has(id),
      );
      if (
        validSelectedIds.length === 0 &&
        selectedTorrentId != null &&
        activeIds.has(selectedTorrentId)
      ) {
        validSelectedIds = [selectedTorrentId];
      }
      if (validSelectedIds.length === 0) return;

      const orderedIds = (torrents ?? [])
        .filter((t) => validSelectedIds.includes(t.id))
        .map((t) => t.id);

      if (position === "down" || position === "bottom") {
        orderedIds.reverse();
      }

      trackQueueMove(position, validSelectedIds.length);
      setBulkPending(true);
      try {
        for (const id of orderedIds) {
          await moveTorrentQueue.mutateAsync({ id, position });
        }
      } catch (err) {
        const msg =
          err instanceof Error ? err.message : "Failed to move torrents";
        showToast(msg, "error");
      } finally {
        setBulkPending(false);
      }
    },
    [selectedIds, torrents, moveTorrentQueue, showToast],
  );

  // Keyboard Shortcuts Listener for Torrent Operations, Navigation & Modals
  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.defaultPrevented) return;

      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement ||
        e.target instanceof HTMLSelectElement ||
        (e.target as HTMLElement)?.isContentEditable
      ) {
        return;
      }

      // Suppress all page-level shortcuts and Escape processing when any modal is open
      if (
        deleteModalState?.isOpen ||
        showAddModal ||
        bulkTagModalState?.isOpen ||
        showImportPackageModal ||
        modalCount > 0 ||
        (typeof document !== "undefined" &&
          Boolean(
            document.querySelector(
              'dialog[open], [role="dialog"], [aria-modal="true"], .modal-overlay, .modal-backdrop',
            ),
          ))
      ) {
        return;
      }

      // 'q' / 'Q' toggles quick controls drawer
      if (e.key === "q" || e.key === "Q") {
        e.preventDefault();
        toggleQuickControls();
        return;
      }

      // 'Escape' closes detail panel or quick controls drawer
      if (e.key === "Escape") {
        if (isQuickControlsOpen) {
          e.preventDefault();
          closeQuickControls();
          return;
        }
        if (selectedTorrentId != null) {
          e.preventDefault();
          setSelectedTorrentId(null);
          return;
        }
      }

      // Ctrl+Shift+I / Cmd+Shift+I to invert selection
      if (
        (e.ctrlKey || e.metaKey) &&
        e.shiftKey &&
        (e.key === "i" || e.key === "I")
      ) {
        e.preventDefault();
        setSelectedIds((prev) => {
          const next = new Set<number>();
          filteredTorrents.forEach((t) => {
            if (!prev.has(t.id)) {
              next.add(t.id);
            }
          });
          return next;
        });
        return;
      }

      // Ctrl+A / Cmd+A to select all filtered torrents
      if ((e.ctrlKey || e.metaKey) && (e.key === "a" || e.key === "A")) {
        e.preventDefault();
        handleSelectAll(filteredTorrents.map((t) => t.id));
        return;
      }

      // Ctrl + Up/Down, Ctrl + Shift + Up/Down for queue priority
      if (
        (e.ctrlKey || e.metaKey) &&
        (e.key === "ArrowUp" || e.key === "ArrowDown")
      ) {
        e.preventDefault();
        const pos: "top" | "up" | "down" | "bottom" = e.shiftKey
          ? e.key === "ArrowUp"
            ? "top"
            : "bottom"
          : e.key === "ArrowUp"
            ? "up"
            : "down";
        handleBulkMoveQueue(pos);
        return;
      }

      // ArrowUp / ArrowDown navigation across filtered torrents
      if (e.key === "ArrowUp" || e.key === "ArrowDown") {
        if (filteredTorrents.length === 0) return;
        e.preventDefault();
        const currentIndex = filteredTorrents.findIndex(
          (t) => t.id === selectedTorrentId,
        );
        let nextIndex = 0;
        if (e.key === "ArrowUp") {
          nextIndex =
            currentIndex > 0 ? currentIndex - 1 : filteredTorrents.length - 1;
        } else {
          nextIndex =
            currentIndex >= 0 && currentIndex < filteredTorrents.length - 1
              ? currentIndex + 1
              : 0;
        }
        const nextTorrent = filteredTorrents[nextIndex];
        if (nextTorrent) {
          setSelectedTorrentId(nextTorrent.id);
          if (e.shiftKey) {
            handleSelectRange([nextTorrent.id]);
          } else {
            setAnchorIndex(nextIndex);
          }
        }
        return;
      }

      // Home / End to jump to first / last torrent
      if (e.key === "Home") {
        if (filteredTorrents.length > 0) {
          e.preventDefault();
          const target = filteredTorrents[0];
          setSelectedTorrentId(target.id);
          if (e.shiftKey) {
            handleSelectRange([target.id]);
          } else {
            setAnchorIndex(0);
          }
        }
        return;
      }

      if (e.key === "End") {
        if (filteredTorrents.length > 0) {
          e.preventDefault();
          const target = filteredTorrents[filteredTorrents.length - 1];
          setSelectedTorrentId(target.id);
          if (e.shiftKey) {
            handleSelectRange([target.id]);
          } else {
            setAnchorIndex(filteredTorrents.length - 1);
          }
        }
        return;
      }

      // Space: toggle pause/resume or Shift/Ctrl+Space to toggle checkbox selection
      if (e.key === " ") {
        e.preventDefault();
        if (e.shiftKey || e.ctrlKey || e.metaKey) {
          if (selectedTorrentId != null) {
            handleToggleSelect(selectedTorrentId);
          }
        } else {
          handleToggleActiveSelected();
        }
        return;
      }

      // p / P: pause / resume (supporting single & multi-selection)
      if (e.key === "p" || e.key === "P") {
        e.preventDefault();
        handleToggleActiveSelected();
        return;
      }

      // Ctrl + R / F5: force recheck selected torrent(s)
      if (
        ((e.ctrlKey || e.metaKey) && (e.key === "r" || e.key === "R")) ||
        e.key === "F5"
      ) {
        e.preventDefault();
        const ids =
          selectedIds.size > 0
            ? Array.from(selectedIds)
            : selectedTorrentId != null
              ? [selectedTorrentId]
              : [];
        ids.forEach((id) => recheckTorrent.mutate(id));
        return;
      }

      // F6 or a / A: force announce to all trackers
      if (
        e.key === "F6" ||
        (!e.ctrlKey && !e.metaKey && (e.key === "a" || e.key === "A"))
      ) {
        if (selectedTorrentId != null) {
          e.preventDefault();
          announceTorrent.mutate(selectedTorrentId);
          return;
        }
      }

      // Ctrl + T: open Bulk Tag modal
      if ((e.ctrlKey || e.metaKey) && (e.key === "t" || e.key === "T")) {
        e.preventDefault();
        setBulkTagModalState({ isOpen: true, mode: "add" });
        return;
      }

      // Delete / Backspace: delete torrent (supporting single & multi-selection)
      if (e.key === "Delete" || e.key === "Backspace") {
        e.preventDefault();
        handleBulkDelete();
        return;
      }
    }

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [
    toggleQuickControls,
    closeQuickControls,
    isQuickControlsOpen,
    selectedTorrentId,
    setSelectedTorrentId,
    selectedIds,
    setSelectedIds,
    filteredTorrents,
    announceTorrent,
    recheckTorrent,
    handleToggleActiveSelected,
    handleBulkDelete,
    handleSelectAll,
    handleSelectRange,
    setAnchorIndex,
    handleToggleSelect,
    handleBulkMoveQueue,
    modalCount,
    deleteModalState?.isOpen,
    showAddModal,
    bulkTagModalState?.isOpen,
    showImportPackageModal,
  ]);

  const count = torrents?.length ?? 0;

  return (
    <div className="torrent-index-page">
      <TorrentToolbar
        count={count}
        totalUploadSpeed={totalUploadSpeed}
        totalDownloadSpeed={totalDownloadSpeed}
        seedingConfig={seedingConfig}
        adjustSpeed={adjustSpeed}
        filter={filter}
        onFilterChange={setFilter}
        viewMode={viewMode}
        onViewModeChange={handleViewMode}
        onAddTorrent={() => setShowAddModal(true)}
        onImportPackage={() => setShowImportPackageModal(true)}
        onSearchIndexers={() => navigate("/settings/indexers")}
        onStartAll={() => startAll.mutate()}
        onStopAll={() => stopAll.mutate()}
        selectedCount={selectedIds.size}
        bulkPending={bulkPending}
        onBulkStart={handleBulkStart}
        onBulkStop={handleBulkStop}
        onBulkDelete={handleBulkDelete}
        onBulkClear={() => setSelectedIds(new Set())}
        onBulkAddTags={handleBulkAddTags}
        onBulkRemoveTags={handleBulkRemoveTags}
        onBulkMoveQueue={handleBulkMoveQueue}
        isFilterCollapsed={isFilterCollapsed}
        onToggleFilter={toggleFilterCollapse}
        isQuickControlsOpen={isQuickControlsOpen}
        onToggleQuickControls={toggleQuickControls}
        visibleColumns={visibleColumns}
        onToggleColumn={toggleColumn}
        onResetColumns={resetColumns}
        onResetSort={resetSort}
        onSelectAllColumns={selectAllColumns}
        onDeselectAllColumns={deselectAllColumns}
        onApplyColumnPreset={applyColumnPreset}
        onToggleCategoryColumns={toggleCategoryColumns}
      />
      <QuickSettingsDrawer
        isOpen={isQuickControlsOpen}
        onClose={closeQuickControls}
      />
      <div className="torrent-content-layout">
        <TorrentFilterPanel
          selectedState={selectedState}
          onSelectState={setSelectedState}
          selectedTracker={selectedTracker}
          onSelectTracker={setSelectedTracker}
          selectedCategory={selectedCategory}
          onSelectCategory={setSelectedCategory}
          selectedTag={selectedTag}
          onSelectTag={setSelectedTag}
          selectedTagIds={selectedTagIds}
          onToggleTag={toggleTag}
          tagMatchMode={tagMatchMode}
          onTagMatchModeChange={setTagMatchMode}
          onClearTags={clearTags}
          untaggedCount={untaggedCount}
          stateCounts={stateCounts}
          trackerGroups={trackerGroups}
          categoryGroups={categoryGroups}
          tagGroups={tagGroups}
          count={count}
          isCollapsed={isFilterCollapsed}
          onToggleCollapse={toggleFilterCollapse}
        />
        <div className="filter-content">
          <div className="torrent-split-pane">
            <div className="torrent-split-top">
              {viewMode === "table" ? (
                <TorrentTable
                  torrents={filteredTorrents}
                  filter={filter}
                  stateFilter={selectedState}
                  trackerFilter={selectedTracker}
                  categoryFilter={selectedCategory}
                  tagFilter={selectedTag}
                  selectedTagIds={selectedTagIds}
                  tagMatchMode={tagMatchMode}
                  selectedTorrentId={selectedTorrentId}
                  onSelectTorrent={setSelectedTorrentId}
                  selectedIds={selectedIds}
                  onToggleSelect={handleToggleSelect}
                  onSelectAll={handleSelectAll}
                  onSelectRange={handleSelectRange}
                  onSelectMultiple={setSelectedIds}
                  onDeleteSelected={handleBulkDelete}
                  onToggleActive={handleToggleActiveSelected}
                  onOpenBulkTag={() =>
                    setBulkTagModalState({ isOpen: true, mode: "add" })
                  }
                  visibleColumns={visibleColumns}
                  onToggleColumn={toggleColumn}
                  columnOrder={columnOrder}
                  onColumnOrderChange={setColumnOrder}
                  columnWidths={columnWidths}
                  onColumnWidthsChange={setColumnWidths}
                />
              ) : (
                <TorrentGrid
                  torrents={filteredTorrents}
                  filter={filter}
                  stateFilter={selectedState}
                  trackerFilter={selectedTracker}
                  categoryFilter={selectedCategory}
                  tagFilter={selectedTag}
                  selectedTagIds={selectedTagIds}
                  tagMatchMode={tagMatchMode}
                  selectedTorrentId={selectedTorrentId}
                  onSelectTorrent={setSelectedTorrentId}
                  selectedIds={selectedIds}
                  onToggleSelect={handleToggleSelect}
                  onSelectAll={() =>
                    handleSelectAll(filteredTorrents.map((t) => t.id))
                  }
                />
              )}
            </div>
            {selectedTorrentId != null && (
              <TorrentDetailPanel
                torrentId={selectedTorrentId}
                onClose={() => setSelectedTorrentId(null)}
              />
            )}
          </div>
        </div>
      </div>
      {showAddModal && (
        <AddTorrentModal onClose={() => setShowAddModal(false)} />
      )}
      {showImportPackageModal && (
        <ImportPackageModal
          isOpen={showImportPackageModal}
          onClose={() => setShowImportPackageModal(false)}
        />
      )}
      {deleteModalState?.isOpen && (
        <DeleteTorrentModal
          isOpen={deleteModalState.isOpen}
          count={deleteModalState.targetIds.length}
          torrentName={deleteModalState.torrentName}
          isPending={bulkPending}
          onClose={() => {
            if (!bulkPending) setDeleteModalState(null);
          }}
          onConfirm={handleConfirmBulkDelete}
        />
      )}
      {bulkTagModalState?.isOpen && (
        <BulkTagModal
          isOpen={bulkTagModalState.isOpen}
          mode={bulkTagModalState.mode}
          selectedCount={selectedIds.size}
          tags={tags ?? []}
          isPending={bulkPending}
          onClose={() => {
            if (!bulkPending) setBulkTagModalState(null);
          }}
          onConfirm={handleConfirmBulkTag}
        />
      )}
    </div>
  );
}

export default TorrentIndex;

import { useState, useMemo } from "react";
import {
  useTrackerMetrics,
  useTrackerMetricsSummary,
  useTrackerMetricHistory,
  useResetTrackerMetric,
  useDeleteTrackerMetric,
} from "../api/hooks";
import { formatBytes, formatDate } from "../utils/formatters";
import TrackerFavicon from "../components/TrackerFavicon";
import { useToast } from "../context/ToastContext";
import type {
  TrackerMetric,
  TrackerMetricSnapshot,
  HourlyTrafficPoint,
} from "../api/types";

type ProtocolFilter = "ALL" | "UDP" | "HTTP" | "HTTPS";
type StatusFilter = "ALL" | "Working" | "Degraded" | "Offline";
type SortField =
  | "upload"
  | "download"
  | "ratio"
  | "announces"
  | "successRate"
  | "latency"
  | "peers"
  | "domain"
  | "lastAnnounce";

export function TrackerMetrics() {
  const [isLive, setIsLive] = useState(true);
  const [protocolFilter, setProtocolFilter] = useState<ProtocolFilter>("ALL");
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("ALL");
  const [searchTerm, setSearchTerm] = useState("");
  const [sortField, setSortField] = useState<SortField>("upload");
  const [sortAsc, setSortAsc] = useState(false);
  const [selectedMetric, setSelectedMetric] = useState<TrackerMetric | null>(
    null,
  );

  const {
    data: metrics = [],
    isLoading: isLoadingMetrics,
    refetch: refetchMetrics,
  } = useTrackerMetrics(isLive ? 4000 : false);
  const {
    data: summary,
    isLoading: isLoadingSummary,
    refetch: refetchSummary,
  } = useTrackerMetricsSummary(isLive ? 4000 : false);

  const resetMetric = useResetTrackerMetric();
  const deleteMetric = useDeleteTrackerMetric();
  const { showToast } = useToast();

  const handleRefresh = () => {
    refetchMetrics();
    refetchSummary();
    showToast("Tracker metrics refreshed", "info");
  };

  const handleReset = (metric: TrackerMetric) => {
    if (
      confirm(
        `Reset all metrics history for ${metric.domain || metric.trackerUrl}?`,
      )
    ) {
      resetMetric.mutate(metric.id, {
        onSuccess: () =>
          showToast(
            `Reset stats for ${metric.domain || metric.host}`,
            "success",
          ),
        onError: (err) => showToast(`Failed to reset: ${err.message}`, "error"),
      });
    }
  };

  const handleDelete = (metric: TrackerMetric) => {
    if (
      confirm(`Delete tracking data for ${metric.domain || metric.trackerUrl}?`)
    ) {
      deleteMetric.mutate(metric.id, {
        onSuccess: () => {
          showToast(`Deleted ${metric.domain || metric.host}`, "success");
          if (selectedMetric?.id === metric.id) setSelectedMetric(null);
        },
        onError: (err) =>
          showToast(`Failed to delete: ${err.message}`, "error"),
      });
    }
  };

  // Filter and Sort
  const filteredMetrics = useMemo(() => {
    return metrics
      .filter((m) => {
        if (
          protocolFilter !== "ALL" &&
          (m.protocol || "").toUpperCase() !== protocolFilter
        ) {
          return false;
        }
        if (
          statusFilter !== "ALL" &&
          (m.status || "").toLowerCase() !== statusFilter.toLowerCase()
        ) {
          return false;
        }
        if (searchTerm) {
          const q = searchTerm.toLowerCase();
          const matchUrl = (m.trackerUrl || "").toLowerCase().includes(q);
          const matchDomain = (m.domain || "").toLowerCase().includes(q);
          const matchHost = (m.host || "").toLowerCase().includes(q);
          if (!matchUrl && !matchDomain && !matchHost) return false;
        }
        return true;
      })
      .sort((a, b) => {
        let cmp = 0;
        switch (sortField) {
          case "upload":
            cmp = a.totalUploaded - b.totalUploaded;
            break;
          case "download":
            cmp = a.totalDownloaded - b.totalDownloaded;
            break;
          case "ratio":
            cmp = a.ratio - b.ratio;
            break;
          case "announces":
            cmp = a.totalAnnounces - b.totalAnnounces;
            break;
          case "successRate":
            cmp = a.announceSuccessRate - b.announceSuccessRate;
            break;
          case "latency":
            cmp = a.avgResponseTimeMs - b.avgResponseTimeMs;
            break;
          case "peers":
            cmp = a.totalPeersDiscovered - b.totalPeersDiscovered;
            break;
          case "domain":
            cmp = (a.domain || "").localeCompare(b.domain || "");
            break;
          case "lastAnnounce":
            cmp =
              new Date(a.lastAnnounce || 0).getTime() -
              new Date(b.lastAnnounce || 0).getTime();
            break;
          default:
            cmp = a.totalUploaded - b.totalUploaded;
        }
        return sortAsc ? cmp : -cmp;
      });
  }, [metrics, protocolFilter, statusFilter, searchTerm, sortField, sortAsc]);

  const summaryMaxUpload = useMemo(() => {
    return Math.max(
      ...(summary?.topUploadTrackers ?? []).map((t) => t.totalUploaded || 0),
      1,
    );
  }, [summary?.topUploadTrackers]);

  return (
    <div
      className="content-area"
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "1.25rem",
        padding: "1.5rem",
        paddingBottom: "3rem",
      }}
    >
      {/* Header Banner */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: "1rem",
          marginBottom: "1.5rem",
        }}
      >
        <div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "0.75rem",
              flexWrap: "wrap",
            }}
          >
            <h1
              style={{
                fontSize: "1.75rem",
                fontWeight: 700,
                margin: 0,
                display: "flex",
                alignItems: "center",
                gap: "0.5rem",
              }}
            >
              <span>📡</span> Tracker Metrics
            </h1>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "0.3rem",
                fontSize: "0.75rem",
                fontWeight: 600,
                padding: "0.2rem 0.55rem",
                borderRadius: "12px",
                backgroundColor: isLive
                  ? "rgba(34, 197, 94, 0.15)"
                  : "rgba(148, 163, 184, 0.15)",
                color: isLive ? "#4ade80" : "#94a3b8",
                border: `1px solid ${isLive ? "rgba(34, 197, 94, 0.3)" : "rgba(148, 163, 184, 0.3)"}`,
              }}
            >
              <span
                style={{
                  width: "6px",
                  height: "6px",
                  borderRadius: "50%",
                  backgroundColor: isLive ? "#22c55e" : "#94a3b8",
                  boxShadow: isLive ? "0 0 6px #22c55e" : "none",
                }}
              />
              {isLive ? "Live Telemetry" : "Paused"}
            </span>
          </div>
          <p
            style={{
              color: "var(--text-muted, #888)",
              margin: "0.25rem 0 0 0",
              fontSize: "0.9rem",
            }}
          >
            Telemetry, traffic statistics, scrape responses, and latency metrics
            for all interacted trackers
          </p>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem" }}>
          <button
            className={`btn btn-sm ${isLive ? "btn-outline" : "btn-primary"}`}
            onClick={() => setIsLive(!isLive)}
            title={isLive ? "Pause auto-updates" : "Resume live telemetry"}
          >
            {isLive ? "⏸ Pause" : "▶ Resume"}
          </button>
          <button
            className="btn btn-outline btn-sm"
            onClick={handleRefresh}
            title="Refresh metrics"
          >
            🔄 Refresh
          </button>
        </div>
      </div>

      {/* KPI Cards Grid */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
          gap: "0.85rem",
        }}
      >
        {/* Total Uploaded */}
        <div
          className="card"
          style={{
            padding: "1.1rem",
            borderRadius: "8px",
            position: "relative",
            overflow: "hidden",
          }}
        >
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-secondary)",
              fontWeight: 600,
              textTransform: "uppercase",
            }}
          >
            Total Upload Reported
          </div>
          <div
            style={{
              fontSize: "1.65rem",
              fontWeight: 700,
              color: "#4ade80",
              marginTop: "0.3rem",
            }}
          >
            {formatBytes(summary?.totalUploaded ?? 0)}
          </div>
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-muted)",
              marginTop: "0.25rem",
            }}
          >
            Across {summary?.totalTrackers ?? 0} swarms
          </div>
        </div>

        {/* Total Downloaded */}
        <div
          className="card"
          style={{ padding: "1.1rem", borderRadius: "8px" }}
        >
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-secondary)",
              fontWeight: 600,
              textTransform: "uppercase",
            }}
          >
            Total Download Reported
          </div>
          <div
            style={{
              fontSize: "1.65rem",
              fontWeight: 700,
              color: "#60a5fa",
              marginTop: "0.3rem",
            }}
          >
            {formatBytes(summary?.totalDownloaded ?? 0)}
          </div>
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-muted)",
              marginTop: "0.25rem",
            }}
          >
            Global Ratio:{" "}
            <strong style={{ color: "#fbbf24" }}>
              {summary?.globalRatio ?? 0}x
            </strong>
          </div>
        </div>

        {/* Success Rate */}
        <div
          className="card"
          style={{ padding: "1.1rem", borderRadius: "8px" }}
        >
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-secondary)",
              fontWeight: 600,
              textTransform: "uppercase",
            }}
          >
            Announce Success Rate
          </div>
          <div
            style={{
              fontSize: "1.65rem",
              fontWeight: 700,
              color: "#22c55e",
              marginTop: "0.3rem",
            }}
          >
            {summary?.announceSuccessRate ?? 100}%
          </div>
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-muted)",
              marginTop: "0.25rem",
            }}
          >
            {summary?.successfulAnnounces?.toLocaleString() ?? 0} ok /{" "}
            {summary?.failedAnnounces ?? 0} fail
          </div>
        </div>

        {/* Avg Response Time */}
        <div
          className="card"
          style={{ padding: "1.1rem", borderRadius: "8px" }}
        >
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-secondary)",
              fontWeight: 600,
              textTransform: "uppercase",
            }}
          >
            Avg Response Latency
          </div>
          <div
            style={{
              fontSize: "1.65rem",
              fontWeight: 700,
              color: "#e2e8f0",
              marginTop: "0.3rem",
            }}
          >
            {Math.round(summary?.avgResponseTimeMs ?? 0)}{" "}
            <span style={{ fontSize: "1rem", fontWeight: 400 }}>ms</span>
          </div>
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-muted)",
              marginTop: "0.25rem",
            }}
          >
            Round-trip UDP/HTTP
          </div>
        </div>

        {/* Trackers Health Breakdown */}
        <div
          className="card"
          style={{ padding: "1.1rem", borderRadius: "8px" }}
        >
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-secondary)",
              fontWeight: 600,
              textTransform: "uppercase",
            }}
          >
            Active Tracker Swarms
          </div>
          <div
            style={{
              fontSize: "1.65rem",
              fontWeight: 700,
              marginTop: "0.3rem",
            }}
          >
            {summary?.totalTrackers ?? 0}
          </div>
          <div
            style={{
              display: "flex",
              gap: "0.5rem",
              marginTop: "0.25rem",
              fontSize: "0.76rem",
            }}
          >
            <span style={{ color: "#4ade80" }}>
              ● {summary?.healthyTrackers ?? 0} ok
            </span>
            <span style={{ color: "#fbbf24" }}>
              ● {summary?.degradedTrackers ?? 0} slow
            </span>
            <span style={{ color: "#f87171" }}>
              ● {summary?.offlineTrackers ?? 0} down
            </span>
          </div>
        </div>

        {/* Peers Discovered */}
        <div
          className="card"
          style={{ padding: "1.1rem", borderRadius: "8px" }}
        >
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-secondary)",
              fontWeight: 600,
              textTransform: "uppercase",
            }}
          >
            Total Peers Discovered
          </div>
          <div
            style={{
              fontSize: "1.65rem",
              fontWeight: 700,
              color: "#c084fc",
              marginTop: "0.3rem",
            }}
          >
            {(summary?.totalPeersDiscovered ?? 0).toLocaleString()}
          </div>
          <div
            style={{
              fontSize: "0.78rem",
              color: "var(--text-muted)",
              marginTop: "0.25rem",
            }}
          >
            Candidates harvested
          </div>
        </div>
      </div>

      {/* Visual Charts & Diagrams Section */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(360px, 1fr))",
          gap: "1rem",
        }}
      >
        {/* Chart 1: 24h Hourly Activity Timeline */}
        <div
          className="card"
          style={{
            padding: "1.25rem",
            borderRadius: "8px",
            display: "flex",
            flexDirection: "column",
            gap: "0.75rem",
          }}
        >
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <h3
              style={{
                margin: 0,
                fontSize: "0.98rem",
                display: "flex",
                alignItems: "center",
                gap: "0.4rem",
              }}
            >
              <span>📈</span> 24-Hour Announce & Traffic Activity
            </h3>
            <span style={{ fontSize: "0.75rem", color: "var(--text-muted)" }}>
              Last 24 Hours
            </span>
          </div>

          <div
            style={{
              height: "180px",
              width: "100%",
              position: "relative",
              marginTop: "0.5rem",
            }}
          >
            <HourlyActivitySvgChart data={summary?.hourlyHistory ?? []} />
          </div>

          <div
            style={{
              display: "flex",
              justifyContent: "center",
              gap: "1.25rem",
              fontSize: "0.75rem",
              color: "var(--text-secondary)",
            }}
          >
            <span
              style={{ display: "flex", alignItems: "center", gap: "0.35rem" }}
              title="Upload volume across 24 hours (traffic scale)"
            >
              <span
                style={{
                  width: "10px",
                  height: "10px",
                  backgroundColor: "#4ade80",
                  borderRadius: "2px",
                }}
              />
              Upload Volume
            </span>
            <span
              style={{ display: "flex", alignItems: "center", gap: "0.35rem" }}
              title="Download volume across 24 hours (traffic scale)"
            >
              <span
                style={{
                  width: "10px",
                  height: "10px",
                  backgroundColor: "#60a5fa",
                  borderRadius: "2px",
                }}
              />
              Download Volume
            </span>
            <span
              style={{ display: "flex", alignItems: "center", gap: "0.35rem" }}
              title="Announce count scaled independently on secondary scale"
            >
              <span
                style={{
                  width: "10px",
                  height: "10px",
                  backgroundColor: "#f59e0b",
                  borderRadius: "2px",
                }}
              />
              Announce Count (Secondary Scale)
            </span>
          </div>
        </div>

        {/* Chart 2: Top Upload Trackers & Protocols Breakdown */}
        <div
          className="card"
          style={{
            padding: "1.25rem",
            borderRadius: "8px",
            display: "flex",
            flexDirection: "column",
            gap: "0.75rem",
          }}
        >
          <h3
            style={{
              margin: 0,
              fontSize: "0.98rem",
              display: "flex",
              alignItems: "center",
              gap: "0.4rem",
            }}
          >
            <span>🏆</span> Top Swarms by Upload Traffic
          </h3>

          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "0.6rem",
              flex: 1,
              justifyContent: "center",
            }}
          >
            {(summary?.topUploadTrackers ?? []).length === 0 ? (
              <div
                style={{
                  textAlign: "center",
                  color: "var(--text-muted)",
                  fontSize: "0.85rem",
                  padding: "2rem",
                }}
              >
                No tracker traffic recorded yet
              </div>
            ) : (
              (summary?.topUploadTrackers ?? []).map((t, idx) => {
                const pct =
                  summaryMaxUpload > 0
                    ? (t.totalUploaded / summaryMaxUpload) * 100
                    : 0;
                return (
                  <div
                    key={t.id || idx}
                    style={{
                      display: "flex",
                      flexDirection: "column",
                      gap: "0.2rem",
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        fontSize: "0.8rem",
                      }}
                    >
                      <span
                        style={{
                          fontWeight: 600,
                          display: "flex",
                          alignItems: "center",
                          gap: "0.35rem",
                        }}
                      >
                        <TrackerFavicon urlOrHost={t.trackerUrl} size={14} />
                        {t.domain || t.trackerUrl}
                        <span
                          style={{
                            fontSize: "0.65rem",
                            padding: "0.05rem 0.35rem",
                            borderRadius: "3px",
                            backgroundColor: "rgba(255,255,255,0.08)",
                            color: "var(--text-muted)",
                          }}
                        >
                          {(t.protocol || "http").toUpperCase()}
                        </span>
                      </span>
                      <span style={{ fontWeight: 600, color: "#4ade80" }}>
                        {formatBytes(t.totalUploaded)}
                      </span>
                    </div>
                    {/* Progress visual bar */}
                    <div
                      style={{
                        height: "6px",
                        width: "100%",
                        backgroundColor: "rgba(255,255,255,0.06)",
                        borderRadius: "3px",
                        overflow: "hidden",
                      }}
                    >
                      <div
                        style={{
                          height: "100%",
                          width: `${Math.max(4, Math.min(100, pct))}%`,
                          backgroundColor:
                            idx === 0
                              ? "#22c55e"
                              : idx === 1
                                ? "#3b82f6"
                                : idx === 2
                                  ? "#a855f7"
                                  : "#eab308",
                          borderRadius: "3px",
                        }}
                      />
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>

      {/* Main Trackers Table Section */}
      <div
        className="card"
        style={{
          padding: "1.25rem",
          borderRadius: "8px",
          display: "flex",
          flexDirection: "column",
          gap: "0.85rem",
        }}
      >
        {/* Controls, Filters & Search Bar */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            flexWrap: "wrap",
            gap: "0.75rem",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "0.5rem",
              flex: "1 1 240px",
              minWidth: "200px",
            }}
          >
            <input
              type="text"
              className="form-control"
              placeholder="Search tracker domains, URLs, hosts..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              style={{
                width: "100%",
                padding: "0.35rem 0.65rem",
                fontSize: "0.82rem",
                backgroundColor: "var(--bg-primary)",
                borderRadius: "6px",
              }}
            />
          </div>

          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "0.75rem",
              flexWrap: "wrap",
            }}
          >
            {/* Protocol Filter */}
            <div
              style={{ display: "flex", alignItems: "center", gap: "0.25rem" }}
            >
              <span style={{ fontSize: "0.75rem", color: "var(--text-dim)" }}>
                Protocol:
              </span>
              {(["ALL", "UDP", "HTTP", "HTTPS"] as ProtocolFilter[]).map(
                (p) => (
                  <button
                    key={p}
                    className={`btn btn-xs ${protocolFilter === p ? "btn-primary" : "btn-outline"}`}
                    style={{ fontSize: "0.72rem", padding: "0.18rem 0.45rem" }}
                    onClick={() => setProtocolFilter(p)}
                  >
                    {p}
                  </button>
                ),
              )}
            </div>

            {/* Status Filter */}
            <div
              style={{ display: "flex", alignItems: "center", gap: "0.25rem" }}
            >
              <span style={{ fontSize: "0.75rem", color: "var(--text-dim)" }}>
                Status:
              </span>
              {(
                ["ALL", "Working", "Degraded", "Offline"] as StatusFilter[]
              ).map((s) => (
                <button
                  key={s}
                  className={`btn btn-xs ${statusFilter === s ? "btn-primary" : "btn-outline"}`}
                  style={{ fontSize: "0.72rem", padding: "0.18rem 0.45rem" }}
                  onClick={() => setStatusFilter(s)}
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* Results summary count */}
        <div style={{ fontSize: "0.78rem", color: "var(--text-muted)" }}>
          Showing {filteredMetrics.length} of {metrics.length} tracked tracker
          servers
        </div>

        {/* Interactive Data Table */}
        <div
          className="torrent-table-wrapper"
          style={{
            overflowX: "auto",
            borderRadius: "6px",
            border: "1px solid var(--border-light)",
          }}
        >
          <table
            className="torrent-table"
            style={{
              fontSize: "0.8rem",
              width: "100%",
              borderCollapse: "collapse",
            }}
          >
            <thead>
              <tr
                style={{
                  backgroundColor: "#161b22",
                  borderBottom: "1px solid var(--border-light)",
                }}
              >
                <th
                  className="torrent-table-th"
                  style={{ cursor: "pointer", padding: "0.5rem 0.65rem" }}
                  onClick={() => {
                    if (sortField === "domain") setSortAsc(!sortAsc);
                    else {
                      setSortField("domain");
                      setSortAsc(true);
                    }
                  }}
                >
                  Tracker Domain / Host{" "}
                  {sortField === "domain" && (sortAsc ? "▲" : "▼")}
                </th>
                <th
                  className="torrent-table-th"
                  style={{ width: "90px", padding: "0.5rem 0.65rem" }}
                >
                  Status
                </th>
                <th
                  className="torrent-table-th"
                  style={{
                    cursor: "pointer",
                    padding: "0.5rem 0.65rem",
                    textAlign: "right",
                  }}
                  onClick={() => {
                    if (sortField === "upload") setSortAsc(!sortAsc);
                    else {
                      setSortField("upload");
                      setSortAsc(false);
                    }
                  }}
                >
                  Uploaded {sortField === "upload" && (sortAsc ? "▲" : "▼")}
                </th>
                <th
                  className="torrent-table-th"
                  style={{
                    cursor: "pointer",
                    padding: "0.5rem 0.65rem",
                    textAlign: "right",
                  }}
                  onClick={() => {
                    if (sortField === "download") setSortAsc(!sortAsc);
                    else {
                      setSortField("download");
                      setSortAsc(false);
