              border: "1px dashed var(--border-light)",
            }}
          >
            <div style={{ fontSize: "2rem", marginBottom: "0.5rem" }}>🏷️</div>
            <h4 style={{ margin: "0 0 0.5rem", color: "var(--text-primary)" }}>
