              </tbody>
            </table>
          </div>
        )}
      </SectionCard>

      {/* Add / Edit Category Modal */}
      {editingCategory && (
        <div className="modal-overlay" onClick={() => setEditingCategory(null)}>
          <div
            ref={editingCategoryTrapRef}
            className="modal"
            onClick={(e) => e.stopPropagation()}
            style={{
              maxWidth: 540,
              borderRadius: "8px",
              boxShadow: "0 16px 40px rgba(0,0,0,0.7)",
              border: "1px solid var(--border-light)",
            }}
          >
            <div
              className="modal-title"
              style={{
                fontSize: "1.2rem",
                marginBottom: "1rem",
                fontWeight: 600,
                color: "var(--text-primary)",
              }}
            >
              {editingCategory.id
                ? `Edit Category: ${editingCategory.name}`
                : "Add New Category"}
            </div>

            <TextInput
              label="Name"
              value={editingCategory.name || ""}
              onChange={(v) => {
                setEditingCategory({ ...editingCategory, name: v });
                setModalError(null);
              }}
              placeholder="e.g. movies, tv, music"
              hint="Unique name for this category"
            />

            <div style={{ marginBottom: "1rem" }}>
              <label
                style={{
                  display: "block",
                  fontSize: "0.85rem",
                  fontWeight: 500,
                  marginBottom: "0.35rem",
                  color: "var(--text-secondary)",
                }}
              >
                Save Path
              </label>
              <div style={{ display: "flex", gap: "0.5rem" }}>
                <input
                  type="text"
                  className="input"
                  value={editingCategory.savePath || ""}
                  onChange={(e) =>
                    setEditingCategory({
                      ...editingCategory,
                      savePath: e.target.value,
                    })
                  }
                  placeholder="/downloads/movies"
                  style={{
                    flex: 1,
                    padding: "0.5rem 0.75rem",
                    borderRadius: "6px",
                    border: "1px solid var(--border-light)",
                    backgroundColor: "var(--bg-primary, #0f111c)",
                    color: "var(--text-primary, #fff)",
                    fontSize: "0.85rem",
                  }}
                />
                <button
                  type="button"
                  className="btn btn-outline btn-small"
                  onClick={() => handleOpenBrowser(editingCategory.savePath)}
                  title="Browse folders / select directory"
                  style={{
                    display: "inline-flex",
                    alignItems: "center",
                    gap: "0.35rem",
                    padding: "0.4rem 0.75rem",
                    whiteSpace: "nowrap",
                  }}
                >
                  📁 Browse...
                </button>
              </div>

              {/* Disk Space Preview Badge */}
              <div style={{ marginTop: "0.4rem" }}>
                <DiskSpaceBadge disk={currentMatchingDisk} />
              </div>
              <div
                style={{
                  fontSize: "0.75rem",
                  color: "var(--text-muted)",
                  marginTop: "0.25rem",
                }}
              >
                Custom download directory for torrents assigned to this category
                (optional)
              </div>
            </div>

            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
                gap: "1rem",
              }}
            >
              <NumberInput
                label="Max Download Speed"
                value={editingCategory.defaultDownloadLimit ?? 0}
                onChange={(v) =>
                  setEditingCategory({
                    ...editingCategory,
                    defaultDownloadLimit: v,
                  })
                }
                min={0}
                suffix="KB/s"
                hint="0 for unlimited"
              />

              <NumberInput
                label="Max Upload Speed"
                value={editingCategory.defaultUploadLimit ?? 0}
                onChange={(v) =>
                  setEditingCategory({
                    ...editingCategory,
                    defaultUploadLimit: v,
                  })
                }
                min={0}
                suffix="KB/s"
                hint="0 for unlimited"
              />
            </div>

            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
                gap: "1rem",
              }}
            >
              <NumberInput
                label="Max Active Downloads"
                value={editingCategory.maxActiveDownloads ?? 0}
                onChange={(v) =>
                  setEditingCategory({
                    ...editingCategory,
                    maxActiveDownloads: v > 0 ? v : null,
                  })
                }
                min={0}
                hint="0 for unlimited concurrent downloads"
              />

              <NumberInput
                label="Max Active Uploads"
                value={editingCategory.maxActiveUploads ?? 0}
                onChange={(v) =>
                  setEditingCategory({
                    ...editingCategory,
                    maxActiveUploads: v > 0 ? v : null,
                  })
                }
                min={0}
                hint="0 for unlimited concurrent uploads"
              />
            </div>

            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
                gap: "1rem",
              }}
            >
              <NumberInput
                label="Reserved Download Slots"
                value={editingCategory.reservedDownloadSlots ?? 0}
                onChange={(v) =>
                  setEditingCategory({
                    ...editingCategory,
                    reservedDownloadSlots: v,
                  })
                }
                min={0}
                hint="Dedicated download slots reserved for this category"
              />
            </div>

            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
                gap: "1rem",
              }}
            >
              <NumberInput
                label="Target Ratio"
                value={editingCategory.targetRatio ?? 0}
                onChange={(v) =>
                  setEditingCategory({ ...editingCategory, targetRatio: v })
                }
                min={0}
                step={0.1}
                hint="Ratio goal before marking done (0 for none)"
              />

              <NumberInput
                label="Target Seeding Time"
                value={editingCategory.targetSeedTimeMinutes ?? 0}
                onChange={(v) =>
                  setEditingCategory({
                    ...editingCategory,
                    targetSeedTimeMinutes: v,
                  })
                }
                min={0}
                suffix="min"
                hint="0 for unlimited"
              />
            </div>

            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: "0.75rem",
                marginTop: "0.5rem",
              }}
            >
              <Toggle
                label="Auto Stop When Goal Reached"
                checked={editingCategory.autoStop ?? false}
                onChange={(v) =>
                  setEditingCategory({ ...editingCategory, autoStop: v })
                }
                hint="Automatically pause/stop torrent once target ratio or seed time is met"
              />

              <Toggle
                label="Default Category"
                checked={editingCategory.isDefault ?? false}
                onChange={(v) =>
                  setEditingCategory({ ...editingCategory, isDefault: v })
                }
                hint="Automatically assign this category to newly added torrents without an explicit category"
              />
            </div>

            {modalError && (
              <div
                style={{
                  marginTop: "1rem",
                  padding: "0.6rem 0.8rem",
                  borderRadius: "6px",
                  fontSize: "0.85rem",
                  lineHeight: "1.4",
                  backgroundColor: "rgba(220, 53, 69, 0.15)",
                  color: "var(--danger, #dc3545)",
                  border: "1px solid rgba(220, 53, 69, 0.35)",
                }}
              >
                ✕ {modalError}
              </div>
            )}

            <div
              style={{
                display: "flex",
                justifyContent: "flex-end",
                gap: "0.5rem",
                marginTop: "1.5rem",
              }}
            >
              <button
                type="button"
                className="btn btn-outline btn-small"
                onClick={() => setEditingCategory(null)}
                disabled={isSaving}
              >
                Cancel
              </button>
              <button
                type="button"
                className="btn btn-primary btn-small"
                onClick={handleSave}
                disabled={isSaving}
              >
                {isSaving
                  ? "Saving..."
                  : editingCategory.id
                    ? "Save Changes"
                    : "Create Category"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Folder Browser Modal */}
      <FolderBrowserModal
        isOpen={showFolderBrowser}
        initialPath={browsingPath}
        title="Select Category Folder"
        onSelect={handleSelectBrowserPath}
        onClose={() => setShowFolderBrowser(false)}
      />
    </div>
  );
}

export const CategorySettings = CategorySettingsTab;
export default CategorySettingsTab;

import { useState, useEffect } from "react";
import { useNavigate } from "react-router";
import { useGeneralConfig, useSaveGeneralConfig } from "../../api/hooks";
import { apiClient } from "../../api/client";
import { useToast } from "../../context/ToastContext";
import { useTheme, type Theme, type Accent } from "../../context/ThemeContext";
import type {
  GeneralConfig,
  SslCertificateValidationResult,
} from "../../api/types";
import {
  SaveBar,
  Toggle,
  SelectInput,
  TextInput,
  NumberInput,
  SectionCard,
} from "./shared";
import {
  isTelemetryEnabled,
  setTelemetryEnabled,
  trackSettingSave,
} from "../../utils/analytics";

export function GeneralTab() {
  const { data: config, isLoading } = useGeneralConfig();
  const save = useSaveGeneralConfig();
  const navigate = useNavigate();
  const { showToast } = useToast();
  const { setTheme, setAccent } = useTheme();
  const [form, setForm] = useState<GeneralConfig>({
    id: 1,
    autoStart: false,
    themeStyle: "system",
    colorScheme: "auto",
    watchFolderEnabled: false,
    watchFolderPath: "",
    watchFolderScanIntervalSeconds: 10,
    watchFolderAutoStartTorrents: true,
    watchFolderDeleteAddedTorrents: false,
    port: 9898,
    bindAddress: "0.0.0.0",
    urlBase: "",
    authenticationEnabled: false,
    apiKey: "",
    enableSsl: false,
    sslPort: 9899,
    sslCertPath: "",
    sslKeyPath: "",
    sslCertPassword: "",
    redirectHttpToHttps: false,
    tmdbApiKey: "",
  });
  const [dirty, setDirty] = useState(false);
  const [showApiKey, setShowApiKey] = useState(false);
  const [revealedApiKey, setRevealedApiKey] = useState<string | null>(null);
  const [loadingApiKey, setLoadingApiKey] = useState(false);
  const [copied, setCopied] = useState(false);
  const [testingSsl, setTestingSsl] = useState(false);
  const [sslTestResult, setSslTestResult] =
    useState<SslCertificateValidationResult | null>(null);
  const [telemetryEnabled, setTelemetryEnabledState] = useState(() =>
    isTelemetryEnabled(),
  );

  useEffect(() => {
    if (config) {
      setForm({
        ...config,
        colorScheme:
          config.colorScheme === "green"
            ? "emerald"
            : config.colorScheme || "auto",
        enableSsl: config.enableSsl ?? false,
        sslPort: config.sslPort ?? 9899,
        sslCertPath: config.sslCertPath ?? "",
        sslKeyPath: config.sslKeyPath ?? "",
        sslCertPassword: config.sslCertPassword ?? "",
        redirectHttpToHttps: config.redirectHttpToHttps ?? false,
        tmdbApiKey: config.tmdbApiKey ?? "",
      });
      setDirty(false);
      setRevealedApiKey(null);
      setShowApiKey(false);
    }
  }, [config]);

  const set = <K extends keyof GeneralConfig>(
    key: K,
    value: GeneralConfig[K],
  ) => {
    setForm((prev) => ({ ...prev, [key]: value }));
    setDirty(true);
  };

  const handleToggleShowApiKey = async () => {
    if (showApiKey) {
      setShowApiKey(false);
      return;
    }
    if (revealedApiKey || !form.apiKey.includes("*")) {
      setShowApiKey(true);
      return;
    }
    try {
      setLoadingApiKey(true);
      const res = await apiClient.getApiKey();
      if (res?.apiKey) {
        setRevealedApiKey(res.apiKey);
        setShowApiKey(true);
      }
    } catch (_err) {
      showToast("Failed to retrieve unmasked API key", "error");
    } finally {
      setLoadingApiKey(false);
    }
  };

  const handleCopyApiKey = async () => {
    try {
      let keyToCopy = form.apiKey;
      if (revealedApiKey && form.apiKey.includes("*")) {
        keyToCopy = revealedApiKey;
      } else if (!keyToCopy || keyToCopy.includes("*")) {
        const res = await apiClient.getApiKey();
        keyToCopy = res.apiKey;
        setRevealedApiKey(res.apiKey);
      }
      if (!keyToCopy) {
        showToast("No API key available", "error");
        return;
      }
      await navigator.clipboard.writeText(keyToCopy);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
      showToast("API key copied to clipboard", "success");
    } catch (_err) {
      showToast("Failed to copy API key", "error");
    }
  };

  const generateApiKey = () => {
    const bytes = new Uint8Array(16);
    window.crypto.getRandomValues(bytes);
    const key = Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join(
      "",
    );
    setRevealedApiKey(key);
    setShowApiKey(true);
    set("apiKey", key);
  };

  const handleTestSsl = async () => {
    setTestingSsl(true);
    setSslTestResult(null);
    try {
      const res = await apiClient.testSsl({
        enableSsl: form.enableSsl ?? false,
        sslPort: form.sslPort ?? 9899,
        sslCertPath: form.sslCertPath,
        sslKeyPath: form.sslKeyPath,
        sslCertPassword: form.sslCertPassword,
        bindAddress: form.bindAddress,
      });
      setSslTestResult(res);
    } catch (err) {
      setSslTestResult({
        isValid: false,
        subject: "",
        issuer: "",
        validFrom: "",
        validTo: "",
        thumbprint: "",
        hasPrivateKey: false,
        subjectAlternativeNames: [],
        handshakeSucceeded: false,
        message:
          err instanceof Error
            ? err.message
            : "SSL test failed to execute against the server endpoint.",
      });
    } finally {
      setTestingSsl(false);
    }
  };

  if (isLoading) return <div className="loading">Loading configuration...</div>;

  return (
    <div>
      <SaveBar
        dirty={dirty}
        isPending={save.isPending}
        isError={save.isError}
        isSuccess={save.isSuccess}
        error={save.error}
        onSave={() =>
          save.mutate(
            {
              ...form,
              colorScheme:
                form.colorScheme === "green" ? "emerald" : form.colorScheme,
              uiTheme: form.themeStyle,
              uiAccent:
                form.colorScheme === "green" ? "emerald" : form.colorScheme,
            },
            {
              onSuccess: () => {
                setDirty(false);
                trackSettingSave("general", {
                  autoStart: form.autoStart,
                  themeStyle: form.themeStyle,
                  colorScheme: form.colorScheme,
                  watchFolderEnabled: form.watchFolderEnabled,
                  authenticationEnabled: form.authenticationEnabled,
                  enableSsl: form.enableSsl,
                });
              },
            },
          )
        }
      />

      <SectionCard
        title="Application"
        description="Configure launch seeding, visual theme, and color schemes"
      >
        <Toggle
          label="Auto Start"
          checked={form.autoStart}
          onChange={(v) => set("autoStart", v)}
          hint="Start seeding all queued swarms immediately on launch"
        />
        <SelectInput
          label="Theme"
          value={form.themeStyle}
          onChange={(v) => {
            set("themeStyle", v);
            setTheme(v as Theme);
          }}
          options={[
            { value: "dark", label: "Dark (Warm Espresso)" },
            { value: "indigo", label: "Indigo (Deep Midnight)" },
            { value: "oled", label: "OLED (Pure Black)" },
            { value: "slate", label: "Slate (Cool Steel)" },
            { value: "light", label: "Light (Cream Parchment)" },
            { value: "system", label: "System (OS Preference)" },
          ]}
          hint="Overall application appearance theme"
        />
        <SelectInput
          label="Color Scheme"
          value={form.colorScheme === "green" ? "emerald" : form.colorScheme}
          onChange={(v) => {
            const nextAccent = v === "green" ? "emerald" : v;
            set("colorScheme", nextAccent);
            setAccent(nextAccent as Accent);
          }}
          options={[
            { value: "auto", label: "Auto / Brand Gold (Default)" },
            { value: "blue", label: "Electric Blue" },
            { value: "emerald", label: "Emerald Green" },
            { value: "purple", label: "Royal Purple" },
            { value: "rose", label: "Vibrant Rose" },
            { value: "cyan", label: "Cyan Sky" },
            { value: "amber", label: "Warm Amber" },
          ]}
          hint="Accent brand highlight palette"
        />
      </SectionCard>

      <SectionCard
        title="Host & Networking"
        description="Configure web UI port, listening address, reverse proxy URL base, and API authentication"
      >
        <NumberInput
          label="Port"
          value={form.port}
          onChange={(v) => set("port", v)}
          min={1}
          max={65535}
          hint="HTTP port for Seedarr Web UI and REST API"
        />
        <TextInput
          label="Bind Address"
          value={form.bindAddress}
          onChange={(v) => set("bindAddress", v)}
          placeholder="0.0.0.0"
          hint="Listening IP address (* or 0.0.0.0 for all interfaces, 127.0.0.1 for local only)"
        />
        <TextInput
          label="URL Base"
          value={form.urlBase}
          onChange={(v) => set("urlBase", v)}
          placeholder="/seedarr"
          hint="Subdirectory prefix for reverse proxy setups (e.g. /seedarr)"
        />
        <Toggle
          label="Authentication"
          checked={form.authenticationEnabled}
          onChange={(v) => set("authenticationEnabled", v)}
          hint="Require user login credentials for Web UI and API access"
        />
        <TextInput
          label="API Key (X-Api-Key)"
          type={showApiKey ? "text" : "password"}
          value={
            showApiKey
              ? revealedApiKey || (form.apiKey.includes("*") ? "" : form.apiKey)
              : revealedApiKey || form.apiKey
          }
          onChange={(v) => {
            setRevealedApiKey(null);
            set("apiKey", v);
          }}
          hint="Secret token for Arr apps (Radarr/Sonarr) and REST API access"
          rightElement={
            <button
              type="button"
              className="btn btn-outline"
              onClick={handleToggleShowApiKey}
              style={{
                whiteSpace: "nowrap",
                height: "36px",
                padding: "0 0.75rem",
              }}
              disabled={loadingApiKey}
              title={showApiKey ? "Hide API Key" : "Show unmasked API Key"}
            >
              {loadingApiKey ? "..." : showApiKey ? "🙈 Hide" : "👁️ Show"}
            </button>
          }
        />
        <div
          style={{
            display: "flex",
            gap: "0.5rem",
            marginTop: "-0.5rem",
            marginBottom: "1rem",
            flexWrap: "wrap",
          }}
        >
          <button
            type="button"
            className="btn btn-outline"
            onClick={handleCopyApiKey}
            style={{ whiteSpace: "nowrap" }}
          >
            📋 {copied ? "Copied!" : "Copy"}
          </button>
          <button
            type="button"
            className="btn btn-outline"
            onClick={generateApiKey}
            style={{ whiteSpace: "nowrap" }}
          >
            🔄 Regenerate
          </button>
          <button
            type="button"
            className="btn btn-primary"
            onClick={() => navigate("/system/api")}
            style={{ whiteSpace: "nowrap" }}
          >
            📖 API Docs (OpenAPI)
          </button>
        </div>
      </SectionCard>

      <SectionCard
        title="SSL & HTTPS Encryption"
        description="Configure TLS/SSL certificate encryption, dual-listener HTTPS port, and connection verification."
      >
        <div
          style={{ display: "flex", flexDirection: "column", gap: "1.25rem" }}
        >
          <Toggle
            label="Enable SSL (HTTPS)"
            checked={form.enableSsl ?? false}
            onChange={(v) => set("enableSsl", v)}
            hint="Activate secure HTTPS web server endpoint with TLS certificate encryption"
          />

          {form.enableSsl && (
            <>
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
                  gap: "1rem",
                }}
              >
                <NumberInput
                  label="SSL / HTTPS Port"
                  value={form.sslPort ?? 9899}
                  onChange={(v) => set("sslPort", v)}
                  min={1}
                  max={65535}
                  hint="Dedicated port for secure HTTPS traffic (default: 9899)"
                />

                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    paddingTop: "1.5rem",
                  }}
                >
                  <Toggle
                    label="Redirect HTTP to HTTPS"
                    checked={form.redirectHttpToHttps ?? false}
                    onChange={(v) => set("redirectHttpToHttps", v)}
                    hint="Automatically redirect plain HTTP requests to the HTTPS port"
                  />
                </div>
              </div>

              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
                  gap: "1rem",
                }}
              >
                <TextInput
                  label="Certificate Path (.pfx, .crt, .pem)"
                  value={form.sslCertPath ?? ""}
                  onChange={(v) => set("sslCertPath", v)}
                  hint="Path to PKCS#12 (.pfx/.p12) or PEM (.crt/.pem) certificate. Leave blank for auto-generated self-signed certificate."
                />

                <TextInput
                  label="Private Key Path (.key) (Optional for PEM)"
                  value={form.sslKeyPath ?? ""}
                  onChange={(v) => set("sslKeyPath", v)}
                  hint="Path to separate PEM private key (.key). Leave blank if key is bundled in certificate or PFX."
                />

                <TextInput
                  label="Certificate Password (Optional for PFX)"
                  value={form.sslCertPassword ?? ""}
                  onChange={(v) => set("sslCertPassword", v)}
                  type="password"
                  hint="Decryption passphrase if certificate file is password-protected"
                />
              </div>

              {/* Test Certificate Action & Live Verification Result */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "1rem",
                  flexWrap: "wrap",
                  paddingTop: "0.5rem",
                }}
              >
                <button
                  type="button"
                  className="btn btn-outline"
                  onClick={handleTestSsl}
                  disabled={testingSsl}
                  style={{ minWidth: "160px" }}
                >
                  {testingSsl
                    ? "Testing Certificate..."
                    : "🔒 Test SSL Connection"}
                </button>

                <span
                  style={{ fontSize: "0.82rem", color: "var(--text-muted)" }}
                >
                  Validates certificate cryptographic structure, private key,
                  SAN domains, and active HTTPS handshake.
                </span>
              </div>

              {sslTestResult && (
                <div
                  style={{
                    padding: "1rem 1.25rem",
                    borderRadius: "8px",
                    backgroundColor: sslTestResult.isValid
                      ? "rgba(46, 204, 113, 0.08)"
                      : "rgba(231, 76, 60, 0.08)",
                    border: sslTestResult.isValid
                      ? "1px solid rgba(46, 204, 113, 0.3)"
                      : "1px solid rgba(231, 76, 60, 0.3)",
                    display: "flex",
                    flexDirection: "column",
                    gap: "0.5rem",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "0.5rem",
                    }}
                  >
                    <span style={{ fontSize: "1.1rem" }}>
                      {sslTestResult.isValid ? "✓" : "⚠️"}
                    </span>
                    <strong
                      style={{
                        color: sslTestResult.isValid
                          ? "var(--success, #2ecc71)"
                          : "var(--danger, #e74c3c)",
                        fontSize: "0.95rem",
                      }}
                    >
                      {sslTestResult.isValid
                        ? "✓ SSL Certificate & Configuration Valid"
                        : "⚠️ SSL Certificate Validation Issue"}
                    </strong>
                  </div>

                  <p
                    style={{
                      margin: 0,
                      fontSize: "0.86rem",
                      color: "var(--text-primary)",
                    }}
                  >
                    {sslTestResult.message}
                  </p>

                  {sslTestResult.isValid && (
                    <div
                      style={{
                        display: "grid",
                        gridTemplateColumns:
                          "repeat(auto-fit, minmax(220px, 1fr))",
                        gap: "0.75rem",
                        marginTop: "0.5rem",
                        fontSize: "0.8rem",
                        color: "var(--text-secondary)",
                        backgroundColor: "rgba(0, 0, 0, 0.2)",
                        padding: "0.75rem 1rem",
                        borderRadius: "6px",
                      }}
                    >
                      <div>
                        <span
                          style={{
                            color: "var(--text-muted)",
                            display: "block",
                          }}
                        >
                          Subject
                        </span>
                        <span
                          style={{
                            color: "var(--text-primary)",
                            wordBreak: "break-all",
                          }}
                        >
                          {sslTestResult.subject || "N/A"}
                        </span>
                      </div>
                      <div>
                        <span
                          style={{
                            color: "var(--text-muted)",
                            display: "block",
                          }}
                        >
                          Issuer
                        </span>
                        <span
                          style={{
                            color: "var(--text-primary)",
                            wordBreak: "break-all",
                          }}
                        >
                          {sslTestResult.issuer || "N/A"}
                        </span>
                      </div>
                      <div>
                        <span
                          style={{
                            color: "var(--text-muted)",
                            display: "block",
                          }}
                        >
                          Valid Until
                        </span>
                        <span style={{ color: "var(--accent)" }}>
                          {sslTestResult.validTo
                            ? new Date(
                                sslTestResult.validTo,
                              ).toLocaleDateString()
                            : "N/A"}
                        </span>
                      </div>
                      <div>
                        <span
                          style={{
                            color: "var(--text-muted)",
                            display: "block",
                          }}
                        >
                          Private Key
                        </span>
                        <span
                          style={{
                            color: sslTestResult.hasPrivateKey
                              ? "var(--success, #2ecc71)"
                              : "var(--danger)",
                          }}
                        >
                          {sslTestResult.hasPrivateKey
                            ? "Present (Verified)"
                            : "Missing"}
                        </span>
                      </div>
                      {sslTestResult.subjectAlternativeNames?.length > 0 && (
                        <div style={{ gridColumn: "1 / -1" }}>
                          <span
                            style={{
                              color: "var(--text-muted)",
                              display: "block",
                              marginBottom: "0.25rem",
                            }}
                          >
                            Subject Alternative Names (SANs)
                          </span>
                          <div
                            style={{
                              display: "flex",
                              gap: "0.4rem",
                              flexWrap: "wrap",
                            }}
                          >
                            {sslTestResult.subjectAlternativeNames.map(
                              (san) => (
                                <span
                                  key={san}
                                  style={{
                                    padding: "0.15rem 0.45rem",
                                    borderRadius: "4px",
                                    backgroundColor:
                                      "rgba(255, 209, 102, 0.12)",
                                    color: "var(--accent)",
                                    fontSize: "0.75rem",
                                  }}
                                >
                                  {san}
                                </span>
                              ),
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )}

              <div
                style={{
                  padding: "0.75rem 1rem",
                  borderRadius: "6px",
                  backgroundColor: "rgba(255, 209, 102, 0.08)",
                  border: "1px solid rgba(255, 209, 102, 0.2)",
                  fontSize: "0.85rem",
                  color: "var(--text-secondary)",
                  lineHeight: "1.4",
                }}
              >
                <strong style={{ color: "var(--accent)" }}>
                  TLS Certificate Provisioning Note:
                </strong>{" "}
                When Certificate Path is left empty, Seedarr automatically
                generates, signs, and caches an internal 2048-bit RSA
                self-signed certificate in the application configuration
                directory. Web server port and SSL changes take effect upon
                restarting the application daemon or container.
              </div>
            </>
          )}
        </div>
      </SectionCard>

      <SectionCard
        title="Watch Folder Automation"
        description="Automatically scan local folders for newly added .torrent files"
      >
        <Toggle
          label="Enabled"
          checked={form.watchFolderEnabled}
          onChange={(v) => set("watchFolderEnabled", v)}
          hint="Auto-import .torrent files discovered in the watch folder"
        />
        <TextInput
          label="Path"
          value={form.watchFolderPath}
          onChange={(v) => set("watchFolderPath", v)}
          placeholder="/watch"
          disabled={!form.watchFolderEnabled}
          hint="Absolute filesystem path to monitor"
        />
        <NumberInput
          label="Scan Interval"
          value={form.watchFolderScanIntervalSeconds}
          onChange={(v) => set("watchFolderScanIntervalSeconds", v)}
          min={1}
          suffix="seconds"
          disabled={!form.watchFolderEnabled}
          hint="Frequency to scan for new incoming torrent files"
        />
        <Toggle
          label="Auto Start Torrents"
          checked={form.watchFolderAutoStartTorrents}
          onChange={(v) => set("watchFolderAutoStartTorrents", v)}
          hint="Begin seeding torrents immediately once imported from the watch folder"
        />
        <Toggle
          label="Delete After Adding"
          checked={form.watchFolderDeleteAddedTorrents}
          onChange={(v) => set("watchFolderDeleteAddedTorrents", v)}
          hint="Remove .torrent file from the watch directory after successful import"
        />
      </SectionCard>

      <SectionCard
        title="Metadata & Enrichment"
        description="Configure external metadata providers for standalone enrichment"
      >
        <TextInput
          label="TMDb API Key"
          value={form.tmdbApiKey ?? ""}
          onChange={(v) => set("tmdbApiKey", v)}
          placeholder="Leave empty for built-in default"
          hint="API key used to query The Movie Database (TMDb) for posters, backdrops, genres, and cast when Arr applications are not connected"
        />
      </SectionCard>

      <SectionCard
        title="Privacy & Telemetry"
        description="Configure anonymous usage statistics and diagnostics"
      >
        <Toggle
          label="Anonymous Usage Telemetry"
          checked={telemetryEnabled}
          onChange={(v) => {
            setTelemetryEnabled(v);
            setTelemetryEnabledState(v);
            showToast(
              v
                ? "Anonymous telemetry enabled"
                : "Anonymous telemetry disabled",
              "info",
            );
          }}
          hint="Send anonymous aggregate usage data and crash reports to help improve Seedarr. No torrent names, file paths, IP addresses, or personal credentials are ever collected."
        />
      </SectionCard>
    </div>
  );
}

import { useState, useMemo, useEffect } from "react";
import {
  useIndexers,
  useCreateIndexer,
  useUpdateIndexer,
  useDeleteIndexer,
  useTestIndexer,
  useTestDirectIndexer,
  useSyncProwlarrIndexers,
  useRssRules,
  useCreateRssRule,
  useUpdateRssRule,
  useDeleteRssRule,
  useSyncRss,
  useCategories,
  useDownloadClients,
  useTags,
  useRssGrabHistory,
  useClearRssGrabHistory,
  useIndexerCaps,
} from "../../api/hooks";
import type {
  IndexerDefinition,
  IndexerTestResult,
  RssRule,
  RssGrabHistory,
  TorznabCapabilities,
} from "../../api/types";
import { formatBytes, formatDate } from "../../utils/formatters";
import {
  TextInput,
  SelectInput,
  Toggle,
  NumberInput,
  SectionCard,
} from "./shared";
import { useToast } from "../../context/ToastContext";
import { trackIndexerAction } from "../../utils/analytics";

export function formatIndexerTestError(error: any): string {
  if (!error) return "Connection failed";
  if (typeof error === "string") return error;
  return (
    error?.response?.data?.message || error?.message || "Connection failed"
  );
}

export function IndexersTab() {
  const { showToast } = useToast();

  // Download clients
  const { data: downloadClients } = useDownloadClients();

  // Indexers
  const { data: indexers, isLoading } = useIndexers();
  const createMutation = useCreateIndexer();
  const updateMutation = useUpdateIndexer();
  const deleteMutation = useDeleteIndexer();
  const testMutation = useTestIndexer();
  const testDirectMutation = useTestDirectIndexer();
  const syncProwlarrMutation = useSyncProwlarrIndexers();
  const [editing, setEditing] = useState<Partial<IndexerDefinition> | null>(
    null,
  );
  const [testResults, setTestResults] = useState<
    Record<number, boolean | null>
  >({});
  const [testErrorMessages, setTestErrorMessages] = useState<
    Record<number, string>
  >({});
  const [modalTestResult, setModalTestResult] =
    useState<IndexerTestResult | null>(null);
  const [capsFilter, setCapsFilter] = useState<string>("");
  const { data: indexerCaps } = useIndexerCaps(editing?.id);
  const activeCaps =
    modalTestResult?.capabilities || editing?.capabilities || indexerCaps;

  // RSS Rules, Categories, Tags
  const { data: rssRules, isLoading: isRssRulesLoading } = useRssRules();
  const { data: categories } = useCategories();
  const { data: tags } = useTags();
  const createRuleMutation = useCreateRssRule();
  const updateRuleMutation = useUpdateRssRule();
  const deleteRuleMutation = useDeleteRssRule();
  const syncRssMutation = useSyncRss();
  const [editingRule, setEditingRule] = useState<Partial<RssRule> | null>(null);
  const [syncCooldownRemaining, setSyncCooldownRemaining] = useState<number>(0);
  const [historyStatusFilter, setHistoryStatusFilter] = useState<string>("all");
  const { data: grabHistory, isLoading: isGrabHistoryLoading } =
    useRssGrabHistory(undefined, historyStatusFilter);
  const clearGrabHistoryMutation = useClearRssGrabHistory();

  const defaultIndexer: Partial<IndexerDefinition> = {
    name: "Prowlarr",
    indexerType: "Prowlarr",
    url: "http://prowlarr:9696",
    apiKey: "",
    apiPath: "/api",
    enableRss: true,
    enableSearch: true,
    categories: "",
    downloadClientId: 0,
    tags: [],
    enable: true,
  };

  const defaultRssRule: Partial<RssRule> = {
    name: "New RSS Rule",
    isEnabled: true,
    mustContain: "",
    mustNotContain: "",
    minSeeders: 1,
    minSizeBytes: 0,
    maxSizeBytes: 0,
    maxAgeDays: 0,
    freeleechOnly: false,
    categoryId: 0,
    indexerIds: [],
    tags: [],
    priority: 0,
    allowedResolutions: [],
    allowedSources: [],
    allowedCodecs: [],
    savePath: "",
    sequentialDownload: false,
    initialStatus: "Queued",
  };

  const categoryOptions = useMemo(() => {
    const opts = [{ value: "0", label: "None / Default" }];
    if (categories) {
      categories.forEach((cat) => {
        opts.push({ value: cat.id.toString(), label: cat.name });
      });
    }
    return opts;
  }, [categories]);

  useEffect(() => {
    if (syncCooldownRemaining <= 0) return;
    const timer = setInterval(() => {
      setSyncCooldownRemaining((prev) => Math.max(0, prev - 1));
    }, 1000);
    return () => clearInterval(timer);
  }, [syncCooldownRemaining]);

  const handleSave = () => {
    if (!editing) return;
    const name = editing.name?.trim() || editing.indexerType || "Indexer";
    const payload = {
      ...editing,
      name,
      enable: editing.enable ?? true,
      implementation: `${editing.indexerType || "Prowlarr"}Indexer`,
      configContract: "IndexerDefinition",
    };
    if (editing.id) {
      updateMutation.mutate(payload as IndexerDefinition, {
        onSuccess: () => {
          trackIndexerAction("edit", payload.indexerType || "Prowlarr", true);
          setEditing(null);
          setModalTestResult(null);
          showToast(`Indexer "${payload.name}" updated`, "success");
        },
        onError: (err: any) => {
          trackIndexerAction("edit", payload.indexerType || "Prowlarr", false);
          showToast(err?.message || "Failed to update indexer", "error");
        },
      });
    } else {
      createMutation.mutate(payload, {
        onSuccess: () => {
          trackIndexerAction("add", payload.indexerType || "Prowlarr", true);
          setEditing(null);
          setModalTestResult(null);
          showToast(`Indexer "${payload.name}" created`, "success");
        },
        onError: (err: any) => {
          trackIndexerAction("add", payload.indexerType || "Prowlarr", false);
          showToast(err?.message || "Failed to create indexer", "error");
        },
      });
    }
  };

  const handleTest = (id: number) => {
    setTestResults((prev) => ({ ...prev, [id]: null }));
    setTestErrorMessages((prev) => {
      const next = { ...prev };
      delete next[id];
      return next;
    });
    testMutation.mutate(id, {
      onSuccess: (data) => {
        trackIndexerAction("test", "indexer", data.success);
        setTestResults((prev) => ({ ...prev, [id]: data.success }));
        if (data.success) {
          showToast("Indexer connection successful", "success");
        } else {
          const message = data.message || "Connection failed";
          setTestErrorMessages((prev) => ({ ...prev, [id]: message }));
          showToast(`Indexer connection failed: ${message}`, "error");
        }
      },
      onError: (err: any) => {
        trackIndexerAction("test", "indexer", false);
        const message = formatIndexerTestError(err);
        setTestResults((prev) => ({ ...prev, [id]: false }));
        setTestErrorMessages((prev) => ({ ...prev, [id]: message }));
        showToast(`Indexer connection test failed: ${message}`, "error");
      },
    });
  };

  const handleModalTest = () => {
    if (!editing) return;
    setModalTestResult(null);
    testDirectMutation.mutate(editing, {
      onSuccess: (res) => {
        trackIndexerAction(
          "test",
          editing.indexerType || "indexer",
          res.success,
        );
        setModalTestResult(res);
        if (res.capabilities) {
          setEditing((prev) =>
            prev ? { ...prev, capabilities: res.capabilities } : prev,
          );
        }
        if (res.success) {
          showToast("Indexer connection successful", "success");
        } else {
          showToast(
            `Indexer connection failed: ${res.message || "Unknown error"}`,
            "error",
          );
        }
      },
      onError: (err: any) => {
        trackIndexerAction("test", editing.indexerType || "indexer", false);
        const message = formatIndexerTestError(err);
        setModalTestResult({
          success: false,
          message,
        });
        showToast(`Indexer connection failed: ${message}`, "error");
      },
    });
  };

  const handleSaveRule = () => {
    if (!editingRule) return;
    const name = editingRule.name?.trim() || "RSS Rule";
    const minSeeders = Number(editingRule.minSeeders) || 0;
    const minSizeBytes = Number(editingRule.minSizeBytes) || 0;
    const maxSizeBytes = Number(editingRule.maxSizeBytes) || 0;
    const maxAgeDays = Number(editingRule.maxAgeDays) || 0;
    const priority = Number(editingRule.priority) || 0;

    if (
      minSeeders < 0 ||
      minSizeBytes < 0 ||
      maxSizeBytes < 0 ||
      maxAgeDays < 0 ||
      priority < 0
    ) {
      showToast("Numerical constraints cannot be negative", "error");
      return;
    }

    if (maxSizeBytes > 0 && minSizeBytes > maxSizeBytes) {
      showToast("Minimum size cannot be greater than maximum size", "error");
      return;
    }

    const payload: Partial<RssRule> = {
      ...editingRule,
      name,
      isEnabled: editingRule.isEnabled ?? true,
      mustContain: editingRule.mustContain?.trim() || "",
      mustNotContain: editingRule.mustNotContain?.trim() || "",
      minSeeders,
      minSizeBytes,
      maxSizeBytes,
      maxAgeDays,
      priority,
      freeleechOnly: Boolean(editingRule.freeleechOnly),
      categoryId: Number(editingRule.categoryId) || 0,
      indexerIds: editingRule.indexerIds || [],
      tags: editingRule.tags || [],
      tagIds: editingRule.tags || [],
      allowedResolutions: editingRule.allowedResolutions || [],
      allowedSources: editingRule.allowedSources || [],
      allowedCodecs: editingRule.allowedCodecs || [],
      savePath: editingRule.savePath?.trim() || "",
      sequentialDownload: Boolean(editingRule.sequentialDownload),
      initialStatus: editingRule.initialStatus || "Queued",
    };

    if (editingRule.id) {
      updateRuleMutation.mutate(payload as RssRule, {
        onSuccess: () => {
          setEditingRule(null);
          showToast(`RSS Rule "${name}" updated`, "success");
        },
        onError: (err: any) => {
          showToast(err?.message || "Failed to update RSS rule", "error");
        },
      });
    } else {
      createRuleMutation.mutate(payload, {
        onSuccess: () => {
          setEditingRule(null);
          showToast(`RSS Rule "${name}" created`, "success");
        },
        onError: (err: any) => {
          showToast(err?.message || "Failed to create RSS rule", "error");
        },
      });
    }
  };

  const handleSyncProwlarrNow = () => {
    if (syncProwlarrMutation.isPending) return;
    syncProwlarrMutation.mutate(undefined, {
      onSuccess: (res) => {
        trackIndexerAction("sync", "Prowlarr", res.success);
        showToast(
          res.message ||
            `Prowlarr sync complete (${res.added} added, ${res.updated} updated, ${res.removed} removed)`,
          res.success ? "success" : "warning",
        );
      },
      onError: (err: any) => {
        trackIndexerAction("sync", "Prowlarr", false);
        showToast(err?.message || "Prowlarr sync failed", "error");
      },
    });
  };

  const handleSyncRssNow = () => {
    if (syncCooldownRemaining > 0 || syncRssMutation.isPending) return;
    syncRssMutation.mutate(undefined, {
      onSuccess: (res) => {
        setSyncCooldownRemaining(15);
        showToast(
          `RSS sync completed successfully (${res.grabbedCount} releases grabbed)`,
          "success",
        );
      },
      onError: (err: any) => {
        setSyncCooldownRemaining(15);
        showToast(err?.message || "RSS sync failed", "error");
      },
    });
  };

  if (isLoading || isRssRulesLoading)
    return <div className="loading">Loading indexers...</div>;

  return (
    <>
      <SectionCard
        title="Torznab & Newznab Indexers"
        description="Configure Prowlarr, Jackett, or standalone Torznab/Newznab indexers for automated releases"
      >
        <div
          style={{
            display: "flex",
            justifyContent: "flex-end",
            marginBottom: "1rem",
          }}
        >
          <button
            type="button"
            className="btn btn-outline btn-small"
            onClick={handleSyncProwlarrNow}
            disabled={syncProwlarrMutation.isPending}
          >
            {syncProwlarrMutation.isPending
              ? "Syncing from Prowlarr..."
              : "🔄 Sync from Prowlarr"}
          </button>
        </div>

        <div className="provider-cards">
          {indexers?.map((idx) => (
            <div
              key={idx.id}
              className="provider-card"
              onClick={() => {
                setEditing({ ...idx });
                setModalTestResult(null);
              }}
            >
              <div className="provider-card-actions">
                {idx.url && (
                  <a
                    href={idx.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="provider-card-action"
                    title={`Open ${idx.url}`}
                    onClick={(e) => e.stopPropagation()}
                    style={{ textDecoration: "none", color: "inherit" }}
                  >
                    ↗
                  </a>
                )}
                <button
                  className="provider-card-action"
                  title="Test Connection"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleTest(idx.id);
                  }}
                >
                  &#x2713;
                </button>
                <button
                  className="provider-card-action provider-card-action-danger"
                  title="Delete Indexer"
                  onClick={(e) => {
                    e.stopPropagation();
                    if (
                      window.confirm(
                        `Are you sure you want to delete indexer "${idx.name}"?`,
                      )
                    ) {
                      deleteMutation.mutate(idx.id, {
                        onSuccess: () => {
                          trackIndexerAction(
                            "delete",
                            idx.indexerType || "indexer",
                            true,
                          );
                          showToast(`Indexer "${idx.name}" deleted`, "info");
                        },
                        onError: (err) => {
                          trackIndexerAction(
                            "delete",
                            idx.indexerType || "indexer",
                            false,
                          );
                          showToast(
                            err?.message || "Failed to delete indexer",
                            "error",
                          );
                        },
                      });
                    }
                  }}
                >
                  &#x2715;
                </button>
              </div>
              <div className="provider-card-name">{idx.name}</div>
              <div className="provider-card-badges">
                <span className="provider-card-badge provider-card-badge-green">
                  {idx.indexerType}
                </span>
                {idx.enable === false && (
                  <span className="provider-card-badge provider-card-badge-gray">
                    Disabled
                  </span>
                )}
                {idx.enableRss && (
                  <span className="provider-card-badge provider-card-badge-blue">
                    RSS
                  </span>
                )}
                {idx.enableSearch && (
                  <span className="provider-card-badge provider-card-badge-blue">
                    Search
                  </span>
                )}
                {idx.capabilities?.categories &&
                  idx.capabilities.categories.length > 0 && (
                    <span className="provider-card-badge provider-card-badge-gold">
                      {idx.capabilities.categories.length} Discovered Categories
                    </span>
                  )}
              </div>
              <div className="provider-card-info">{idx.url}</div>
              {testResults[idx.id] === true && (
                <div className="provider-card-test provider-card-test-ok">
                  Connection Passed
                </div>
              )}
              {testResults[idx.id] === false && (
                <div
                  className="provider-card-test provider-card-test-fail"
                  title={testErrorMessages[idx.id] || "Connection Failed"}
                >
                  Connection Failed
                  {testErrorMessages[idx.id] && (
                    <div
                      className="provider-card-test-error"
                      style={{
                        fontSize: "0.72rem",
                        marginTop: "0.25rem",
                        color: "var(--danger, #ef4444)",
                        lineHeight: "1.25",
                        wordBreak: "break-word",
                      }}
                    >
                      {testErrorMessages[idx.id]}
                    </div>
                  )}
                </div>
              )}
              {testResults[idx.id] === null && (
                <div className="provider-card-test provider-card-test-pending">
                  Testing...
                </div>
              )}
            </div>
          ))}
          <div
            className="provider-card-add"
            onClick={() => {
              setEditing({ ...defaultIndexer });
              setModalTestResult(null);
            }}
            title="Add Indexer"
          >
            <span className="provider-card-add-icon">+</span>
          </div>
        </div>
      </SectionCard>

      <SectionCard
        title="RSS Automation Rules"
        description="Automate release filtering with regex criteria, seeders, size thresholds, and freeleech filters"
      >
        <div
          style={{
            display: "flex",
            justifyContent: "flex-end",
            marginBottom: "1rem",
          }}
        >
          <button
            type="button"
            className="btn btn-outline btn-small"
            onClick={handleSyncRssNow}
            disabled={syncRssMutation.isPending || syncCooldownRemaining > 0}
          >
            {syncRssMutation.isPending
              ? "Syncing RSS..."
              : syncCooldownRemaining > 0
                ? `🔄 Sync RSS (${syncCooldownRemaining}s)`
                : "🔄 Sync RSS Now"}
          </button>
        </div>

        <div className="provider-cards">
          {[...(rssRules || [])]
            .sort(
              (a, b) => (a.priority ?? 0) - (b.priority ?? 0) || a.id - b.id,
            )
            .map((rule) => (
              <div
                key={rule.id}
                className="provider-card"
                onClick={() => setEditingRule({ ...rule })}
              >
                <div className="provider-card-actions">
                  <button
                    className="provider-card-action provider-card-action-danger"
                    title="Delete RSS Rule"
                    onClick={(e) => {
                      e.stopPropagation();
                      if (
                        window.confirm(
                          `Are you sure you want to delete the RSS rule "${rule.name}"?`,
                        )
                      ) {
                        deleteRuleMutation.mutate(rule.id, {
                          onSuccess: () =>
                            showToast(
                              `RSS Rule "${rule.name}" deleted`,
                              "info",
                            ),
                          onError: (err: any) =>
                            showToast(
                              err?.message || "Failed to delete RSS rule",
                              "error",
                            ),
                        });
                      }
                    }}
                  >
                    &#x2715;
                  </button>
                </div>
                <div className="provider-card-name">{rule.name}</div>
                <div className="provider-card-badges">
                  <span
                    className={`provider-card-badge ${
                      rule.isEnabled
                        ? "provider-card-badge-green"
                        : "provider-card-badge-gray"
                    }`}
                  >
                    {rule.isEnabled ? "Enabled" : "Disabled"}
                  </span>
                  <span className="provider-card-badge provider-card-badge-blue">
                    Priority {rule.priority ?? 0}
                  </span>
                  {rule.minSeeders > 0 && (
                    <span className="provider-card-badge provider-card-badge-blue">
                      ≥ {rule.minSeeders} seeds
                    </span>
                  )}
                  {rule.freeleechOnly && (
                    <span className="provider-card-badge provider-card-badge-gold">
                      Freeleech
                    </span>
                  )}
