                  setEditing({ ...editing, onSeedGoalReached: v })
                }
                hint="Trigger when ratio or seeding time goal is met"
              />
              <Toggle
                label="On Health Issue"
                checked={editing.onHealthIssue}
                onChange={(v) => setEditing({ ...editing, onHealthIssue: v })}
                hint="Trigger on system or tracker health issues"
              />
              <Toggle
                label="On Health Restored"
                checked={editing.onHealthRestored}
                onChange={(v) =>
                  setEditing({ ...editing, onHealthRestored: v })
                }
                hint="Trigger when system health returns to normal"
              />
              <Toggle
                label="On Manual Interaction"
                checked={editing.onManualInteractionRequired}
                onChange={(v) =>
                  setEditing({ ...editing, onManualInteractionRequired: v })
                }
                hint="Trigger when manual user action is required"
              />
              <Toggle
                label="On Media Inspected"
                checked={editing.onMediaInspected}
                onChange={(v) =>
                  setEditing({ ...editing, onMediaInspected: v })
                }
                hint="Trigger when media metadata inspection finishes"
              />
              <Toggle
                label="On Extract Complete"
                checked={editing.onExtractComplete}
                onChange={(v) =>
                  setEditing({ ...editing, onExtractComplete: v })
                }
                hint="Trigger when archive auto-extraction completes"
              />
              <Toggle
                label="On Torrent Deleted"
                checked={editing.onTorrentDeleted}
                onChange={(v) =>
                  setEditing({ ...editing, onTorrentDeleted: v })
                }
                hint="Trigger when a torrent is removed from Seedarr"
              />
              <Toggle
                label="On Application Update"
                checked={editing.onApplicationUpdate}
                onChange={(v) =>
                  setEditing({ ...editing, onApplicationUpdate: v })
                }
                hint="Trigger when Seedarr is updated"
              />
            </div>

            <SectionTitle>Filters</SectionTitle>
            <div className="form-group">
              <label className="form-label">Tags</label>
              <div className="form-input-wrapper">
                <select
                  multiple
                  className="form-select"
                  value={(editing.tags || []).map(String)}
                  onChange={(e) => {
                    const selectedOptions = Array.from(
                      e.target.selectedOptions,
                      (option) => Number(option.value),
                    );
                    setEditing({ ...editing, tags: selectedOptions });
                  }}
                  style={{ borderRadius: "6px", minHeight: "80px" }}
                >
                  {allTags?.map((tag) => (
                    <option key={tag.id} value={tag.id}>
                      {tag.label}
                    </option>
                  ))}
                  {editing.tags
                    ?.filter((tagId) => !allTags?.some((t) => t.id === tagId))
                    .map((tagId) => (
                      <option key={tagId} value={tagId}>
                        Tag #{tagId}
                      </option>
                    ))}
                </select>
                {editing.tags && editing.tags.length > 0 && (
                  <div
                    style={{
                      display: "flex",
                      flexWrap: "wrap",
                      gap: "0.35rem",
                      marginTop: "0.5rem",
                    }}
                  >
                    {editing.tags.map((tagId) => {
                      const tag = allTags?.find((t) => t.id === tagId);
                      return (
                        <span
                          key={tagId}
                          className="badge badge-primary"
                          style={{
                            display: "inline-flex",
                            alignItems: "center",
                            gap: "0.3rem",
                            padding: "0.2rem 0.5rem",
                            fontSize: "0.75rem",
                            cursor: "pointer",
                          }}
                          title="Click to remove tag"
                          onClick={() => {
                            setEditing({
                              ...editing,
                              tags: (editing.tags || []).filter(
                                (id) => id !== tagId,
                              ),
                            });
                          }}
                        >
                          {tag ? tag.label : `Tag #${tagId}`} ✕
                        </span>
                      );
                    })}
                  </div>
                )}
                <span className="form-hint">
                  Only trigger for torrents matching these tags (leave empty to
                  allow all torrents and system events)
                </span>
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">Categories</label>
              <div className="form-input-wrapper">
                <select
                  multiple
                  className="form-select"
                  value={editing.categories || []}
                  onChange={(e) => {
                    const selectedOptions = Array.from(
                      e.target.selectedOptions,
                      (option) => option.value,
                    );
                    setEditing({ ...editing, categories: selectedOptions });
                  }}
                  style={{ borderRadius: "6px", minHeight: "80px" }}
                >
                  {allCategories?.map((cat) => (
                    <option key={cat.id} value={cat.name}>
                      {cat.name}
                    </option>
                  ))}
                  {editing.categories
                    ?.filter(
                      (catName) =>
                        !allCategories?.some((c) => c.name === catName),
                    )
                    .map((catName) => (
                      <option key={catName} value={catName}>
                        {catName}
                      </option>
                    ))}
                </select>
                {editing.categories && editing.categories.length > 0 && (
                  <div
                    style={{
                      display: "flex",
                      flexWrap: "wrap",
                      gap: "0.35rem",
                      marginTop: "0.5rem",
                    }}
                  >
                    {editing.categories.map((catName) => (
                      <span
                        key={catName}
                        className="badge badge-primary"
                        style={{
                          display: "inline-flex",
                          alignItems: "center",
                          gap: "0.3rem",
                          padding: "0.2rem 0.5rem",
                          fontSize: "0.75rem",
                          cursor: "pointer",
                        }}
                        title="Click to remove category"
                        onClick={() => {
                          setEditing({
                            ...editing,
                            categories: (editing.categories || []).filter(
                              (c) => c !== catName,
                            ),
                          });
                        }}
                      >
                        {catName} ✕
                      </span>
                    ))}
                  </div>
                )}
                <span className="form-hint">
                  Only trigger for torrents matching these categories (leave
                  empty to allow all categories)
                </span>
              </div>
            </div>

            {testDirectMutation.isPending && (
              <div
                style={{
                  marginTop: "1rem",
                  padding: "0.75rem 1rem",
                  borderRadius: "6px",
                  fontSize: "0.875rem",
                  backgroundColor: "rgba(200, 168, 78, 0.12)",
                  color: "var(--accent, #c8a84e)",
                  border: "1px solid rgba(200, 168, 78, 0.35)",
                  display: "flex",
                  alignItems: "center",
                  gap: "0.5rem",
                }}
              >
                <span>Testing notification connection...</span>
              </div>
            )}

            {modalTestResult && !testDirectMutation.isPending && (
              <div
                style={{
                  marginTop: "1rem",
                  padding: "0.75rem 1rem",
                  borderRadius: "6px",
                  fontSize: "0.875rem",
                  lineHeight: "1.4",
                  display: "flex",
                  alignItems: "flex-start",
                  gap: "0.65rem",
                  backgroundColor: modalTestResult.success
                    ? "rgba(40, 167, 69, 0.15)"
                    : "rgba(220, 53, 69, 0.15)",
                  color: modalTestResult.success
                    ? "var(--success, #28a745)"
                    : "var(--danger, #dc3545)",
                  border: `1px solid ${
                    modalTestResult.success
                      ? "rgba(40, 167, 69, 0.35)"
                      : "rgba(220, 53, 69, 0.35)"
                  }`,
                }}
              >
                <span
                  style={{
                    fontWeight: "bold",
                    fontSize: "1.1rem",
                    lineHeight: "1",
                  }}
                >
                  {modalTestResult.success ? "✓" : "✕"}
                </span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600 }}>
                    {modalTestResult.success
                      ? "Test notification sent successfully"
                      : "Test notification failed"}
                  </div>
                  {modalTestResult.message && (
                    <div
                      style={{
                        marginTop: "0.25rem",
                        opacity: 0.95,
                        wordBreak: "break-all",
                      }}
                    >
                      {modalTestResult.message}
                    </div>
                  )}
                </div>
              </div>
            )}

            <div
              className="modal-actions"
              style={{
                marginTop: "1.5rem",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <div>
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={handleModalTest}
                  disabled={testDirectMutation.isPending}
                >
                  {testDirectMutation.isPending
                    ? "Testing..."
                    : "Test Connection"}
                </button>
              </div>
              <div style={{ display: "flex", gap: "0.5rem" }}>
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => {
                    setEditing(null);
                    setModalTestResult(null);
                  }}
                >
                  Cancel
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={handleSave}
                  disabled={
                    createMutation.isPending || updateMutation.isPending
                  }
                >
                  {createMutation.isPending || updateMutation.isPending
                    ? "Saving..."
                    : "Save"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {deletingNotif && (
        <div className="modal-overlay" onClick={() => setDeletingNotif(null)}>
          <div
            className="modal"
            onClick={(e) => e.stopPropagation()}
            style={{
              maxWidth: 450,
              borderRadius: "8px",
              boxShadow: "0 16px 40px rgba(0,0,0,0.7)",
              border: "1px solid var(--border-light)",
            }}
          >
            <h3
              className="modal-title"
              style={{ fontSize: "1.15rem", marginBottom: "0.75rem" }}
            >
              Delete Notification Channel
            </h3>
            <p
              style={{
                fontSize: "0.875rem",
                color: "var(--text-secondary)",
                marginBottom: "1.25rem",
                lineHeight: 1.5,
              }}
            >
              Are you sure you want to delete the notification channel "
              {deletingNotif.name}"? This action cannot be undone.
            </p>
            <div
              className="modal-actions"
              style={{
                display: "flex",
                justifyContent: "flex-end",
                gap: "0.5rem",
              }}
            >
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setDeletingNotif(null)}
                disabled={deleteMutation.isPending}
              >
                Cancel
              </button>
              <button
                type="button"
                className="btn btn-danger"
                onClick={handleConfirmDelete}
                disabled={deleteMutation.isPending}
              >
                {deleteMutation.isPending ? "Deleting..." : "Delete"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from "react";
