describe("NumberInput typing, backspace, and bounds behavior (Issue #205)", () => {
  it("does not snap to 0 immediately when clearing input with backspace while typing", () => {
    const calls: number[] = [];
    const inputProps = captureInputProps({
      label: "Max Upload Speed",
      value: 625,
      onChange: (v) => calls.push(v),
      min: 0,
    });

    // User hits backspace to clear the field: internal text becomes ""
    inputProps.onChange({ target: { value: "" } });
    assert.equal(
      calls.length,
      0,
      "Empty string should not trigger onChange immediately while typing",
    );

    // User types "8"
    inputProps.onChange({ target: { value: "8" } });
    assert.deepEqual(calls, [8], "Typing 8 should call onChange(8)");

    // User types "80"
    inputProps.onChange({ target: { value: "80" } });
    assert.deepEqual(
      calls,
      [8, 80],
      "Typing 80 should call onChange(80) without leading 0 snap",
    );

    // User types "8080"
    inputProps.onChange({ target: { value: "8080" } });
    assert.deepEqual(
      calls,
      [8, 80, 8080],
      "Typing 8080 should call onChange(8080)",
    );
  });

  it("clamps empty input to min (or defaultValue) on blur", () => {
    const calls: number[] = [];
    const inputProps = captureInputProps({
      label: "Max Upload Speed",
      value: 625,
      onChange: (v) => calls.push(v),
      min: 0,
    });

    // User clears input
    inputProps.onChange({ target: { value: "" } });
    assert.equal(calls.length, 0);

    // User blurs
    inputProps.onBlur({} as any);
    assert.deepEqual(
      calls,
      [0],
      "Blur on empty input should clamp to min ?? 0 and call onChange",
    );
  });

  it("falls back to defaultValue on blur when provided and input is empty", () => {
    const calls: number[] = [];
    const inputProps = captureInputProps({
      label: "Timeout",
      value: 30,
      onChange: (v) => calls.push(v),
      min: 5,
      max: 120,
      defaultValue: 15,
    });

    inputProps.onChange({ target: { value: "" } });
    assert.equal(calls.length, 0);

    inputProps.onBlur({} as any);
    assert.deepEqual(
      calls,
      [15],
      "Blur on empty input should fall back to defaultValue",
    );
  });

  it("does not call onChange when typing out-of-bounds values, but clamps to bounds on blur", () => {
    const calls: number[] = [];
    const inputProps = captureInputProps({
      label: "Percentage",
      value: 50,
      onChange: (v) => calls.push(v),
      min: 10,
      max: 100,
    });

    // Type below min (5 < 10)
    inputProps.onChange({ target: { value: "5" } });
    assert.equal(
      calls.length,
      0,
      "Typing 5 (< min 10) should not call onChange while typing",
    );

    // Blur clamps 5 to 10
    inputProps.onBlur({} as any);
    assert.deepEqual(calls, [10], "Blur should clamp 5 to min=10");

    // Now type above max (200 > 100)
    inputProps.onChange({ target: { value: "200" } });
    assert.equal(
      calls.length,
      1,
      "Typing 200 (> max 100) should not call onChange while typing",
    );

    // Blur clamps 200 to 100
    inputProps.onBlur({} as any);
    assert.deepEqual(calls, [10, 100], "Blur should clamp 200 to max=100");
  });

  it("allows typing intermediate decimals without premature onChange, calling onChange on valid decimal", () => {
    const calls: number[] = [];
    const inputProps = captureInputProps({
      label: "Global Seed Ratio Limit",
      value: 0,
      onChange: (v) => calls.push(v),
      min: 0,
      step: 0.1,
    });

    // Type "1"
    inputProps.onChange({ target: { value: "1" } });
    assert.deepEqual(calls, [1]);

    // Type "1." (intermediate decimal)
    inputProps.onChange({ target: { value: "1." } });
    assert.deepEqual(
      calls,
      [1],
      "Typing '1.' should not trigger onChange while ending in decimal dot",
    );

    // Type "1.5"
    inputProps.onChange({ target: { value: "1.5" } });
    assert.deepEqual(calls, [1, 1.5], "Typing '1.5' should call onChange(1.5)");

    // Blur maintains 1.5
    inputProps.onBlur({} as any);
    assert.deepEqual(calls, [1, 1.5, 1.5], "Blur maintains 1.5");
  });

  it("clamps intermediate decimal on blur if blurred before adding fractional digits", () => {
    const calls: number[] = [];
    const inputProps = captureInputProps({
      label: "Ratio",
      value: 2,
      onChange: (v) => calls.push(v),
      min: 0,
      step: 0.1,
    });

    // User types "3." and blurs immediately
    inputProps.onChange({ target: { value: "3." } });
    assert.equal(calls.length, 0);

    inputProps.onBlur({} as any);
    assert.deepEqual(calls, [3], "Blur on '3.' should parse and clamp to 3");
  });

  it("handles typing intermediate '-' and clamps appropriately on blur", () => {
    const calls: number[] = [];
    const inputProps = captureInputProps({
      label: "Signed Value",
      value: 0,
      onChange: (v) => calls.push(v),
      min: -50,
      max: 50,
    });

    inputProps.onChange({ target: { value: "-" } });
    assert.equal(
      calls.length,
      0,
      "Typing '-' should not call onChange while typing",
    );

    inputProps.onBlur({} as any);
    assert.deepEqual(
      calls,
      [-50],
      "Blur on '-' should fallback and clamp to min (-50)",
    );
  });
});

import { useState, useCallback, useMemo } from "react";
import { Torrent } from "../../api/types";
import { useTorrentFiles, useRenameTorrentFile } from "../../api/hooks";
import { formatBytes } from "../../utils/formatters";
import { SkeletonLine } from "../../components/Skeleton";
import { MediaPlayerModal } from "../../components/MediaPlayerModal";
import { isPlayableFile, isAudioFile } from "../../utils/mediaPlayer";
import {
  FileTreeNode,
  FilePriority,
  buildFileTree,
  getDescendantFileIds,
  getDirectoryPriority,
  getDirectoryWanted,
  formatPriority,
} from "../../utils/fileTree";

function FileTreeRow({
  node,
  depth,
  expanded,
  onToggle,
  onDirectoryPriority,
  onFilePriority,
  onDirectoryWanted,
  onFileWanted,
  filePriorities,
  fileWanted,
  onPlayMedia,
  editingPath,
  editingValue,
  onStartRename,
  onSaveRename,
  onCancelRename,
  onChangeRenameValue,
  isRenaming,
}: {
  node: FileTreeNode;
  depth: number;
  expanded: Set<string>;
  onToggle: (path: string) => void;
  onDirectoryPriority: (node: FileTreeNode, priority: FilePriority) => void;
  onFilePriority: (fileId: number, priority: FilePriority) => void;
  onDirectoryWanted: (node: FileTreeNode, wanted: boolean) => void;
  onFileWanted: (fileId: number, wanted: boolean) => void;
  filePriorities: Record<number, FilePriority>;
  fileWanted: Record<number, boolean>;
  onPlayMedia: (file: {
    id: number;
    path: string;
    name: string;
    size: number;
  }) => void;
  editingPath: string | null;
  editingValue: string;
  onStartRename: (path: string, currentName: string) => void;
  onSaveRename: (oldPath: string, newName: string) => void;
  onCancelRename: () => void;
  onChangeRenameValue: (val: string) => void;
  isRenaming: boolean;
}) {
  const isOpen = expanded.has(node.path);
  const indent = depth * 20;
  const dirPriority = node.isDir
    ? getDirectoryPriority(node, filePriorities)
    : "Normal";
  const filePrio =
    !node.isDir && node.fileId !== undefined
      ? (filePriorities[node.fileId] ?? node.priority ?? "Normal")
      : "Normal";
  const dirWanted = node.isDir
    ? getDirectoryWanted(node, fileWanted, filePriorities)
    : { isWanted: true, isIndeterminate: false };
  const isWanted =
    !node.isDir && node.fileId !== undefined
      ? (fileWanted[node.fileId] ??
        node.wanted ??
        formatPriority(filePrio) !== "Do Not Download")
      : true;
  const progressValue = node.progress ?? 100;
  const playable =
    !node.isDir && node.fileId !== undefined && isPlayableFile(node.name);

  return (
    <>
      <tr
        className="torrent-table-row"
        style={{ cursor: node.isDir ? "pointer" : "default" }}
        onClick={() => node.isDir && onToggle(node.path)}
      >
        <td
          onClick={(e) => e.stopPropagation()}
          style={{ width: 60, textAlign: "center" }}
        >
          {node.isDir ? (
            <input
              type="checkbox"
              aria-label={`Wanted for folder ${node.name}`}
              checked={dirWanted.isWanted}
              ref={(el) => {
                if (el) {
                  el.indeterminate = dirWanted.isIndeterminate;
                }
              }}
              onChange={(e) => onDirectoryWanted(node, e.target.checked)}
              style={{ cursor: "pointer" }}
            />
          ) : (
            <input
              type="checkbox"
              aria-label={`Wanted for file ${node.name}`}
              checked={isWanted}
              onChange={(e) =>
                node.fileId !== undefined &&
                onFileWanted(node.fileId, e.target.checked)
              }
              style={{ cursor: "pointer" }}
            />
          )}
        </td>
        <td className="mono" style={{ paddingLeft: indent + 8 }}>
          {node.isDir ? (
            <span
              style={{ display: "inline-flex", alignItems: "center", gap: 4 }}
            >
              <span style={{ fontSize: 10, width: 12, textAlign: "center" }}>
                {isOpen ? "▼" : "▶"}
              </span>
              <span style={{ opacity: 0.7 }}>📁</span> {node.name}/
            </span>
          ) : editingPath === node.path ? (
            <div
              onClick={(e) => e.stopPropagation()}
              style={{ display: "inline-flex", alignItems: "center", gap: 4 }}
            >
              <span style={{ width: 12 }} />
              <span style={{ opacity: 0.7 }}>
                {playable ? (isAudioFile(node.name) ? "🎵" : "🎬") : "📄"}
              </span>
              <input
                type="text"
                className="form-control"
                aria-label={`Rename ${node.name}`}
                value={editingValue}
                onChange={(e) => onChangeRenameValue(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    onSaveRename(node.path, editingValue);
                  } else if (e.key === "Escape") {
                    onCancelRename();
                  }
                }}
                disabled={isRenaming}
                autoFocus
                style={{
                  fontSize: "0.8rem",
                  padding: "0.15rem 0.35rem",
                  height: "auto",
                  minWidth: 160,
                }}
              />
              <button
                type="button"
                className="btn btn-xs btn-primary"
                aria-label="Save rename"
                title="Save rename"
                disabled={isRenaming || !editingValue.trim()}
                onClick={() => onSaveRename(node.path, editingValue)}
                style={{
                  padding: "0.15rem 0.45rem",
                  fontSize: "0.75rem",
                  cursor: "pointer",
                }}
              >
                {isRenaming ? "..." : "✓"}
              </button>
              <button
                type="button"
                className="btn btn-xs btn-default"
                aria-label="Cancel rename"
                title="Cancel rename"
                disabled={isRenaming}
                onClick={onCancelRename}
                style={{
                  padding: "0.15rem 0.45rem",
                  fontSize: "0.75rem",
                  cursor: "pointer",
                }}
              >
                ✕
              </button>
            </div>
          ) : (
            <span
              style={{ display: "inline-flex", alignItems: "center", gap: 4 }}
            >
              <span style={{ width: 12 }} />
              <span style={{ opacity: 0.7 }}>
                {playable ? (isAudioFile(node.name) ? "🎵" : "🎬") : "📄"}
              </span>{" "}
              {playable ? (
                <button
                  type="button"
                  className="btn-link"
                  aria-label={`Play ${node.name}`}
                  onClick={(e) => {
                    e.stopPropagation();
                    onPlayMedia({
                      id: node.fileId!,
                      path: node.path,
                      name: node.name,
                      size: node.size,
                    });
                  }}
                  style={{
                    background: "none",
                    border: "none",
                    padding: 0,
                    color: "var(--accent-color, #3498db)",
                    textDecoration: "underline",
                    cursor: "pointer",
                    fontFamily: "inherit",
                    fontSize: "inherit",
                    textAlign: "left",
                  }}
                >
                  {node.name}
                </button>
              ) : (
                node.name
              )}
            </span>
          )}
        </td>
        <td>{formatBytes(node.size)}</td>
        <td>
          {!node.isDir ? (
            <div
              style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}
            >
              <div
                style={{
                  flex: 1,
                  minWidth: 40,
                  maxWidth: 70,
                  height: 6,
                  backgroundColor: "rgba(255, 255, 255, 0.1)",
                  borderRadius: 3,
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    width: `${progressValue}%`,
                    height: "100%",
                    backgroundColor:
                      progressValue >= 100 ? "#2ecc71" : "#3498db",
                  }}
                />
              </div>
              <span style={{ fontSize: "0.75rem", minWidth: 38 }}>
                {progressValue.toFixed(1)}%
              </span>
            </div>
          ) : (
            <span
              style={{ fontSize: "0.75rem", color: "var(--text-muted, #888)" }}
            >
              —
            </span>
          )}
        </td>
        <td>
          <div
            onClick={(e) => e.stopPropagation()}
            style={{ display: "inline-flex", alignItems: "center", gap: 4 }}
          >
            {node.isDir ? (
              <select
                aria-label={`Priority for folder ${node.name}`}
                className="form-control"
                style={{
                  fontSize: "0.75rem",
                  padding: "0.15rem 0.35rem",
                  height: "auto",
                  width: "auto",
                  cursor: "pointer",
                }}
                value={dirPriority}
                onChange={(e) =>
                  onDirectoryPriority(node, e.target.value as FilePriority)
                }
              >
                <option value="Normal">Normal</option>
                <option value="High">High</option>
                <option value="Do Not Download">Skip All</option>
                {dirPriority === "Mixed" && (
                  <option value="Mixed" disabled>
                    Mixed
                  </option>
                )}
              </select>
            ) : (
              <select
                aria-label={`Priority for file ${node.name}`}
                className="form-control"
                style={{
                  fontSize: "0.75rem",
                  padding: "0.15rem 0.35rem",
                  height: "auto",
                  width: "auto",
                  cursor: "pointer",
                }}
                value={formatPriority(filePrio)}
                onChange={(e) =>
                  node.fileId !== undefined &&
                  onFilePriority(node.fileId, e.target.value as FilePriority)
                }
              >
                <option value="Normal">Normal</option>
                <option value="High">High</option>
                <option value="Do Not Download">Do Not Download</option>
              </select>
            )}
          </div>
        </td>
        <td
          style={{ textAlign: "center" }}
          onClick={(e) => e.stopPropagation()}
        >
          <div
            style={{
              display: "inline-flex",
