describe("TorrentToolbar accessibility attributes", () => {
  const mockSeedingConfig: Partial<SeedingConfig> = {
    maxUploadSpeedKbps: 1024,
    maxDownloadSpeedKbps: 2048,
  };

  const defaultProps = {
    count: 10,
    totalUploadSpeed: 512,
    totalDownloadSpeed: 1024,
    seedingConfig: mockSeedingConfig as SeedingConfig,
    adjustSpeed: () => {},
    filter: "",
    onFilterChange: () => {},
    viewMode: "table" as const,
    onViewModeChange: () => {},
    onAddTorrent: () => {},
    onStartAll: () => {},
    onStopAll: () => {},
    selectedCount: 0,
    bulkPending: false,
    onBulkStart: () => {},
    onBulkStop: () => {},
    onBulkDelete: () => {},
    onBulkClear: () => {},
  };

  it("renders speed adjustment buttons with descriptive aria-label attributes and limit labels", () => {
    const html = renderToolbar(defaultProps);

    assert.ok(
      html.includes("UL Limit:"),
      "Upload limit label must be rendered",
    );
    assert.ok(
      html.includes("DL Limit:"),
      "Download limit label must be rendered",
    );
    assert.ok(
      !html.includes("UL: 512") && !html.includes("UL: 512 B/s"),
      "Live upload speed must not be rendered in toolbar",
    );
    assert.ok(
      html.includes('aria-label="Double upload speed limit"'),
      "Double upload speed button must have descriptive aria-label",
    );
    assert.ok(
      html.includes('aria-label="Halve upload speed limit"'),
      "Halve upload speed button must have descriptive aria-label",
    );
    assert.ok(
      html.includes('aria-label="Double download speed limit"'),
      "Double download speed button must have descriptive aria-label",
    );
    assert.ok(
      html.includes('aria-label="Halve download speed limit"'),
      "Halve download speed button must have descriptive aria-label",
    );
  });

  it("renders filter search input with accessible aria-label", () => {
    const html = renderToolbar(defaultProps);

    assert.ok(
      html.includes('aria-label="Filter torrents"') ||
        html.includes('aria-label="Filter torrents..."'),
      "Filter input must have accessible aria-label",
    );
    assert.ok(
      html.includes('class="search-input"'),
      "Search input element must be rendered",
    );
  });

  it("reflects correct aria-pressed state on view mode toggle buttons for table mode", () => {
    const html = renderToolbar({
      ...defaultProps,
      viewMode: "table",
    });

    // Table view button should be aria-pressed=true, Grid view button aria-pressed=false
    assert.ok(
      html.includes('title="Table view" aria-pressed="true"') ||
        html.includes('aria-pressed="true" title="Table view"') ||
        (html.includes('title="Table view"') &&
          html.includes('aria-pressed="true"')),
      "Table view button should have aria-pressed=true",
    );
    assert.ok(
      html.includes('title="Grid view" aria-pressed="false"') ||
        html.includes('aria-pressed="false" title="Grid view"') ||
        (html.includes('title="Grid view"') &&
          html.includes('aria-pressed="false"')),
      "Grid view button should have aria-pressed=false",
    );
  });

  it("reflects correct aria-pressed state on view mode toggle buttons for grid mode", () => {
    const html = renderToolbar({
      ...defaultProps,
      viewMode: "grid",
    });

    // In grid mode: Grid view button aria-pressed=true, Table view button aria-pressed=false
    const tableMatch = html.match(/<button[^>]*title="Table view"[^>]*>/);
    assert.ok(tableMatch, "Table button found");
    assert.ok(
      tableMatch[0].includes('aria-pressed="false"'),
      "Table button should be aria-pressed=false",
    );

    const gridMatch = html.match(/<button[^>]*title="Grid view"[^>]*>/);
    assert.ok(gridMatch, "Grid button found");
    assert.ok(
      gridMatch[0].includes('aria-pressed="true"'),
      "Grid button should be aria-pressed=true",
    );
  });

  it("renders bulk tag assignment and removal buttons when selectedCount > 0", () => {
    const html = renderToolbar({
      ...defaultProps,
      selectedCount: 3,
      onBulkAddTags: () => {},
      onBulkRemoveTags: () => {},
    });

    assert.ok(
      html.includes("bulk-add-tags-btn"),
      "Assign tags button must be rendered in bulk actions",
    );
    assert.ok(
      html.includes("bulk-remove-tags-btn"),
      "Remove tags button must be rendered in bulk actions",
    );
    assert.ok(
      html.includes("Assign Tags"),
      "Assign Tags text should be present",
    );
    assert.ok(
      html.includes("Remove Tags"),
      "Remove Tags text should be present",
    );
  });

  it("does not render bulk Force Recheck button", () => {
    const html = renderToolbar({
      ...defaultProps,
      selectedCount: 2,
    });

    assert.ok(
      !html.includes("bulk-recheck-btn"),
      "Force Recheck button must not be rendered in bulk actions",
    );
  });
});

import { useState, useMemo } from "react";
import {
  useInspectTorrentTrackers,
  useInspectHashTrackers,
  useBoostTorrent,
  useBoostHash,
  useInjectTrackerToTorrent,
  useBoostAllTorrents,
  useHarvestDownloadTrackers,
  useScanTrackerBoostTrackers,
} from "../../api/hooks";
import { formatBytes, formatRatio } from "../../utils/formatters";
import { useToast } from "../../context/ToastContext";
import TrackerFavicon from "../../components/TrackerFavicon";
import { useTranslation } from "../../i18n";
import type { UnifiedDownloadItem } from "./types";

export interface HarvesterPanelProps {
  unifiedItems: UnifiedDownloadItem[];
  torrentsLoading?: boolean;
  selectedKey: string | null;
  onSelectKey: (key: string) => void;
}

export function HarvesterPanel({
  unifiedItems,
  torrentsLoading,
  selectedKey,
  onSelectKey,
}: HarvesterPanelProps) {
  const { t } = useTranslation();
  const { showToast } = useToast();

  const [downloadFilter, setDownloadFilter] = useState<
    "all" | "public" | "private" | "real" | "seedarr"
  >("all");
  const [downloadSearch, setDownloadSearch] = useState("");

  const scanTrackers = useScanTrackerBoostTrackers();
  const harvestDownloads = useHarvestDownloadTrackers();
  const boostTorrent = useBoostTorrent();
  const boostHash = useBoostHash();
  const injectTracker = useInjectTrackerToTorrent();
  const boostAll = useBoostAllTorrents();

  const filteredDownloads = useMemo(() => {
    return unifiedItems.filter((item) => {
      if (downloadFilter === "public" && item.isPrivate) return false;
      if (downloadFilter === "private" && !item.isPrivate) return false;
      if (downloadFilter === "real" && item.sourceType !== "real_client")
        return false;
      if (downloadFilter === "seedarr" && item.sourceType !== "seedarr")
        return false;
      if (downloadSearch.trim()) {
        const q = downloadSearch.toLowerCase();
        const name = (item.name || "").toLowerCase();
        const hash = (item.infoHash || "").toLowerCase();
        if (!name.includes(q) && !hash.includes(q)) {
          return false;
        }
      }
      return true;
    });
  }, [unifiedItems, downloadFilter, downloadSearch]);

  const activeSelectedKey = selectedKey ?? filteredDownloads[0]?.key ?? "";
  const selectedItem = useMemo(() => {
    return filteredDownloads.find((i) => i.key === activeSelectedKey);
  }, [filteredDownloads, activeSelectedKey]);

  // Inspection hooks with live hash scraping
  const {
    data: torrentInspection,
    isLoading: torrentInspectLoading,
    refetch: refetchTorrentInspect,
  } = useInspectTorrentTrackers(
    selectedItem?.id ?? 0,
    Boolean(selectedItem?.id && selectedItem.id > 0),
  );

  const {
    data: hashInspection,
    isLoading: hashInspectLoading,
    refetch: refetchHashInspect,
  } = useInspectHashTrackers(
    selectedItem?.infoHash ?? "",
    selectedItem?.name ?? "",
    Boolean(!selectedItem?.id && selectedItem?.infoHash),
  );

  const inspection = selectedItem?.id ? torrentInspection : hashInspection;
  const inspectionLoading = selectedItem?.id
    ? torrentInspectLoading
    : hashInspectLoading;

  const handleScanAll = () => {
    scanTrackers.mutate(undefined, {
      onSuccess: (res) => {
        showToast(
          t(
            "trackerBoost.probedEndpointsSuccess",
            "Probed {count} tracker endpoints",
            { count: res.testedCount },
          ),
          "success",
        );
      },
      onError: (err) => {
        showToast(
          t(
            "trackerBoost.probeTrackersFailed",
            "Failed to probe trackers: {error}",
            { error: err.message },
          ),
          "error",
        );
      },
    });
  };

  const handleHarvestDownloads = () => {
    harvestDownloads.mutate(undefined, {
      onSuccess: (res) => {
        showToast(
          t(
            "trackerBoost.harvestedTrackersSuccess",
            "Harvested {count} new trackers from active downloads",
            { count: res.harvestedCount },
          ),
          "success",
        );
      },
      onError: (err) => {
        showToast(
          t(
            "trackerBoost.harvestFailed",
            "Failed to harvest from downloads: {error}",
            { error: err.message },
          ),
          "error",
        );
      },
    });
  };

  const handleBoostItem = (item: UnifiedDownloadItem) => {
    if (item.id && item.id > 0) {
      boostTorrent.mutate(item.id, {
        onSuccess: (res) => {
          showToast(res.message, res.boosted ? "success" : "info");
        },
        onError: (err) => {
          showToast(
            t("trackerBoost.boostFailed", "Failed to boost: {error}", {
              error: err.message,
            }),
            "error",
          );
        },
      });
    } else if (item.infoHash) {
      boostHash.mutate(
        { infoHash: item.infoHash, name: item.name },
        {
          onSuccess: (res) => {
            showToast(res.message, res.boosted ? "success" : "info");
          },
          onError: (err) => {
            showToast(
              t("trackerBoost.boostFailed", "Failed to boost: {error}", {
                error: err.message,
              }),
              "error",
            );
          },
        },
      );
    }
  };

  const handleInjectSingle = (trackerUrl: string) => {
    if (!selectedItem) return;

    injectTracker.mutate(
      {
        torrentId: selectedItem.id,
        infoHash: selectedItem.infoHash,
        trackerUrl,
      },
      {
        onSuccess: (res) => {
          showToast(res.message, "success");
        },
        onError: (err) => {
          showToast(
            t(
              "trackerBoost.injectFailed",
              "Failed to inject tracker: {error}",
              { error: err.message },
            ),
            "error",
          );
        },
      },
    );
  };

  const handleBoostAll = () => {
    boostAll.mutate(undefined, {
      onSuccess: (resList) => {
        const totalAdded = resList.reduce(
          (sum, r) => sum + r.addedTrackersCount,
          0,
        );
        const totalSeeds = resList.reduce(
          (sum, r) => sum + r.totalSeedersFound,
          0,
        );
        showToast(
          t(
            "trackerBoost.boostAllSuccess",
            "Boosted {swarms} swarms: injected {trackers} verified trackers (+{seeds} seeds discovered)",
            {
              swarms: resList.length,
              trackers: totalAdded,
              seeds: totalSeeds,
            },
          ),
          "success",
        );
      },
      onError: (err) => {
        showToast(
          t(
            "trackerBoost.boostDownloadsFailed",
            "Failed to boost downloads: {error}",
            { error: err.message },
          ),
          "error",
        );
      },
    });
  };

  return (
    <div
      style={{
        flex: "1 1 auto",
        display: "flex",
        flexDirection: "column",
        minHeight: 0,
        marginBottom: "0.5rem",
      }}
    >
      {/* Action Toolbar */}
      <div
        className="card"
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: "1rem",
          marginBottom: "1.25rem",
          padding: "0.75rem 1rem",
          borderRadius: "8px",
        }}
      >
        <div
          style={{
            display: "flex",
            gap: "0.6rem",
            alignItems: "center",
            flexWrap: "wrap",
          }}
        >
          <button
            className="btn btn-primary"
            onClick={handleBoostAll}
            disabled={boostAll.isPending || filteredDownloads.length === 0}
            title={t(
              "trackerBoost.scrapeAllTooltip",
              "Scrape candidate trackers and inject only verified positive matches across all active downloads",
            )}
            style={{ padding: "0.45rem 1rem", fontWeight: 600 }}
          >
            {boostAll.isPending
              ? t("trackerBoost.scrapingBoosting", "⚡ Scraping & Boosting...")
              : t(
                  "trackerBoost.boostAllDownloads",
                  "⚡ Boost All Downloads (Verified Only)",
                )}
          </button>

          <button
            className="btn btn-action"
